window.SB_CATTEXT = {"lock": {"status": "befintlig", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/brunnslock", "name": "Lätta Brunnslock", "use": "text+faq"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/luckor", "name": "Luckor", "use": "ingen text"}], "words": 83, "faqWords": 539, "check": "Nykyinen teksti koskee vain kevyitä kansia; uusi pääkategoria sisältää myös luukut. SB: lisätäänkö yksi lause luukuista? FAQ on lähes sama kuin Lätta brunnslock -sivulla.", "sv": {"intro": "Enligt Arbetsmiljöverkets regler får ett brunnslock i betong inte väga mer än 25 kg. Våra lätta brunnslock väger endast några kilo, men är lika hållbara och säkra som traditionella, tyngre brunnslock.", "introDraft": false, "blocks": [{"t": "h3", "x": "Lätta brunnslock som är barnsäkra och låsbara"}, {"t": "p", "x": "De används till olika typer av brunnar, såsom avloppsbrunnar, inspektionsbrunnar, vattenbrunnar och mätarbrunnar med flera."}, {"t": "p", "x": "Är ni osäkra på vilken storlek av brunnslock som passar er brunn, tveka inte att kontakta oss. Vi hjälper gärna till. Antingen via vårt Kontaktformulär eller på telefon 0920-520056"}], "faq": [{"q": "Vad är ett lätt brunnslock och varför ska jag välja det?", "a": ["Ett lätt brunnslock tillverkas i komposit, polyeten (PE) eller glasfiber och väger 3-12 kg jämfört med ett betonglock 60-120 kg. Det uppfyller Arbetsmiljöverkets krav på att ett brunnslock inte får väga mer än 25 kg vid manuell hantering. Du får samma hållbarhet och säkerhet som ett tungt betonglock, men kan öppna det själv vid inspektion eller slamtömning."]}, {"q": "Vilka storlekar finns lätta brunnslock i?", "a": ["Vi har lätta brunnslock i storlekarna 590, 660, 750, 780, 790, 900, 930, 1000, 1050, 1150 och 1340 mm. De passar betongbrunnar med utvändigt mått 500-1 450 mm och invändigt mått 451-1 290 mm. Använd filtreringen ovan för att hitta rätt storlek baserat på din brunns mått."]}, {"q": "Hur tungt får ett lätt brunnslock vara?", "a": ["Enligt Arbetsmiljöverkets föreskrifter (AFS 2012:2) bör manuell hantering av tunga lock undvikas. Ett brunnslock i betong väger normalt 60-120 kg och kräver lyfthjälpmedel. Våra lätta brunnslock väger 3-12 kg och kan öppnas av en person utan verktyg eller lyfthjälp."]}, {"q": "Vilken bärighet ska jag välja, A15, B125, C250 eller D400?", "a": ["Bärigheten anges i belastningsklass enligt EN 124. A15 (1,5 ton) passar grönområden och gångytor utan biltrafik. B125 (12,5 ton) passar gårdsplan, garageinfart och parkering för personbil. C250 (25 ton) passar mindre lastbilstrafik och industriområden. D400 (40 ton) är vår högsta klass och klarar tung lastbilstrafik på gata och industriinfart."]}, {"q": "Passar lätta brunnslock till min trekammarbrunn?", "a": ["Ja. Lätta brunnslock passar alla vanliga trekammarbrunnar och slamavskiljare i betong med rund öppning mellan 500 och 1 450 mm. De vanligaste storlekarna för trekammarbrunn är 600, 900 och 1 000 mm. Behöver du även en tätningsring för att stoppa lukt och insekter hittar du det i samma kategoriträd."]}, {"q": "Är lätta brunnslock barnsäkra och låsbara?", "a": ["Ja. Samtliga lätta brunnslock i vårt sortiment har en låsfunktion som hindrar barn och obehöriga från att öppna locket. Våra körbara modeller uppfyller säkerhetsstandard EN 124 och är godkända för montering i offentlig och privat miljö."]}, {"q": "Hur monterar jag ett lätt brunnslock på en betongbrunn?", "a": ["Locket placeras direkt på betongringens överkant. För täthet mot vatten, lukt och insekter rekommenderar vi att en tätningsring monteras mellan betongringen och locket. Behöver du höja brunnen till markens nivå används en förhöjningsring i betong. Vid trafikerad yta gjuts en bärlast-ram runt locket."]}, {"q": "Vad kostar ett lätt brunnslock?", "a": ["Priset varierar med storlek, bärighet och material. Mindre composite-lock för avloppsbrunn (590-780 mm) kostar 1 749-2 895 kr. Körbara lock i klass B125 (900 mm) kostar från 7 722 kr. Lätt körbart lock 1 000 mm i klass D400 (40 ton) kostar 17 690 kr. Jämfört med tunga gjutjärnsbetäckningar är priset jämförbart eller lägre, med betydligt lättare hantering."]}, {"q": "Hur skiljer sig ert lätta brunnslock från Byggmax, Biltema och Jula?", "a": ["Våra körbara lock (klass B125 och uppåt) är CE-märkta och certifierade enligt EN 124 för bärighet upp till klass D400 (40 ton). I klass A15 är vissa modeller certifierade enligt EN 124. Hela sortimentet är tillverkat för professionellt bruk. Vi har också större storlekar (upp till 1 340 mm) som inte finns hos byggvaruhusen. Behöver du ett lock som klarar lastbilstrafik eller en specifik storlek över 800 mm är vårt sortiment den primära kanalen i Sverige."]}]}, "fi": {"intro": "Ruotsin työsuojeluviranomaisen (Arbetsmiljöverket) sääntöjen mukaan betonisen kaivonkannen paino saa olla enintään 25 kg. Kevyet kaivonkantemme painavat vain muutaman kilon, mutta ne ovat yhtä kestäviä ja turvallisia kuin perinteiset, painavammat kaivonkannet.", "introDraft": false, "h": "Tietoa kaivonkansista ja luukuista", "blocks": [{"t": "h3", "x": "Kevyet kaivonkannet, jotka ovat lapsiturvallisia ja lukittavia"}, {"t": "p", "x": "Niitä käytetään erityyppisissä kaivoissa, kuten jätevesikaivoissa, tarkastuskaivoissa, vesikaivoissa, mittarikaivoissa ja muissa."}, {"t": "p", "x": "Jos olette epävarmoja siitä, minkä kokoinen kaivonkansi sopii kaivoonne, ottakaa rohkeasti yhteyttä. Autamme mielellämme. Joko yhteydenottolomakkeemme kautta tai puhelimitse numerossa 0920-520056"}], "faq": [{"q": "Mikä on kevyt kaivonkansi ja miksi minun kannattaa valita se?", "a": ["Kevyt kaivonkansi valmistetaan komposiitista, polyeteenistä (PE) tai lasikuidusta, ja se painaa 3-12 kg, kun betonikansi painaa 60-120 kg. Se täyttää Arbetsmiljöverketin vaatimuksen, jonka mukaan kaivonkansi saa käsin käsiteltäessä painaa enintään 25 kg. Saat saman kestävyyden ja turvallisuuden kuin painavalla betonikannella, mutta voit avata kannen itse tarkastuksen tai lietteen tyhjennyksen yhteydessä."]}, {"q": "Missä kooissa kevyitä kaivonkansia on saatavana?", "a": ["Meillä on kevyitä kaivonkansia kokoina 590, 660, 750, 780, 790, 900, 930, 1000, 1050, 1150 ja 1340 mm. Ne sopivat betonikaivoihin, joiden ulkomitta on 500-1 450 mm ja sisämitta 451-1 290 mm. Käytä yllä olevaa suodatusta löytääksesi oikean koon kaivosi mittojen perusteella."]}, {"q": "Kuinka painava kevyt kaivonkansi saa olla?", "a": ["Arbetsmiljöverketin määräysten (AFS 2012:2) mukaan painavien kansien käsittelyä käsin tulisi välttää. Betoninen kaivonkansi painaa tavallisesti 60-120 kg ja vaatii nostoapuvälineen. Kevyet kaivonkantemme painavat 3-12 kg, ja yksi henkilö voi avata ne ilman työkaluja tai nostoapua."]}, {"q": "Mikä kantavuus minun pitäisi valita, A15, B125, C250 vai D400?", "a": ["Kantavuus ilmoitetaan kuormitusluokkana EN 124 -standardin mukaisesti. A15 (1,5 tonnia) sopii viheralueille ja kävelypinnoille, joilla ei ole autoliikennettä. B125 (12,5 tonnia) sopii piha-alueille, autotallin ajoliittymiin ja henkilöautojen pysäköintiin. C250 (25 tonnia) sopii vähäiselle kuorma-autoliikenteelle ja teollisuusalueille. D400 (40 tonnia) on korkein luokkamme, ja se kestää raskasta kuorma-autoliikennettä kaduilla ja teollisuusalueiden ajoliittymissä."]}, {"q": "Sopivatko kevyet kaivonkannet kolmikammiokaivooni?", "a": ["Kyllä. Kevyet kaivonkannet sopivat kaikkiin tavallisiin betonisiin kolmikammiokaivoihin ja saostuskaivoihin, joiden pyöreä aukko on 500 ja 1 450 mm:n välillä. Kolmikammiokaivon yleisimmät koot ovat 600, 900 ja 1 000 mm. Jos tarvitset myös tiivisterenkaan hajujen ja hyönteisten estämiseksi, löydät sen samasta kategoriapuusta."]}, {"q": "Ovatko kevyet kaivonkannet lapsiturvallisia ja lukittavia?", "a": ["Kyllä. Kaikissa valikoimamme kevyissä kaivonkansissa on lukitustoiminto, joka estää lapsia ja asiattomia avaamasta kantta. Ajettavat mallimme täyttävät EN 124 -turvallisuusstandardin, ja ne on hyväksytty asennettaviksi julkisiin ja yksityisiin ympäristöihin."]}, {"q": "Miten asennan kevyen kaivonkannen betonikaivoon?", "a": ["Kansi asetetaan suoraan betonirenkaan yläreunalle. Tiiviyden varmistamiseksi vettä, hajuja ja hyönteisiä vastaan suosittelemme asentamaan tiivisterenkaan betonirenkaan ja kannen väliin. Jos kaivoa pitää korottaa maanpinnan tasolle, käytetään betonista korotusrengasta. Liikennöidyllä pinnalla kannen ympärille valetaan kuormaa kantava kehys."]}, {"q": "Mitä kevyt kaivonkansi maksaa?", "a": ["Hinta vaihtelee koon, kantavuuden ja materiaalin mukaan. Pienemmät komposiittikannet jätevesikaivoon (590-780 mm) maksavat 1 749-2 895 kr. Ajettavat kannet luokassa B125 (900 mm) maksavat alkaen 7 722 kr. Kevyt ajettava kansi 1 000 mm luokassa D400 (40 tonnia) maksaa 17 690 kr. Painaviin valurautakansistoihin verrattuna hinta on samaa tasoa tai alhaisempi, ja käsittely on huomattavasti kevyempää."]}, {"q": "Miten kevyt kaivonkantenne eroaa kansista, joita myyvät Byggmax, Biltema ja Jula?", "a": ["Ajettavat kantemme (luokka B125 ja sitä korkeammat) ovat CE-merkittyjä ja sertifioitu EN 124 -standardin mukaisesti kantavuudeltaan luokkaan D400 (40 tonnia) asti. Luokassa A15 osa malleista on sertifioitu EN 124 -standardin mukaisesti. Koko valikoima on valmistettu ammattikäyttöön. Meillä on myös suurempia kokoja (enintään 1 340 mm), joita rautakaupoista ei löydy. Jos tarvitset kannen, joka kestää kuorma-autoliikennettä, tai tietyn yli 800 mm:n koon, valikoimamme on ensisijainen kanava Ruotsissa."]}]}}, "lock/latta": {"status": "kombinerad", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/brunnslock/latta-brunnslock-for-betongbrunnar", "name": "Lätta brunnslock för betongbrunnar", "use": "text+faq"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/brunnslock/betongring-med-latt-brunnslock", "name": "Betongring med lätt brunnslock", "use": "faq"}], "words": 272, "faqWords": 673, "check": "Väitteet \"certifierade enligt EN 124\" ja mallikoot (590 ... 1340 mm) tarkistettava uutta valikoimaa vastaan.", "sv": {"intro": "Lätta brunnslock för betongbrunnar i composite, polyeten och gjutjärn, körbara modeller upp till 40 ton, barnsäkra och låsbara. Våra lock väger under 25 kg enligt Arbetsmiljöverkets regler och passar alla vanliga betongbrunnar mellan 500 och 1 450 mm.", "introDraft": false, "blocks": [{"t": "p", "x": "Här hittar du både plana brunnslock för avloppsbrunn, trekammarbrunn och vattenmätarbrunn, och förstärkta körbara lock för infart, gårdsplan och industriområde."}, {"t": "p", "x": "Behöver du hjälp att välja rätt storlek? Mät ditt invändiga eller utvändiga mått på betongringen och filtrera nedan, eller ring oss på 0920-520056 så hjälper vi dig att matcha rätt lock till din brunn."}, {"t": "h3", "x": "Varför välja ett lätt brunnslock?"}, {"t": "p", "x": "Ett traditionellt betonglock väger ofta 60-120 kg, vilket gör det tungt att lyfta vid inspektion och slamtömning. Lätta brunnslock i composite eller PE väger 3-12 kg och uppfyller Arbetsmiljöverkets 25 kg-gräns för manuell hantering. De har samma bärighet som tunga betonglock, från 1,5 ton för grönområden till 40 ton (klass D400) för körbara ytor, men kan öppnas av en person utan lyfthjälpmedel."}, {"t": "h4", "x": "Lätt brunnslock för trekammarbrunn och avloppsbrunn"}, {"t": "p", "x": "Våra lätta brunnslock passar trekammarbrunnar, slamavskiljare, avloppsbrunnar, dagvattenbrunnar och vattenmätarbrunnar. Modellerna 590, 750, 780, 790, 900, 930, 1050, 1150 och 1340 mm täcker både små inspektionsbrunnar och större slambrunnar. Behöver du även tätningsring eller förhöjningsring i betong hittar du det i samma kategoriträd."}, {"t": "h4", "x": "Körbara lätta brunnslock"}, {"t": "p", "x": "För infart, gårdsplan och industriområde har vi körbara lätta brunnslock i klass B125 (12,5 ton), C250 (25 ton) och D400 (40 ton). Locken är förstärkta med stålarmering eller composite-konstruktion och certifierade enligt EN 124. Det körbara locket 590 Composite väger under 12 kg men klarar 12,5 ton, ett tydligt alternativ till tunga gjutjärnsbetäckningar."}], "faq": [{"q": "Vad är ett lätt brunnslock och varför ska jag välja det?", "a": ["Ett lätt brunnslock tillverkas i komposit, polyeten (PE) eller glasfiber och väger 3-12 kg jämfört med ett betonglock 60-120 kg. Det uppfyller Arbetsmiljöverkets krav på att ett brunnslock inte får väga mer än 25 kg vid manuell hantering. Du får samma hållbarhet och säkerhet som ett tungt betonglock, men kan öppna det själv vid inspektion eller slamtömning."]}, {"q": "Vilka storlekar finns lätta brunnslock i?", "a": ["Vi har lätta brunnslock i storlekarna 590, 660, 750, 780, 790, 900, 930, 1000, 1050, 1150 och 1340 mm. De passar betongbrunnar med utvändigt mått 500-1 450 mm och invändigt mått 451-1 290 mm. Använd filtreringen ovan för att hitta rätt storlek baserat på din brunns mått."]}, {"q": "Hur tungt får ett lätt brunnslock vara?", "a": ["Enligt Arbetsmiljöverkets föreskrifter (AFS 2012:2) bör manuell hantering av tunga lock undvikas. Ett brunnslock i betong väger normalt 60-120 kg och kräver lyfthjälpmedel. Våra lätta brunnslock väger 3-12 kg och kan öppnas av en person utan verktyg eller lyfthjälp."]}, {"q": "Vilken bärighet ska jag välja, A15, B125, C250 eller D400?", "a": ["Bärigheten anges i belastningsklass enligt EN 124. A15 (1,5 ton) passar grönområden och gångytor utan biltrafik. B125 (12,5 ton) passar gårdsplan, garageinfart och parkering för personbil. C250 (25 ton) passar mindre lastbilstrafik och industriområden. D400 (40 ton) är vår högsta klass och klarar tung lastbilstrafik på gata och industriinfart."]}, {"q": "Passar lätta brunnslock till min trekammarbrunn?", "a": ["Ja. Lätta brunnslock passar alla vanliga trekammarbrunnar och slamavskiljare i betong med rund öppning mellan 500 och 1 450 mm. De vanligaste storlekarna för trekammarbrunn är 600, 900 och 1 000 mm. Behöver du även en tätningsring för att stoppa lukt och insekter hittar du det i samma kategoriträd."]}, {"q": "Är lätta brunnslock barnsäkra och låsbara?", "a": ["Ja. Samtliga lätta brunnslock i vårt sortiment har en låsfunktion som hindrar barn och obehöriga från att öppna locket. Våra körbara modeller uppfyller säkerhetsstandard EN 124 och är godkända för montering i offentlig och privat miljö."]}, {"q": "Hur monterar jag ett lätt brunnslock på en betongbrunn?", "a": ["Locket placeras direkt på betongringens överkant. För täthet mot vatten, lukt och insekter rekommenderar vi att en tätningsring monteras mellan betongringen och locket. Behöver du höja brunnen till markens nivå används en förhöjningsring i betong. Vid trafikerad yta gjuts en bärlast-ram runt locket."]}, {"q": "Vad kostar ett lätt brunnslock?", "a": ["Priset varierar med storlek, bärighet och material. Mindre composite-lock för avloppsbrunn (590-780 mm) kostar 1 749-2 895 kr. Körbara lock i klass B125 (900 mm) kostar från 7 722 kr. Lätt körbart lock 1 000 mm i klass D400 (40 ton) kostar 17 690 kr. Jämfört med tunga gjutjärnsbetäckningar är priset jämförbart eller lägre, med betydligt lättare hantering."]}, {"q": "Hur skiljer sig ert lätta brunnslock från Byggmax, Biltema och Jula?", "a": ["Våra körbara lock (klass B125 och uppåt) är CE-märkta och certifierade enligt EN 124 för bärighet upp till klass D400 (40 ton). I klass A15 är vissa modeller certifierade enligt EN 124. Hela sortimentet är tillverkat för professionellt bruk. Vi har också större storlekar (upp till 1 340 mm) som inte finns hos byggvaruhusen. Behöver du ett lock som klarar lastbilstrafik eller en specifik storlek över 800 mm är vårt sortiment den primära kanalen i Sverige."]}, {"q": "Vad är fördelen med ett lätt brunnslock för betongringar?", "a": ["Ett lätt brunnslock underlättar hantering och minskar behovet av tung utrustning vid installation och underhåll, vilket sparar både tid och kostnad."]}, {"q": "Vilka dimensioner finns för betongringar med lätta brunnslock?", "a": ["Vi erbjuder betongringar med lätta brunnslock i flera storlekar, från 600 mm upp till 1200 mm i diameter."]}, {"q": "Är brunnslocken säkra att använda i områden med tung trafik?", "a": ["Ja, våra lätta brunnslock för betongringar är designade för att tåla trafikbelastning och uppfyller höga säkerhetsstandarder för sådana miljöer."]}, {"q": "Hur lång är leveranstiden för betongringar med lätt brunnslock?", "a": ["Leveranstiden är vanligtvis 3-6 arbetsdagar, beroende på lagerstatus och destination."]}, {"q": "Kan jag beställa betongringar med lätt brunnslock för både privat och företagsbruk?", "a": ["Ja, vi erbjuder betongringar med lätt brunnslock för både privatpersoner och företag. Betalning kan göras via faktura."]}]}, "fi": {"intro": "Kevyet kaivonkannet betonikaivoihin komposiittia, polyeteeniä ja valurautaa, ajettavat mallit 40 tonniin asti, lapsiturvalliset ja lukittavat. Kantemme painavat alle 25 kg Ruotsin työsuojeluviranomaisen (Arbetsmiljöverket) sääntöjen mukaisesti, ja ne sopivat kaikkiin tavallisiin betonikaivoihin, joiden koko on 500 ja 1 450 mm:n välillä.", "introDraft": false, "h": "Tietoa kevyistä kaivonkansista", "blocks": [{"t": "p", "x": "Täältä löydät sekä tasaisia kaivonkansia jätevesikaivoon, kolmikammiokaivoon ja vesimittarikaivoon että vahvistettuja ajettavia kansia ajoliittymään, piha-alueelle ja teollisuusalueelle."}, {"t": "p", "x": "Tarvitsetko apua oikean koon valinnassa? Mittaa betonirenkaan sisä- tai ulkomitta ja suodata alla, tai soita meille numeroon 0920-520056, niin autamme sinua löytämään kaivoosi sopivan kannen."}, {"t": "h3", "x": "Miksi valita kevyt kaivonkansi?"}, {"t": "p", "x": "Perinteinen betonikansi painaa usein 60-120 kg, minkä vuoksi sitä on raskas nostaa tarkastuksen ja lietteen tyhjennyksen yhteydessä. Komposiitista tai PE:stä valmistetut kevyet kaivonkannet painavat 3-12 kg ja täyttävät Arbetsmiljöverketin 25 kg:n rajan käsin käsittelylle. Niillä on sama kantavuus kuin painavilla betonikansilla, 1,5 tonnista viheralueille 40 tonniin (luokka D400) ajettaville pinnoille, mutta yksi henkilö voi avata ne ilman nostoapuvälineitä."}, {"t": "h4", "x": "Kevyt kaivonkansi kolmikammiokaivoon ja jätevesikaivoon"}, {"t": "p", "x": "Kevyet kaivonkantemme sopivat kolmikammiokaivoihin, saostuskaivoihin, jätevesikaivoihin, hulevesikaivoihin ja vesimittarikaivoihin. Mallit 590, 750, 780, 790, 900, 930, 1050, 1150 ja 1340 mm kattavat sekä pienet tarkastuskaivot että suuremmat lietekaivot. Jos tarvitset myös tiivisterenkaan tai betonisen korotusrenkaan, löydät ne samasta kategoriapuusta."}, {"t": "h4", "x": "Ajettavat kevyet kaivonkannet"}, {"t": "p", "x": "Ajoliittymiin, piha-alueille ja teollisuusalueille meillä on ajettavia kevyitä kaivonkansia luokissa B125 (12,5 tonnia), C250 (25 tonnia) ja D400 (40 tonnia). Kannet on vahvistettu teräsraudoituksella tai komposiittirakenteella, ja ne on sertifioitu EN 124 -standardin mukaisesti. Ajettava kansi 590 Composite painaa alle 12 kg mutta kestää 12,5 tonnia, selkeä vaihtoehto painaville valurautakansistoille."}], "faq": [{"q": "Mikä on kevyt kaivonkansi ja miksi minun kannattaa valita se?", "a": ["Kevyt kaivonkansi valmistetaan komposiitista, polyeteenistä (PE) tai lasikuidusta, ja se painaa 3-12 kg, kun betonikansi painaa 60-120 kg. Se täyttää Arbetsmiljöverketin vaatimuksen, jonka mukaan kaivonkansi saa käsin käsiteltäessä painaa enintään 25 kg. Saat saman kestävyyden ja turvallisuuden kuin painavalla betonikannella, mutta voit avata kannen itse tarkastuksen tai lietteen tyhjennyksen yhteydessä."]}, {"q": "Missä kooissa kevyitä kaivonkansia on saatavana?", "a": ["Meillä on kevyitä kaivonkansia kokoina 590, 660, 750, 780, 790, 900, 930, 1000, 1050, 1150 ja 1340 mm. Ne sopivat betonikaivoihin, joiden ulkomitta on 500-1 450 mm ja sisämitta 451-1 290 mm. Käytä yllä olevaa suodatusta löytääksesi oikean koon kaivosi mittojen perusteella."]}, {"q": "Kuinka painava kevyt kaivonkansi saa olla?", "a": ["Arbetsmiljöverketin määräysten (AFS 2012:2) mukaan painavien kansien käsittelyä käsin tulisi välttää. Betoninen kaivonkansi painaa tavallisesti 60-120 kg ja vaatii nostoapuvälineen. Kevyet kaivonkantemme painavat 3-12 kg, ja yksi henkilö voi avata ne ilman työkaluja tai nostoapua."]}, {"q": "Mikä kantavuus minun pitäisi valita, A15, B125, C250 vai D400?", "a": ["Kantavuus ilmoitetaan kuormitusluokkana EN 124 -standardin mukaisesti. A15 (1,5 tonnia) sopii viheralueille ja kävelypinnoille, joilla ei ole autoliikennettä. B125 (12,5 tonnia) sopii piha-alueille, autotallin ajoliittymiin ja henkilöautojen pysäköintiin. C250 (25 tonnia) sopii vähäiselle kuorma-autoliikenteelle ja teollisuusalueille. D400 (40 tonnia) on korkein luokkamme, ja se kestää raskasta kuorma-autoliikennettä kaduilla ja teollisuusalueiden ajoliittymissä."]}, {"q": "Sopivatko kevyet kaivonkannet kolmikammiokaivooni?", "a": ["Kyllä. Kevyet kaivonkannet sopivat kaikkiin tavallisiin betonisiin kolmikammiokaivoihin ja saostuskaivoihin, joiden pyöreä aukko on 500 ja 1 450 mm:n välillä. Kolmikammiokaivon yleisimmät koot ovat 600, 900 ja 1 000 mm. Jos tarvitset myös tiivisterenkaan hajujen ja hyönteisten estämiseksi, löydät sen samasta kategoriapuusta."]}, {"q": "Ovatko kevyet kaivonkannet lapsiturvallisia ja lukittavia?", "a": ["Kyllä. Kaikissa valikoimamme kevyissä kaivonkansissa on lukitustoiminto, joka estää lapsia ja asiattomia avaamasta kantta. Ajettavat mallimme täyttävät EN 124 -turvallisuusstandardin, ja ne on hyväksytty asennettaviksi julkisiin ja yksityisiin ympäristöihin."]}, {"q": "Miten asennan kevyen kaivonkannen betonikaivoon?", "a": ["Kansi asetetaan suoraan betonirenkaan yläreunalle. Tiiviyden varmistamiseksi vettä, hajuja ja hyönteisiä vastaan suosittelemme asentamaan tiivisterenkaan betonirenkaan ja kannen väliin. Jos kaivoa pitää korottaa maanpinnan tasolle, käytetään betonista korotusrengasta. Liikennöidyllä pinnalla kannen ympärille valetaan kuormaa kantava kehys."]}, {"q": "Mitä kevyt kaivonkansi maksaa?", "a": ["Hinta vaihtelee koon, kantavuuden ja materiaalin mukaan. Pienemmät komposiittikannet jätevesikaivoon (590-780 mm) maksavat 1 749-2 895 kr. Ajettavat kannet luokassa B125 (900 mm) maksavat alkaen 7 722 kr. Kevyt ajettava kansi 1 000 mm luokassa D400 (40 tonnia) maksaa 17 690 kr. Painaviin valurautakansistoihin verrattuna hinta on samaa tasoa tai alhaisempi, ja käsittely on huomattavasti kevyempää."]}, {"q": "Miten kevyt kaivonkantenne eroaa kansista, joita myyvät Byggmax, Biltema ja Jula?", "a": ["Ajettavat kantemme (luokka B125 ja sitä korkeammat) ovat CE-merkittyjä ja sertifioitu EN 124 -standardin mukaisesti kantavuudeltaan luokkaan D400 (40 tonnia) asti. Luokassa A15 osa malleista on sertifioitu EN 124 -standardin mukaisesti. Koko valikoima on valmistettu ammattikäyttöön. Meillä on myös suurempia kokoja (enintään 1 340 mm), joita rautakaupoista ei löydy. Jos tarvitset kannen, joka kestää kuorma-autoliikennettä, tai tietyn yli 800 mm:n koon, valikoimamme on ensisijainen kanava Ruotsissa."]}, {"q": "Mikä on betonirenkaisiin tarkoitetun kevyen kaivonkannen etu?", "a": ["Kevyt kaivonkansi helpottaa käsittelyä ja vähentää raskaan kaluston tarvetta asennuksessa ja kunnossapidossa, mikä säästää sekä aikaa että kustannuksia."]}, {"q": "Missä mitoissa kevyillä kaivonkansilla varustettuja betonirenkaita on saatavana?", "a": ["Tarjoamme kevyillä kaivonkansilla varustettuja betonirenkaita useissa koissa, halkaisijaltaan 600 mm:stä aina 1200 mm:iin."]}, {"q": "Ovatko kaivonkannet turvallisia käyttää alueilla, joilla on raskasta liikennettä?", "a": ["Kyllä, betonirenkaisiin tarkoitetut kevyet kaivonkantemme on suunniteltu kestämään liikennekuormitusta, ja ne täyttävät tällaisten ympäristöjen korkeat turvallisuusstandardit."]}, {"q": "Mikä on kevyellä kaivonkannella varustettujen betonirenkaiden toimitusaika?", "a": ["Toimitusaika on yleensä 3-6 arkipäivää varastotilanteesta ja määränpäästä riippuen."]}, {"q": "Voinko tilata kevyellä kaivonkannella varustettuja betonirenkaita sekä yksityis- että yrityskäyttöön?", "a": ["Kyllä, tarjoamme kevyellä kaivonkannella varustettuja betonirenkaita sekä yksityishenkilöille että yrityksille. Maksaa voi laskulla."]}]}}, "lock/plastbrunn": {"status": "utkast", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/brunnslock/latta-lock-for-plastbrunnar", "name": "Lätta lock för plastbrunnar", "use": "faq"}], "words": 155, "faqWords": 177, "check": "Luonnos tuotekuvauksista (A15, 2 ruuvia, UV-kestävä, sisämitat). FAQ on nykyisen sivun.", "sv": {"intro": "Lätta brunnslock i plast för plastbrunnar med släta eller korrugerade rör. Locken finns för rördimensionerna 315, 400, 425 och 600 mm.", "introDraft": true, "blocks": [{"t": "h3", "x": "Släta eller korrugerade rör", "d": true}, {"t": "p", "x": "Välj lock efter brunnsrörets typ och invändiga diameter. Lock till korrugerade rör finns för invändig diameter 300-340 mm (315), 390-410 mm (400) och 425-450 mm (425). Lock till släta rör finns för invändig diameter 290-315 mm (315), 400 mm och 574-604 mm (600). Locket 400 för korrugerade eller släta rör passar också betongbrunnar med invändigt mått 400 mm.", "d": true}, {"t": "h3", "x": "Belastningsklass och låsning", "d": true}, {"t": "p", "x": "Locken är tillverkade i UV-beständigt material som tål solljus. De har belastningsklass A15 (grönområde, 1 500 kg) och är inte körbara med fordon. Locket låses med två skruvar.", "d": true}, {"t": "p", "x": "Lock för plastbrunnar som ska klara trafik finns bland gjutjärnsbetäckningar för plastbrunnar under Trafik. Är du osäker på storleken? Mät brunnsrörets invändiga diameter och använd filtret ovan, eller ring oss på 0920-52 00 56.", "d": true}], "faq": [{"q": "Vad är lätta lock för plastbrunnar och hur används de?", "a": ["Lätta lock för plastbrunnar är specialdesignade för att passa plastbrunnar och är tillverkade i hållbara material som HD-PE. De är enkla att installera och hantera tack vare sin lätta vikt."]}, {"q": "Vilka fördelar har lätta lock för plastbrunnar jämfört med traditionella lock?", "a": ["Dessa lock är lättare, korrosionsbeständiga och tål både minusgrader och solljus. De minskar risken för skador vid hantering och är ofta utformade med säkerhetsfunktioner för att skydda mot obehörig åtkomst."]}, {"q": "Passar lätta lock för plastbrunnar alla typer av plastbrunnar?", "a": ["Ja, de finns i olika storlekar och kan anpassas för att passa olika storlekar på brunnar och användningsområden som avlopp och vattenbrunnar."]}, {"q": "Hur väljer jag rätt storlek på ett lätt brunnslock för plastbrunnar?", "a": ["Det är viktigt att mäta brunnens öppning noggrant. Svenska Brunnslock tillhandahåller vägledning för att hjälpa dig att välja rätt storlek för din brunn."]}, {"q": "Är lätta lock för plastbrunnar säkra och barnsäkra?", "a": ["De flesta lock är utformade med låsfunktioner och följer säkerhetsstandarder för att förhindra obehörig åtkomst och öka tryggheten för barn och husdjur."]}]}, "fi": {"intro": "Kevyet muoviset kaivonkannet muovikaivoihin, joissa on sileät tai korrugoidut putket. Kansia on saatavana putkikokoihin 315, 400, 425 ja 600 mm.", "introDraft": true, "h": "Tietoa kevyistä kansista muovikaivoihin", "blocks": [{"t": "h3", "x": "Sileät tai korrugoidut putket", "d": true}, {"t": "p", "x": "Valitse kansi kaivoputken tyypin ja sisähalkaisijan mukaan. Korrugoitujen putkien kansia on saatavana sisähalkaisijoille 300-340 mm (315), 390-410 mm (400) ja 425-450 mm (425). Sileiden putkien kansia on saatavana sisähalkaisijoille 290-315 mm (315), 400 mm ja 574-604 mm (600). Korrugoitujen tai sileiden putkien kansi 400 sopii myös betonikaivoihin, joiden sisämitta on 400 mm.", "d": true}, {"t": "h3", "x": "Kuormitusluokka ja lukitus", "d": true}, {"t": "p", "x": "Kannet on valmistettu UV-kestävästä materiaalista, joka kestää auringonvaloa. Niiden kuormitusluokka on A15 (viheralue, 1 500 kg), eivätkä ne ole ajettavia ajoneuvoilla. Kansi lukitaan kahdella ruuvilla.", "d": true}, {"t": "p", "x": "Liikennettä kestäviä kansia muovikaivoihin löytyy muovikaivojen valurautakansistoista kohdasta Liikenne. Etkö ole varma koosta? Mittaa kaivoputken sisähalkaisija ja käytä yllä olevaa suodatinta, tai soita meille numeroon 0920-52 00 56.", "d": true}], "faq": [{"q": "Mitä ovat kevyet kannet muovikaivoihin ja miten niitä käytetään?", "a": ["Muovikaivojen kevyet kannet on suunniteltu erityisesti sopimaan muovikaivoihin, ja ne on valmistettu kestävistä materiaaleista, kuten HD-PE:stä. Ne on helppo asentaa ja käsitellä keveytensä ansiosta."]}, {"q": "Mitä etuja muovikaivojen kevyillä kansilla on perinteisiin kansiin verrattuna?", "a": ["Nämä kannet ovat kevyempiä ja korroosionkestäviä, ja ne kestävät sekä pakkasta että auringonvaloa. Ne vähentävät vaurioiden riskiä käsittelyn aikana, ja niissä on usein turvaominaisuuksia, jotka suojaavat luvattomalta pääsyltä."]}, {"q": "Sopivatko muovikaivojen kevyet kannet kaikentyyppisiin muovikaivoihin?", "a": ["Kyllä, niitä on saatavana eri kokoisina, ja ne voidaan mukauttaa sopimaan erikokoisiin kaivoihin ja käyttötarkoituksiin, kuten viemäröintiin ja vesikaivoihin."]}, {"q": "Miten valitsen oikean koon kevyelle kaivonkannelle muovikaivoon?", "a": ["Kaivon aukko on tärkeää mitata huolellisesti. Svenska Brunnslock tarjoaa opastusta, joka auttaa sinua valitsemaan kaivoosi oikean koon."]}, {"q": "Ovatko muovikaivojen kevyet kannet turvallisia ja lapsiturvallisia?", "a": ["Useimmat kannet on varustettu lukitustoiminnoilla, ja ne noudattavat turvallisuusstandardeja, jotka estävät luvattoman pääsyn ja lisäävät lasten ja lemmikkien turvallisuutta."]}]}}, "lock/plast": {"status": "befintlig", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/brunnslock-plast", "name": "Brunnslock plast", "use": "text"}], "words": 413, "faqWords": 0, "check": "Teksti sellaisenaan (paras SEO-sivu, 301).", "sv": {"intro": "När det gäller att skydda din brunn är ett robust och slitstarkt brunnslock i plast en perfekt lösning. Vi erbjuder ett brett sortiment av brunnslock i högkvalitativ plast som kombinerar hållbarhet, funktionalitet och estetik.", "introDraft": false, "blocks": [{"t": "h3", "x": "Brunnslock plast: hållbara och funktionella lösningar för din brunn"}, {"t": "p", "x": "Våra plastlock är särskilt framtagna för att möta kraven i både privata och kommersiella miljöer, oavsett om det gäller en dricksvattenbrunn, avloppsbrunn eller annan typ av brunnsinstallation."}, {"t": "h3", "x": "Varför välja ett brunnslock i plast?"}, {"t": "p", "x": "Plastlock för brunnar har flera fördelar som gör dem till ett populärt val bland husägare, entreprenörer och fastighetsägare. Här är några av de främsta anledningarna till varför vi rekommenderar våra brunnslock i plast:"}, {"t": "ul", "items": ["Lättvikt och enkel installation: Till skillnad från tunga lock i metall eller betong är plastlock betydligt lättare att hantera och installera. Detta gör dem perfekta för dem som vill ha en smidig och snabb installation utan behov av specialutrustning.", "Rostfritt och underhållsfritt: Våra brunnslock i plast rostar inte och kräver minimalt underhåll, vilket innebär att du sparar både tid och pengar i längden. Det tåliga materialet klarar av extrema väderförhållanden och håller sig i gott skick år efter år.", "Anpassningsbara och diskreta: Brunnslock i plast finns i olika färger och storlekar, vilket gör det enkelt att hitta ett lock som passar din specifika brunn. Deras diskreta design gör att de smälter in i sin omgivning, oavsett om det är i en trädgård, vid en uppfart eller på en gård."]}, {"t": "h3", "x": "Hållbara material för långvarig användning"}, {"t": "p", "x": "Våra brunnslock i plast är tillverkade av UV-resistent och slagtålig plast, vilket säkerställer att de behåller sin styrka och färg över tid. Detta gör dem till en pålitlig och kostnadseffektiv lösning för dig som vill ha ett brunnslock som klarar påfrestningar från både väder och tung trafik. Oavsett om du behöver ett lock för en vanlig trädgårdsbrunn eller för mer industriella tillämpningar har vi alternativ som passar dina behov."}, {"t": "h3", "x": "Välj rätt plastlock för din brunn"}, {"t": "p", "x": "Att välja rätt brunnslock i plast är en viktig del i att säkerställa säkerheten och funktionaliteten i din brunn. Vi erbjuder ett brett utbud av lock med olika dimensioner och egenskaper för att passa olika brunnstyper. Om du är osäker på vilken modell som är bäst för dig, hjälper vi gärna till med rådgivning för att hitta det bästa alternativet för din installation."}, {"t": "p", "x": "Utforska vårt sortiment och hitta det perfekta plastlocket för din brunn hos Svenska Brunnslock. Vi är här för att hjälpa dig att göra det bästa valet för både säkerhet och estetik."}], "faq": []}, "fi": {"intro": "Kun haluat suojata kaivosi, tukeva ja kulutusta kestävä muovinen kaivonkansi on täydellinen ratkaisu. Tarjoamme laajan valikoiman laadukkaasta muovista valmistettuja kaivonkansia, joissa yhdistyvät kestävyys, toimivuus ja esteettisyys.", "introDraft": false, "h": "Tietoa muovikansista", "blocks": [{"t": "h3", "x": "Muoviset kaivonkannet: kestäviä ja toimivia ratkaisuja kaivoosi"}, {"t": "p", "x": "Muovikantemme on kehitetty erityisesti vastaamaan sekä yksityisten että kaupallisten ympäristöjen vaatimuksiin, olipa kyseessä juomavesikaivo, jätevesikaivo tai muu kaivoasennus."}, {"t": "h3", "x": "Miksi valita muovinen kaivonkansi?"}, {"t": "p", "x": "Muovisilla kaivonkansilla on useita etuja, joiden vuoksi ne ovat suosittu valinta talonomistajien, urakoitsijoiden ja kiinteistönomistajien keskuudessa. Tässä on joitakin tärkeimmistä syistä, miksi suosittelemme muovisia kaivonkansiamme:"}, {"t": "ul", "items": ["Keveys ja helppo asennus: Toisin kuin painavat metalli- tai betonikannet, muovikannet ovat huomattavasti helpompia käsitellä ja asentaa. Tämän ansiosta ne sopivat täydellisesti niille, jotka haluavat sujuvan ja nopean asennuksen ilman erikoisvälineitä.", "Ruostumattomia ja huoltovapaita: Muoviset kaivonkantemme eivät ruostu ja vaativat vain vähän huoltoa, joten säästät pitkällä aikavälillä sekä aikaa että rahaa. Kestävä materiaali kestää äärimmäiset sääolosuhteet ja pysyy hyvässä kunnossa vuodesta toiseen.", "Mukautettavia ja huomaamattomia: Muovisia kaivonkansia on saatavana eri väreissä ja kokoina, joten juuri sinun kaivoosi sopivan kannen löytäminen on helppoa. Niiden huomaamattoman muotoilun ansiosta ne sulautuvat ympäristöönsä, oli kyseessä puutarha, pihatie tai piha."]}, {"t": "h3", "x": "Kestävät materiaalit pitkäaikaiseen käyttöön"}, {"t": "p", "x": "Muoviset kaivonkantemme on valmistettu UV-kestävästä ja iskunkestävästä muovista, mikä varmistaa, että ne säilyttävät lujuutensa ja värinsä ajan myötä. Tämän ansiosta ne ovat luotettava ja kustannustehokas ratkaisu, kun haluat kaivonkannen, joka kestää sekä sään että raskaan liikenteen rasitukset. Tarvitsitpa kannen tavalliseen puutarhakaivoon tai teollisempiin käyttökohteisiin, meiltä löytyy tarpeisiisi sopivia vaihtoehtoja."}, {"t": "h3", "x": "Valitse kaivoosi oikea muovikansi"}, {"t": "p", "x": "Oikean muovisen kaivonkannen valinta on tärkeä osa kaivosi turvallisuuden ja toimivuuden varmistamista. Tarjoamme laajan valikoiman kansia, joissa on eri mitat ja ominaisuudet eri kaivotyyppeihin. Jos et ole varma, mikä malli sopii sinulle parhaiten, autamme mielellämme neuvonnalla löytääksemme asennukseesi parhaan vaihtoehdon."}, {"t": "p", "x": "Tutustu valikoimaamme ja löydä kaivoosi täydellinen muovikansi Svenska Brunnslockilta. Autamme sinua tekemään parhaan valinnan sekä turvallisuuden että esteettisyyden kannalta."}], "faq": []}}, "lock/betong": {"status": "kombinerad", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/betonglock", "name": "Betonglock", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/betonglock/betonglock-till-gardspump", "name": "Betonglock till Gårdspump", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/luckor/betonglock-med-ingjuten-lucka", "name": "Betonglock med ingjuten lucka", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/betonglock/betonglock-med-luftningsventil", "name": "Betonglock med luftningsventil", "use": "sammanfogad"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/betonglock/korbara-betonglock", "name": "Körbara betonglock", "use": "ingen text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/betonglock/ej-korbara-betonglock", "name": "Ej körbara betonglock", "use": "ingen text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/betonglock/korbara-betonglock-med-manhal", "name": "Körbara betonglock med manhål", "use": "ingen text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/betonglock/ej-korbara-betonglock-med-manhal", "name": "Ej körbara betonglock med manhål", "use": "ingen text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/betonglock/betonglock-med-lucka", "name": "Betonglock med lucka", "use": "ingen text"}], "words": 428, "faqWords": 0, "check": "Kolme tekstiä yhdistetty. \"Kronans gårdspump nr 12\" tuotenimenä ok?", "sv": {"intro": "På Svenska Brunnslock förstår vi vikten av pålitliga och hållbara lösningar för att skydda vattenbrunnar och andra nedgrävda installationer.", "introDraft": false, "blocks": [{"t": "p", "x": "Våra betonglock är utformade för att möta dessa behov och kombinerar styrka och hållbarhet i en produkt som står emot tidens tand. Men vad är det egentligen som gör betonglock till ett föredraget val i många projekt, och vilka unika egenskaper erbjuder de?"}, {"t": "h3", "x": "Vad är betonglock?"}, {"t": "p", "x": "Betonglock används för att säkra tillträdet till brunnar, schakt och andra nedgrävda utrymmen där det finns behov av ett robust och långvarigt skydd. De är tillverkade av högkvalitativ, armerad betong, och erbjuder exceptionell styrka och motståndskraft mot både fysiska påfrestningar och väderrelaterad erosion. Deras tyngd garanterar att de inte enkelt kan flyttas eller tas bort, vilket är en kritisk egenskap i många säkerhetssammanhang."}, {"t": "h4", "x": "Fördelar med betonglock"}, {"t": "p", "x": "Installationen av betonglock i infrastruktur- och industriella projekt såväl som på en fastighet erbjuder många fördelar. Den främsta är deras långvariga hållbarhet. Betong är välkänt för sin förmåga att stå emot hårda väderförhållanden, vilket är idealiskt för svenska klimatförhållanden som kan variera från heta somrar till iskalla vintrar. Betonglock är också mycket kostnadseffektiva, särskilt med tanke på deras långa livslängd och minimala underhållsbehov."}, {"t": "p", "x": "Dessa är dessutom säkra. Deras vikt och robusta konstruktion gör dem svåra att manipulera eller forcera, vilket erbjuder ett effektivt skydd mot obehörig åtkomst till kritiska infrastrukturtillgångar."}, {"t": "h4", "x": "Välja rätt betonglock"}, {"t": "p", "x": "Att välja rätt betonglock innebär att överväga flera faktorer, såsom storlek, form och specifika säkerhetskrav. På Svenska Brunnslock har vi ett brett sortiment av betonglock som passar olika applikationer och uppfyller diverse tekniska krav. Vårt team av experter är redo att assistera dig med att välja rätt produkt som passar just dina behov och förutsättningar."}, {"t": "h4", "x": "Investera i betonglock från Svenska Brunnslock"}, {"t": "p", "x": "Genom att investera i betonglock från Svenska Brunnslock kan du vara säker på att du får en lösning som inte bara är hållbar och pålitlig, utan också kostnadseffektiv. Våra produkter är designade för att erbjuda maximal säkerhet och hållbarhet, vilket minskar behovet av frekventa byten eller underhåll."}, {"t": "p", "x": "Kontakta oss idag för att diskutera dina behov och hur våra betonglock kan ge dig den säkerhet och hållbarhet du behöver för dina vattenbrunnar och andra infrastrukturtillgångar. Välj Svenska Brunnslock för kvalitet och pålitlighet som varar."}, {"t": "h3", "x": "Betonglock till gårdspump"}, {"t": "p", "x": "Brunnslock i betong passar till de flesta gårdspumpar på marknaden, exempelvis Kronans gårdspump nr 12."}, {"t": "h3", "x": "Betonglock med ingjuten lucka"}, {"t": "p", "x": "Vi tillverkar olika typer av specialanpassade betonglock med ingjutna luckor. Från luckor i segjärn, stål eller aluminium. Kan tillverka i alla belastningsklasser från A15 till F900"}, {"t": "p", "x": "Levereras med ingjutna lyftöglor så man enkelt kan lyfta betonglocken på plats."}], "faq": []}, "fi": {"intro": "Svenska Brunnslockilla ymmärrämme luotettavien ja kestävien ratkaisujen merkityksen vesikaivojen ja muiden maanalaisten asennusten suojaamisessa.", "introDraft": false, "h": "Tietoa betonikansista", "blocks": [{"t": "p", "x": "Betonikantemme on suunniteltu vastaamaan näihin tarpeisiin, ja niissä yhdistyvät lujuus ja kestävyys tuotteessa, joka kestää aikaa. Mutta mikä oikeastaan tekee betonikansista suositun valinnan monissa hankkeissa, ja mitä ainutlaatuisia ominaisuuksia niillä on?"}, {"t": "h3", "x": "Mitä betonikannet ovat?"}, {"t": "p", "x": "Betonikansia käytetään turvaamaan pääsy kaivoihin, kuiluihin ja muihin maanalaisiin tiloihin silloin, kun tarvitaan tukevaa ja pitkäikäistä suojaa. Ne on valmistettu laadukkaasta, raudoitetusta betonista, ja niillä on poikkeuksellinen lujuus sekä kestävyys niin fyysisiä rasituksia kuin sääolosuhteiden aiheuttamaa eroosiota vastaan. Niiden paino takaa, ettei niitä voi helposti siirtää tai poistaa, mikä on kriittinen ominaisuus monissa turvallisuusyhteyksissä."}, {"t": "h4", "x": "Betonikansien edut"}, {"t": "p", "x": "Betonikansien asentaminen infrastruktuuri- ja teollisuushankkeisiin sekä kiinteistöille tarjoaa monia etuja. Tärkein niistä on niiden pitkäaikainen kestävyys. Betoni tunnetaan kyvystään kestää ankaria sääolosuhteita, mikä on ihanteellista Ruotsin ilmasto-oloille, jotka voivat vaihdella kuumista kesistä jäätäviin talviin. Betonikannet ovat myös erittäin kustannustehokkaita, etenkin kun otetaan huomioon niiden pitkä käyttöikä ja vähäinen huollon tarve."}, {"t": "p", "x": "Ne ovat lisäksi turvallisia. Niiden paino ja tukeva rakenne tekevät niistä vaikeita peukaloida tai murtaa, mikä tarjoaa tehokkaan suojan luvatonta pääsyä vastaan kriittisiin infrastruktuurikohteisiin."}, {"t": "h4", "x": "Oikean betonikannen valinta"}, {"t": "p", "x": "Oikean betonikannen valitseminen edellyttää useiden tekijöiden, kuten koon, muodon ja erityisten turvallisuusvaatimusten, huomioimista. Svenska Brunnslockilla on laaja valikoima betonikansia, jotka sopivat eri käyttökohteisiin ja täyttävät erilaisia teknisiä vaatimuksia. Asiantuntijatiimimme on valmis auttamaan sinua valitsemaan tuotteen, joka sopii juuri sinun tarpeisiisi ja olosuhteisiisi."}, {"t": "h4", "x": "Investoi Svenska Brunnslockin betonikansiin"}, {"t": "p", "x": "Investoimalla Svenska Brunnslockin betonikansiin voit olla varma, että saat ratkaisun, joka ei ole ainoastaan kestävä ja luotettava vaan myös kustannustehokas. Tuotteemme on suunniteltu tarjoamaan maksimaalinen turvallisuus ja kestävyys, mikä vähentää tiheiden vaihtojen tai huoltojen tarvetta."}, {"t": "p", "x": "Ota meihin yhteyttä jo tänään, niin keskustellaan tarpeistasi ja siitä, miten betonikantemme voivat antaa sinulle tarvitsemasi turvallisuuden ja kestävyyden vesikaivoillesi ja muille infrastruktuurikohteillesi. Valitse Svenska Brunnslock: laatua ja luotettavuutta, joka kestää."}, {"t": "h3", "x": "Betonikansi pihapumppuun"}, {"t": "p", "x": "Betoniset kaivonkannet sopivat useimpiin markkinoilla oleviin pihapumppuihin, esimerkiksi Kronanin pihapumppuun nro 12."}, {"t": "h3", "x": "Betonikansi, johon on valettu luukku"}, {"t": "p", "x": "Valmistamme erilaisia erikseen mukautettuja betonikansia, joihin on valettu luukku. Luukut voivat olla pallografiittivalurautaa, terästä tai alumiinia. Voimme valmistaa kaikissa kuormitusluokissa A15:stä F900:aan"}, {"t": "p", "x": "Toimitetaan valetuilla nostolenkeillä, joten betonikannet on helppo nostaa paikalleen."}], "faq": []}}, "lock/gjutjarn": {"status": "kombinerad", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/lock-och-sil-i-gjutjarn/lock-och-sil-till-latta-betackningar", "name": "Lock och sil till Lätta betäckningar", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/lock-och-sil-i-gjutjarn/sil-till-spygatter", "name": "Sil-lock till Spygatter", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/lock-och-sil-i-gjutjarn", "name": "Lock och sil i gjutjärn", "use": "ingen text"}], "words": 321, "faqWords": 0, "check": "Kaksi tekstiä yhdistetty, toistuvat SEO-osiot pois.", "sv": {"intro": "Lock eller sil i gjutjärn är avsedda att placeras i ytor där små eller inga trafiklaster förekommer. Det normala användningsområdet är i tomtmark och på gångbanor eller cykelvägar där snöröjning och annat underhåll görs med lättare maskiner.", "introDraft": false, "blocks": [{"t": "p", "x": "Klarar en belastning på 3 ton."}, {"t": "h3", "x": "Lock och sil till betäckning: effektiv vattenhantering"}, {"t": "p", "x": "Lock och sil till betäckning är viktiga komponenter för att säkerställa effektiv vattenhantering i avloppssystem och andra underjordiska installationer. På Svenska Brunnslock erbjuder vi högkvalitativa lock och silar som ger pålitlig prestanda och hållbarhet. Här diskuterar vi fördelarna med våra produkter, vilka alternativ vi erbjuder och deras användning."}, {"t": "h3", "x": "Fördelar med lock och sil till betäckning"}, {"t": "p", "x": "Lock och silar hjälper till att förhindra att skräp och stora föremål kommer in i avloppssystemet, vilket minskar risken för blockeringar och översvämningar. De är avgörande för att upprätthålla effektiv vattenavrinning och skydda infrastrukturen. Genom att använda lock och silar från Svenska Brunnslock kan du säkerställa att ditt avloppssystem fungerar optimalt och kräver mindre underhåll."}, {"t": "h3", "x": "Våra produkter"}, {"t": "p", "x": "Vi erbjuder lock och silar till betäckning i olika storlekar och material, inklusive gjutjärn och komposit, för att passa olika tillämpningar och miljöer. Våra produkter är tillverkade av hållbara material som tål tuffa förhållanden och säkerställer långvarig prestanda. Oavsett dina specifika krav har vi rätt lösning för dig."}, {"t": "h3", "x": "Användning och installation"}, {"t": "p", "x": "Lock och silar är enkla att installera och underhålla. Våra produkter levereras med detaljerade installationsanvisningar för att säkerställa korrekt montering och effektiv funktion. Genom att följa dessa anvisningar kan du snabbt och enkelt förbättra vattenhanteringen och skyddet för ditt avloppssystem."}, {"t": "h3", "x": "Sil-lock till spygatter"}, {"t": "p", "x": "Finns även som körbar som är belastningstestad med 3 tons punktbelastning. Lämpliga miljöer är bland annat stall, parkeringsgarage och pannrum."}, {"t": "h4", "x": "Sil-lock till spygatter: skydda dina avloppssystem"}, {"t": "p", "x": "Sil-lock till spygatter är en viktig komponent för att skydda avloppssystem genom att förhindra att skräp och stora föremål tränger in. På Svenska Brunnslock erbjuder vi högkvalitativa sil-lock som säkerställer effektiv funktion och långvarig hållbarhet."}], "faq": []}, "fi": {"intro": "Valurautaiset kannet tai sihdit on tarkoitettu sijoitettaviksi pinnoille, joilla on vähän tai ei lainkaan liikennekuormia. Tavallinen käyttökohde on tonttimaa sekä jalkakäytävät tai pyörätiet, joilla lumenauraus ja muu kunnossapito tehdään kevyemmillä koneilla.", "introDraft": false, "h": "Tietoa valurautakansista ja sihdeistä", "blocks": [{"t": "p", "x": "Kestää 3 tonnin kuormituksen."}, {"t": "h3", "x": "Kannet ja sihdit kansistoihin: tehokas vedenhallinta"}, {"t": "p", "x": "Kansistojen kannet ja sihdit ovat tärkeitä komponentteja tehokkaan vedenhallinnan varmistamisessa viemärijärjestelmissä ja muissa maanalaisissa asennuksissa. Svenska Brunnslockilla tarjoamme laadukkaita kansia ja sihtejä, jotka tarjoavat luotettavan suorituskyvyn ja kestävyyden. Tässä käsittelemme tuotteidemme etuja, tarjoamiamme vaihtoehtoja ja niiden käyttöä."}, {"t": "h3", "x": "Kansistojen kansien ja sihtien edut"}, {"t": "p", "x": "Kannet ja sihdit auttavat estämään roskien ja suurten esineiden pääsyn viemärijärjestelmään, mikä vähentää tukosten ja tulvien riskiä. Ne ovat ratkaisevan tärkeitä tehokkaan veden poisjohtamisen ylläpitämisessä ja infrastruktuurin suojaamisessa. Käyttämällä Svenska Brunnslockin kansia ja sihtejä voit varmistaa, että viemärijärjestelmäsi toimii optimaalisesti ja vaatii vähemmän huoltoa."}, {"t": "h3", "x": "Tuotteemme"}, {"t": "p", "x": "Tarjoamme kansia ja sihtejä kansistoihin eri kokoina ja materiaaleina, mukaan lukien valurauta ja komposiitti, sopimaan erilaisiin käyttökohteisiin ja ympäristöihin. Tuotteemme on valmistettu kestävistä materiaaleista, jotka kestävät vaativia olosuhteita ja varmistavat pitkäaikaisen suorituskyvyn. Olivatpa erityisvaatimuksesi mitkä tahansa, meiltä löytyy oikea ratkaisu sinulle."}, {"t": "h3", "x": "Käyttö ja asennus"}, {"t": "p", "x": "Kannet ja sihdit on helppo asentaa ja huoltaa. Tuotteidemme mukana toimitetaan yksityiskohtaiset asennusohjeet, jotka varmistavat oikean asennuksen ja tehokkaan toiminnan. Noudattamalla näitä ohjeita voit nopeasti ja helposti parantaa viemärijärjestelmäsi vedenhallintaa ja suojausta."}, {"t": "h3", "x": "Sihtikansi lattiakaivoon"}, {"t": "p", "x": "Saatavana myös ajettavana mallina, joka on kuormitustestattu 3 tonnin pistekuormalla. Sopivia ympäristöjä ovat muun muassa tallit, pysäköintihallit ja kattilahuoneet."}, {"t": "h4", "x": "Sihtikansi lattiakaivoon: suojaa viemärijärjestelmäsi"}, {"t": "p", "x": "Lattiakaivon sihtikansi on tärkeä komponentti viemärijärjestelmien suojaamisessa, koska se estää roskia ja suuria esineitä pääsemästä sisään. Svenska Brunnslockilla tarjoamme laadukkaita sihtikansia, jotka varmistavat tehokkaan toiminnan ja pitkäaikaisen kestävyyden."}], "faq": []}}, "lock/luckor": {"status": "kombinerad", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/luckor/korbara-luckor", "name": "Körbara luckor", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/luckor/plana-luckor", "name": "Plana luckor", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/luckor/overfalsad-lucka", "name": "Överfalsad lucka", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/luckor/durkplatsluckor", "name": "Durkplåtsluckor", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/luckor", "name": "Luckor", "use": "ingen text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/luckor/rostfria-luckor", "name": "Rostfria Luckor", "use": "ingen text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/luckor/aluminiumluckor", "name": "Aluminiumluckor", "use": "ingen text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/luckor/varmforzinkade-stal-luckor", "name": "Varmförzinkade/stål luckor", "use": "ingen text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/luckor/kompositluckor", "name": "Kompositluckor", "use": "ingen text"}], "words": 527, "faqWords": 0, "check": "Neljä tekstiä yhdistetty (körbara, plana, överfalsade, durkplåt). Pitkä: SB voi lyhentää yleisiä SEO-kappaleita.", "sv": {"intro": "Vi har ett stort sortiment på körbara luckor med alla belastningsklasser enligt europastandard EN 124.", "introDraft": false, "blocks": [{"t": "p", "x": "Belastningsklass och användningsområde."}, {"t": "ul", "items": ["Lättare biltrafik - parkeringar och garage B125 och C250", "Tung trafik - normal trafik klarar bussar och lastbilar D400", "Riktigt tung trafik - hamnar, industrier och flygplatser E600 och F900"]}, {"t": "h3", "x": "Körbara luckor: hållbara och tåliga för trafikerade områden"}, {"t": "p", "x": "Körbara luckor är designade för att klara tung trafik och tuffa förhållanden, vilket gör dem idealiska för användning i områden som vägar, parkeringsplatser och industriella miljöer. På Svenska Brunnslock erbjuder vi högkvalitativa körbara luckor som kombinerar styrka och hållbarhet med enkel installation. Här går vi igenom fördelarna med våra produkter, de olika alternativen och deras användning."}, {"t": "h3", "x": "Fördelar med körbara luckor"}, {"t": "p", "x": "Körbara luckor är utformade för att klara höga belastningar och intensiv trafik. Deras robusta konstruktion säkerställer att de tål vikten av tunga fordon, vilket gör dem perfekta för installation i vägar och andra trafikerade områden. Genom att använda körbara luckor från Svenska Brunnslock kan du säkerställa att dina infrastrukturer förblir säkra och funktionella under lång tid."}, {"t": "h3", "x": "Våra produkter"}, {"t": "p", "x": "Vi erbjuder körbara luckor i olika storlekar och material, inklusive gjutjärn och stål, för att passa olika behov och applikationer. Våra produkter är tillverkade av högkvalitativa material som garanterar lång livslängd och pålitlig prestanda. Oavsett om du behöver luckor för en väg, en parkeringsplats eller ett industriområde, har vi rätt lösning för dig."}, {"t": "h3", "x": "Användning och installation"}, {"t": "p", "x": "Körbara luckor är enkla att installera och underhålla. Våra produkter levereras med detaljerade installationsanvisningar för att säkerställa korrekt montering och optimal funktion. Genom att följa dessa anvisningar kan du snabbt och enkelt förbättra säkerheten och hållbarheten i din infrastruktur."}, {"t": "h3", "x": "Användningsområden"}, {"t": "p", "x": "Dessa luckor är mångsidiga och kan användas i en mängd olika miljöer. De är perfekta för användning på vägar, parkeringsplatser, industriområden och andra platser där tung trafik förekommer. Deras robusta konstruktion och hållbara material gör dem till en pålitlig lösning för alla dina behov."}, {"t": "h3", "x": "Plana luckor"}, {"t": "p", "x": "Plana luckor används både inom- och utomhus som golvlucka och inspektionslucka kan även användas som vägglucka. Vid beställning av komplett lucka ingår ram för ingjutning eller eftermontage. Exempel på användningsområden: nedstigningsluckor, inspektionslucka, vägglucka, manlucka, lucka för pumpstationer."}, {"t": "h4", "x": "Plana luckor: diskreta och funktionella"}, {"t": "p", "x": "Plana luckor är designade för att vara diskreta och funktionella, vilket gör dem idealiska för användning i en mängd olika miljöer. På Svenska Brunnslock erbjuder vi plana luckor som kombinerar estetik med prestanda."}, {"t": "h3", "x": "Överfalsade luckor"}, {"t": "p", "x": "Vi levererar luckorna i rostfritt, aluminium eller varmförzinkat stål. Användningsområde för en överfalsade luckor kan vara som nedstigningslucka på olika platser, olika typer av inspektionsluckor, rökevakueringsluckor för fastigheter, lucka för pumpstationer eller för nödutrymning, olika typer av manlucka eller vägglucka samt fjärrvärmelucka."}, {"t": "h4", "x": "Överfalsad lucka: säker och tätslutande"}, {"t": "p", "x": "En överfalsad lucka är utformad för att ge en säker och tätslutande lösning för en mängd olika applikationer. På Svenska Brunnslock erbjuder vi överfalsade luckor som kombinerar hållbarhet med enkel installation."}, {"t": "h3", "x": "Durkplåtsluckor"}, {"t": "p", "x": "Användningsområden för en plan durkplåtslucka är bland annat som -nedstignings, inspektions-, vägg-, manlucka, eller lucka för pumpstationer."}, {"t": "p", "x": "Används ofta som inspektionslucka i källare."}, {"t": "h4", "x": "Durkplåtsluckor: hållbara och halksäkra"}, {"t": "p", "x": "Durkplåtsluckor är robusta och halksäkra luckor som används i en mängd olika industriella och kommersiella miljöer. På Svenska Brunnslock erbjuder vi durkplåtsluckor som är designade för att vara hållbara och säkra."}], "faq": []}, "fi": {"intro": "Meillä on laaja valikoima ajettavia luukkuja kaikissa eurooppalaisen EN 124 -standardin mukaisissa kuormitusluokissa.", "introDraft": false, "h": "Tietoa luukuista", "blocks": [{"t": "p", "x": "Kuormitusluokka ja käyttökohde."}, {"t": "ul", "items": ["Kevyempi autoliikenne: pysäköintialueet ja autotallit B125 ja C250", "Raskas liikenne: tavallinen liikenne, kestää linja-autot ja kuorma-autot D400", "Erittäin raskas liikenne: satamat, teollisuus ja lentoasemat E600 ja F900"]}, {"t": "h3", "x": "Ajettavat luukut: kestäviä ja lujia liikennöidyille alueille"}, {"t": "p", "x": "Ajettavat luukut on suunniteltu kestämään raskasta liikennettä ja vaativia olosuhteita, mikä tekee niistä ihanteellisia käytettäviksi esimerkiksi teillä, pysäköintialueilla ja teollisuusympäristöissä. Svenska Brunnslockilla tarjoamme laadukkaita ajettavia luukkuja, joissa yhdistyvät lujuus ja kestävyys sekä helppo asennus. Tässä käymme läpi tuotteidemme edut, eri vaihtoehdot ja niiden käytön."}, {"t": "h3", "x": "Ajettavien luukkujen edut"}, {"t": "p", "x": "Ajettavat luukut on suunniteltu kestämään suuria kuormia ja vilkasta liikennettä. Niiden tukeva rakenne varmistaa, että ne kestävät raskaiden ajoneuvojen painon, mikä tekee niistä täydellisiä asennettaviksi teihin ja muille liikennöidyille alueille. Käyttämällä Svenska Brunnslockin ajettavia luukkuja voit varmistaa, että infrastruktuurisi pysyy turvallisena ja toimivana pitkään."}, {"t": "h3", "x": "Tuotteemme"}, {"t": "p", "x": "Tarjoamme ajettavia luukkuja eri kokoina ja materiaaleina, mukaan lukien valurauta ja teräs, sopimaan erilaisiin tarpeisiin ja käyttökohteisiin. Tuotteemme on valmistettu laadukkaista materiaaleista, jotka takaavat pitkän käyttöiän ja luotettavan suorituskyvyn. Tarvitsitpa luukkuja tielle, pysäköintialueelle tai teollisuusalueelle, meiltä löytyy oikea ratkaisu sinulle."}, {"t": "h3", "x": "Käyttö ja asennus"}, {"t": "p", "x": "Ajettavat luukut on helppo asentaa ja huoltaa. Tuotteidemme mukana toimitetaan yksityiskohtaiset asennusohjeet, jotka varmistavat oikean asennuksen ja optimaalisen toiminnan. Noudattamalla näitä ohjeita voit nopeasti ja helposti parantaa infrastruktuurisi turvallisuutta ja kestävyyttä."}, {"t": "h3", "x": "Käyttökohteet"}, {"t": "p", "x": "Nämä luukut ovat monipuolisia, ja niitä voidaan käyttää monenlaisissa ympäristöissä. Ne sopivat täydellisesti käytettäviksi teillä, pysäköintialueilla, teollisuusalueilla ja muissa paikoissa, joissa on raskasta liikennettä. Niiden tukeva rakenne ja kestävät materiaalit tekevät niistä luotettavan ratkaisun kaikkiin tarpeisiisi."}, {"t": "h3", "x": "Tasaiset luukut"}, {"t": "p", "x": "Tasaisia luukkuja käytetään sekä sisällä että ulkona lattialuukkuina ja tarkastusluukkuina, ja niitä voidaan käyttää myös seinäluukkuina. Kun tilaat kokonaisen luukun, mukana on kehys valuun upotettavaksi tai jälkiasennukseen. Esimerkkejä käyttökohteista: laskeutumisluukut, tarkastusluukku, seinäluukku, miesluukku, luukku pumppaamoihin."}, {"t": "h4", "x": "Tasaiset luukut: huomaamattomia ja toimivia"}, {"t": "p", "x": "Tasaiset luukut on suunniteltu huomaamattomiksi ja toimiviksi, mikä tekee niistä ihanteellisia käytettäviksi monenlaisissa ympäristöissä. Svenska Brunnslockilla tarjoamme tasaisia luukkuja, joissa yhdistyvät esteettisyys ja suorituskyky."}, {"t": "h3", "x": "Limireunaiset luukut"}, {"t": "p", "x": "Toimitamme luukut ruostumattomasta teräksestä, alumiinista tai kuumasinkitystä teräksestä. Limireunaista luukkua voidaan käyttää esimerkiksi laskeutumisluukkuna eri kohteissa, erilaisina tarkastusluukkuina, kiinteistöjen savunpoistoluukkuina, pumppaamojen luukkuna tai hätäpoistumiseen, erilaisina miesluukkuina tai seinäluukkuina sekä kaukolämpöluukkuna."}, {"t": "h4", "x": "Limireunainen luukku: turvallinen ja tiiviisti sulkeutuva"}, {"t": "p", "x": "Limireunainen luukku on suunniteltu tarjoamaan turvallinen ja tiiviisti sulkeutuva ratkaisu monenlaisiin käyttökohteisiin. Svenska Brunnslockilla tarjoamme limireunaisia luukkuja, joissa yhdistyvät kestävyys ja helppo asennus."}, {"t": "h3", "x": "Kyynellevyluukut"}, {"t": "p", "x": "Tasaista kyynellevyluukkua käytetään muun muassa laskeutumis-, tarkastus-, seinä- tai miesluukkuna tai pumppaamojen luukkuna."}, {"t": "p", "x": "Käytetään usein tarkastusluukkuna kellareissa."}, {"t": "h4", "x": "Kyynellevyluukut: kestäviä ja liukastumista estäviä"}, {"t": "p", "x": "Kyynellevyluukut ovat tukevia ja liukastumista estäviä luukkuja, joita käytetään monenlaisissa teollisissa ja kaupallisissa ympäristöissä. Svenska Brunnslockilla tarjoamme kyynellevyluukkuja, jotka on suunniteltu kestäviksi ja turvallisiksi."}], "faq": []}}, "lock/golv": {"status": "kombinerad", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/luckor/krypgrundslucka", "name": "Krypgrundslucka", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/luckor/golvlucka-aluminium", "name": "Golvlucka Aluminium", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/luckor/inspektionsluckor", "name": "Inspektionsluckor", "use": "sammanfogad"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/luckor/golvlucka-varmforzinkad", "name": "Golvlucka Varmförzinkad", "use": "ingen text"}], "words": 83, "faqWords": 0, "check": "Lyhyt (alle 100 sanaa). SB voi täydentää lattia- ja tarkastusluukuista.", "sv": {"intro": "Krypgrundslucka eller \"lucka till torpargrund\" som de också kallas är tillverkade i stålplåt som ytbehandlats, för utomhusmiljö tål vatten, vind och UV-ljus. Luckorna levereras med vridlås och nyckel.", "introDraft": false, "blocks": [{"t": "p", "x": "Ramen har monteringshål för att man enkelt skall kunna montera locken med skruvar."}, {"t": "p", "x": "Finns i 2 st. olika storlekar. Luckorna är inte isolerade, vi rekommenderar att man isolerar öppningen med cellplast eller annan likvärdig isolering."}, {"t": "p", "x": "Levereras i GRÅ kulör RAL 7040."}, {"t": "h3", "x": "Golvlucka i aluminium"}, {"t": "p", "x": "Inspektionslucka i aluminium. Gas- och vattentät. För inom- och utomhusbruk."}], "faq": []}, "fi": {"intro": "Ryömintätilan luukut eli \"torpan perustuksen luukut\", kuten niitä myös kutsutaan, on valmistettu pintakäsitellystä teräslevystä, joka ulkoympäristössä kestää vettä, tuulta ja UV-valoa. Luukut toimitetaan kääntölukolla ja avaimella.", "introDraft": false, "h": "Tietoa lattia- ja ryömintätilan luukuista", "blocks": [{"t": "p", "x": "Kehyksessä on asennusreiät, joten kannet on helppo asentaa ruuveilla."}, {"t": "p", "x": "Saatavana 2 eri kokoa. Luukkuja ei ole eristetty, joten suosittelemme aukon eristämistä solumuovilla tai muulla vastaavalla eristeellä."}, {"t": "p", "x": "Toimitetaan HARMAANA, sävy RAL 7040."}, {"t": "h3", "x": "Alumiininen lattialuukku"}, {"t": "p", "x": "Alumiininen tarkastusluukku. Kaasu- ja vesitiivis. Sisä- ja ulkokäyttöön."}], "faq": []}}, "lock/sakerhet": {"status": "kombinerad", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/luckor/sakerhetslucka", "name": "Säkerhetslucka", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/luckor/evakueringslucka", "name": "Evakueringslucka", "use": "text"}], "words": 440, "faqWords": 0, "check": "\"Tillverkas enligt ISO 9001 och ISO 14001\" ja \"A15 upp till ...\" tarkistettava. Brand-rökluckor-kategorian teksti (piilotettu, 0 tuotetta) jätetty pois.", "sv": {"intro": "Vi har ett stort utbud på måttanpassade säkerhetsluckor efter önskemål. Luckorna kan anpassas utifrån säkerhetsklass 1 till 4 och belastningsklass enligt EN124 från A15 kN - F900 kN.", "introDraft": false, "blocks": [{"t": "p", "x": "Tillverkas enligt ISO 9001 och ISO 14001."}, {"t": "p", "x": "Luckorna kan tillverkas i en mängd olika material som:"}, {"t": "ul", "items": ["Galvaniserat stål", "Rostfritt stål", "Aluminium", "Segjärn (gjutjärn)", "Kompositmaterial."]}, {"t": "h3", "x": "Säkerhetslucka: optimal skydd och säkerhet"}, {"t": "p", "x": "En säkerhetslucka är en kritisk komponent för att säkerställa säkerhet och skydd i olika miljöer, inklusive industriella anläggningar, tekniska rum och underjordiska utrymmen. På Svenska Brunnslock erbjuder vi säkerhetsluckor som kombinerar robusthet med avancerade säkerhetsfunktioner. Här går vi igenom fördelarna med våra produkter, de olika alternativen och deras användning."}, {"t": "h3", "x": "Fördelar med säkerhetsluckor"}, {"t": "p", "x": "Säkerhetsluckor erbjuder skydd mot obehörig åtkomst och förhindrar olyckor genom att ge en säker och kontrollerad åtkomst till kritiska utrymmen. De är utformade för att vara hållbara och motståndskraftiga mot intrång, vilket gör dem idealiska för användning i känsliga och högsäkerhetsmiljöer. Genom att använda säkerhetsluckor från Svenska Brunnslock kan du säkerställa högsta nivå av skydd och säkerhet för dina anläggningar."}, {"t": "h3", "x": "Våra produkter"}, {"t": "p", "x": "Vi erbjuder säkerhetsluckor i olika storlekar och material, inklusive stål och aluminium, för att passa olika behov och applikationer. Våra produkter är utrustade med avancerade låssystem och säkerhetsfunktioner som garanterar maximal säkerhet och pålitlighet. Oavsett dina specifika krav har vi rätt lösning för dig."}, {"t": "h3", "x": "Användning och installation"}, {"t": "p", "x": "Säkerhetsluckor är enkla att installera och använda. Våra produkter levereras med detaljerade installationsanvisningar för att säkerställa korrekt montering och optimal säkerhet. Genom att följa dessa anvisningar kan du snabbt och enkelt förbättra skyddet och säkerheten i dina anläggningar."}, {"t": "h3", "x": "Användningsområden"}, {"t": "p", "x": "Säkerhetsluckor är mångsidiga och kan användas i en mängd olika miljöer. De är perfekta för användning i industriella anläggningar, tekniska rum, underjordiska utrymmen och andra platser där hög säkerhet är avgörande. Deras robusta konstruktion och avancerade säkerhetsfunktioner gör dem till en pålitlig lösning för alla dina behov."}, {"t": "h3", "x": "Evakueringsluckor"}, {"t": "p", "x": "Kundanpassade evakueringsluckor för utrymning. Luckorna kan anpassas utifrån belastningsklass från A15 upp till F900. Finns som runda och fyrkantiga."}, {"t": "p", "x": "Tillverkas enligt ISO 9001 och ISO 14001."}, {"t": "p", "x": "Luckorna levereras med lås och gasfjädrar för att underlätta öppning och stängning."}, {"t": "h4", "x": "Evakueringslucka: snabb och säker utrymning"}, {"t": "p", "x": "En evakueringslucka är en kritisk komponent för att säkerställa snabb och säker utrymning i nödsituationer. På Svenska Brunnslock erbjuder vi evakueringsluckor som är designade för att ge enkel åtkomst och snabb evakuering."}, {"t": "h4", "x": "Fördelar med evakueringsluckor"}, {"t": "p", "x": "Evakueringsluckor är utformade för att möjliggöra snabb och säker utrymning i händelse av nödsituationer, såsom bränder, gasläckor eller andra faror. De är lätta att öppna och ger en tydlig och snabb väg ut, vilket minskar risken för panik och skador. Genom att använda evakueringsluckor från Svenska Brunnslock kan du säkerställa att dina anläggningar är förberedda för alla eventualiteter."}], "faq": []}, "fi": {"intro": "Meillä on laaja valikoima toiveiden mukaan mittatilauksena valmistettavia turvaluukkuja. Luukut voidaan mukauttaa turvallisuusluokan 1-4 ja EN124:n mukaisen kuormitusluokan A15 kN - F900 kN mukaan.", "introDraft": false, "h": "Tietoa turva- ja poistumisluukuista", "blocks": [{"t": "p", "x": "Valmistetaan ISO 9001- ja ISO 14001 -standardien mukaisesti."}, {"t": "p", "x": "Luukut voidaan valmistaa monista eri materiaaleista, kuten:"}, {"t": "ul", "items": ["Galvanoitu teräs", "Ruostumaton teräs", "Alumiini", "Pallografiittivalurauta (valurauta)", "Komposiittimateriaali."]}, {"t": "h3", "x": "Turvaluukku: optimaalinen suojaus ja turvallisuus"}, {"t": "p", "x": "Turvaluukku on kriittinen komponentti turvallisuuden ja suojauksen varmistamisessa erilaisissa ympäristöissä, kuten teollisuuslaitoksissa, teknisissä tiloissa ja maanalaisissa tiloissa. Svenska Brunnslockilla tarjoamme turvaluukkuja, joissa yhdistyvät tukevuus ja edistyneet turvaominaisuudet. Tässä käymme läpi tuotteidemme edut, eri vaihtoehdot ja niiden käytön."}, {"t": "h3", "x": "Turvaluukkujen edut"}, {"t": "p", "x": "Turvaluukut suojaavat luvattomalta pääsyltä ja ehkäisevät onnettomuuksia tarjoamalla turvallisen ja valvotun pääsyn kriittisiin tiloihin. Ne on suunniteltu kestäviksi ja murronkestäviksi, mikä tekee niistä ihanteellisia käytettäviksi herkissä ja korkean turvallisuustason ympäristöissä. Käyttämällä Svenska Brunnslockin turvaluukkuja voit varmistaa laitoksillesi korkeimman tason suojauksen ja turvallisuuden."}, {"t": "h3", "x": "Tuotteemme"}, {"t": "p", "x": "Tarjoamme turvaluukkuja eri kokoina ja materiaaleina, mukaan lukien teräs ja alumiini, sopimaan erilaisiin tarpeisiin ja käyttökohteisiin. Tuotteemme on varustettu edistyneillä lukitusjärjestelmillä ja turvaominaisuuksilla, jotka takaavat maksimaalisen turvallisuuden ja luotettavuuden. Olivatpa erityisvaatimuksesi mitkä tahansa, meiltä löytyy oikea ratkaisu sinulle."}, {"t": "h3", "x": "Käyttö ja asennus"}, {"t": "p", "x": "Turvaluukut on helppo asentaa ja käyttää. Tuotteidemme mukana toimitetaan yksityiskohtaiset asennusohjeet, jotka varmistavat oikean asennuksen ja optimaalisen turvallisuuden. Noudattamalla näitä ohjeita voit nopeasti ja helposti parantaa laitostesi suojausta ja turvallisuutta."}, {"t": "h3", "x": "Käyttökohteet"}, {"t": "p", "x": "Turvaluukut ovat monipuolisia, ja niitä voidaan käyttää monenlaisissa ympäristöissä. Ne sopivat täydellisesti käytettäviksi teollisuuslaitoksissa, teknisissä tiloissa, maanalaisissa tiloissa ja muissa paikoissa, joissa korkea turvallisuus on ratkaisevan tärkeää. Niiden tukeva rakenne ja edistyneet turvaominaisuudet tekevät niistä luotettavan ratkaisun kaikkiin tarpeisiisi."}, {"t": "h3", "x": "Poistumisluukut"}, {"t": "p", "x": "Asiakkaan tarpeisiin mukautetut poistumisluukut hätäpoistumiseen. Luukut voidaan mukauttaa kuormitusluokan mukaan A15:stä aina F900:aan. Saatavana pyöreinä ja nelikulmaisina."}, {"t": "p", "x": "Valmistetaan ISO 9001- ja ISO 14001 -standardien mukaisesti."}, {"t": "p", "x": "Luukut toimitetaan lukolla ja kaasujousilla, jotka helpottavat avaamista ja sulkemista."}, {"t": "h4", "x": "Poistumisluukku: nopea ja turvallinen poistuminen"}, {"t": "p", "x": "Poistumisluukku on kriittinen komponentti nopean ja turvallisen poistumisen varmistamisessa hätätilanteissa. Svenska Brunnslockilla tarjoamme poistumisluukkuja, jotka on suunniteltu tarjoamaan helppo pääsy ja nopea evakuointi."}, {"t": "h4", "x": "Poistumisluukkujen edut"}, {"t": "p", "x": "Poistumisluukut on suunniteltu mahdollistamaan nopea ja turvallinen poistuminen hätätilanteissa, kuten tulipaloissa, kaasuvuodoissa tai muissa vaaratilanteissa. Ne on helppo avata, ja ne tarjoavat selkeän ja nopean reitin ulos, mikä vähentää paniikin ja loukkaantumisten riskiä. Käyttämällä Svenska Brunnslockin poistumisluukkuja voit varmistaa, että laitoksesi ovat valmistautuneet kaikkiin mahdollisiin tilanteisiin."}], "faq": []}}, "lock/kund": {"status": "befintlig", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/luckor/kundanpassade-luckor", "name": "Kundanpassade luckor", "use": "text"}], "words": 79, "faqWords": 0, "check": "\"De senaste 10 åren\" ajantasaisuus.", "sv": {"intro": "Trots vårt breda sortiment av luckor och betäckningar så förekommer det, relativt ofta, att de standardluckor vi har inte passar för avsett ändamål. Kundanpassade luckor är i de fallen en lösning.", "introDraft": false, "blocks": [{"t": "p", "x": "Dessa finns med belastningsklass A15 till F900 enligt EN124."}, {"t": "p", "x": "De senaste 10 åren har vi levererat kundspecifika luckor runtom i hela Skandinavien, till industrier, kommuner, entreprenörer och privatpersoner. Ett större känt projekt är Förbifart Stockholm dit har vi levererat mer än 50 st. körbara luckor med höga belastningskrav."}], "faq": []}, "fi": {"intro": "Laajasta luukku- ja kansistovalikoimastamme huolimatta tulee suhteellisen usein vastaan tilanteita, joissa vakioluukkumme eivät sovi aiottuun käyttötarkoitukseen. Mittatilausluukut ovat näissä tapauksissa ratkaisu.", "introDraft": false, "h": "Tietoa mittatilausluukuista", "blocks": [{"t": "p", "x": "Niitä on saatavana kuormitusluokissa A15-F900 EN124:n mukaisesti."}, {"t": "p", "x": "Viimeisten 10 vuoden aikana olemme toimittaneet asiakaskohtaisia luukkuja eri puolille Skandinaviaa teollisuudelle, kunnille, urakoitsijoille ja yksityishenkilöille. Suurempi tunnettu hanke on Förbifart Stockholm, johon olemme toimittaneet yli 50 kpl ajettavia luukkuja, joilla on korkeat kuormitusvaatimukset."}], "faq": []}}, "lock/tillbehor": {"status": "kombinerad", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/betackningar/lockoppnare", "name": "Locköppnare", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/brunnslock/avluftningsventil-tatningslist", "name": "Avluftningsventil & tätningslist", "use": "faq"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/luckor/lockoppnare-2", "name": "Locköppnare", "use": "sammanfogad"}], "words": 201, "faqWords": 111, "check": "Teksti koskee vain kannennostimia; kategoriassa myös tiivisteet ja venttiilit (FAQ kattaa ne).", "sv": {"intro": "En locköppnare är ett oumbärligt verktyg för att enkelt och säkert öppna och stänga brunnslock. På Svenska Brunnslock erbjuder vi locköppnare som är designade för att göra arbetet smidigare och säkrare.", "introDraft": false, "blocks": [{"t": "p", "x": "Lyftnyckel, verktyg för öppning av brunnslock i gjutjärn/segjärn"}, {"t": "h3", "x": "Locköppnare: enkel och säker hantering av brunnslock"}, {"t": "p", "x": "Här går vi igenom fördelarna med våra produkter, de olika alternativen och deras användning."}, {"t": "h3", "x": "Fördelar med locköppnare"}, {"t": "p", "x": "Locköppnare gör det möjligt att enkelt och säkert hantera tunga brunnslock, vilket minskar risken för skador och underlättar underhållsarbete. De är särskilt användbara för kommuner, industrier och andra organisationer som regelbundet behöver öppna och stänga brunnslock. Genom att använda locköppnare från Svenska Brunnslock kan du effektivisera ditt arbete och förbättra säkerheten."}, {"t": "h3", "x": "Våra produkter"}, {"t": "p", "x": "Vi erbjuder locköppnare i olika modeller och storlekar för att passa olika typer av brunnslock. Våra produkter är tillverkade av robusta material som garanterar lång hållbarhet och pålitlig prestanda. Oavsett dina specifika behov har vi rätt locköppnare för dig."}, {"t": "h3", "x": "Användning och installation"}, {"t": "p", "x": "Locköppnare är enkla att använda och kräver ingen omfattande utbildning. Våra produkter levereras med tydliga instruktioner för att säkerställa korrekt användning och maximal effektivitet. Genom att följa dessa anvisningar kan du snabbt och enkelt hantera brunnslock på ett säkert och effektivt sätt."}], "faq": [{"q": "Vilken funktion har en avluftningsventil i ett brunnslock?", "a": ["En avluftningsventil förhindrar övertryck i brunnsystemet och säkerställer korrekt ventilation, dels vid toalettspolning för avloppsbrunnar."]}, {"q": "Vilka storlekar finns tillgängliga för tätningslister?", "a": ["Vi erbjuder tätningslister i storlekar från 600 mm upp till 1340 mm i diameter för att passa olika brunnsdimensioner."]}, {"q": "Är tätningslisterna vattentäta?", "a": ["Ja, våra tätningslister är vattentäta och förhindrar att smuts och vatten tränger in i brunnen."]}, {"q": "Kan jag installera en avluftningsventil själv?", "a": ["Installation av avluftningsventilen är enkel och kan utföras av de flesta utan professionell hjälp, men vid tveksamheter rekommenderas fackman."]}, {"q": "Finns det extra tillbehör till avluftningsventiler?", "a": ["Ja, vi erbjuder bland annat en hänglåsadapter som tillval för att ytterligare säkra avluftningsventilen."]}]}, "fi": {"intro": "Kannennostin on korvaamaton työkalu kaivonkansien helppoon ja turvalliseen avaamiseen ja sulkemiseen. Svenska Brunnslockilla tarjoamme kannennostimia, jotka on suunniteltu tekemään työstä sujuvampaa ja turvallisempaa.", "introDraft": false, "h": "Tietoa kannennostimista ja tarvikkeista", "blocks": [{"t": "p", "x": "Nostoavain, työkalu valurautaisten tai pallografiittivalurautaisten kaivonkansien avaamiseen"}, {"t": "h3", "x": "Kannennostin: kaivonkansien helppo ja turvallinen käsittely"}, {"t": "p", "x": "Tässä käymme läpi tuotteidemme edut, eri vaihtoehdot ja niiden käytön."}, {"t": "h3", "x": "Kannennostimien edut"}, {"t": "p", "x": "Kannennostimien avulla painavia kaivonkansia voi käsitellä helposti ja turvallisesti, mikä vähentää loukkaantumisriskiä ja helpottaa kunnossapitotyötä. Ne ovat erityisen hyödyllisiä kunnille, teollisuudelle ja muille organisaatioille, joiden täytyy säännöllisesti avata ja sulkea kaivonkansia. Käyttämällä Svenska Brunnslockin kannennostimia voit tehostaa työtäsi ja parantaa turvallisuutta."}, {"t": "h3", "x": "Tuotteemme"}, {"t": "p", "x": "Tarjoamme kannennostimia eri malleina ja kokoina sopimaan erityyppisiin kaivonkansiin. Tuotteemme on valmistettu tukevista materiaaleista, jotka takaavat pitkän kestävyyden ja luotettavan suorituskyvyn. Olivatpa erityistarpeesi mitkä tahansa, meiltä löytyy sinulle oikea kannennostin."}, {"t": "h3", "x": "Käyttö ja asennus"}, {"t": "p", "x": "Kannennostimet ovat helppokäyttöisiä eivätkä vaadi laajaa koulutusta. Tuotteidemme mukana toimitetaan selkeät ohjeet, jotka varmistavat oikean käytön ja maksimaalisen tehokkuuden. Noudattamalla näitä ohjeita voit nopeasti ja helposti käsitellä kaivonkansia turvallisesti ja tehokkaasti."}], "faq": [{"q": "Mikä tehtävä kaivonkannen ilmanpoistoventtiilillä on?", "a": ["Ilmanpoistoventtiili estää ylipaineen kaivojärjestelmässä ja varmistaa asianmukaisen tuuletuksen, muun muassa jätevesikaivoissa WC:n huuhtelun yhteydessä."]}, {"q": "Missä kooissa tiivistelistoja on saatavana?", "a": ["Tarjoamme tiivistelistoja halkaisijaltaan 600 mm:stä aina 1340 mm:iin sopimaan erilaisiin kaivojen mittoihin."]}, {"q": "Ovatko tiivistelistat vesitiiviitä?", "a": ["Kyllä, tiivistelistamme ovat vesitiiviitä ja estävät lian ja veden pääsyn kaivoon."]}, {"q": "Voinko asentaa ilmanpoistoventtiilin itse?", "a": ["Ilmanpoistoventtiilin asennus on helppoa, ja useimmat pystyvät tekemään sen ilman ammattilaisen apua, mutta epäselvissä tapauksissa suositellaan ammattilaista."]}, {"q": "Onko ilmanpoistoventtiileihin saatavana lisätarvikkeita?", "a": ["Kyllä, tarjoamme muun muassa lisävarusteena riippulukkoadapterin, jolla ilmanpoistoventtiilin voi lukita entistä varmemmin."]}]}}, "el": {"status": "utkast", "sources": [], "words": 147, "faqWords": 0, "check": "Luonnos alakategorioiden teksteistä. Tarkista toimialat ja kuormitusluvut.", "sv": {"intro": "Kabelbrunnar, skarvbrunnar, kabelrännor och kabelskyddsrör för el-, tele- och datanät i mark, längs väg och järnväg. Vi levererar bland annat till järnvägar, ställverk och vindkraftsparker.", "introDraft": true, "blocks": [{"t": "h3", "x": "Kabelbrunnar", "d": true}, {"t": "p", "x": "Kabelbrunnar finns i komposit och betong. Kompositbrunnarna UC och OXPRO klarar belastningar på 40 ton (D400) utan motgjutning, OXPRO upp till 90 ton (F900). NEXUS är dimensionerad för upp till 25 ton (C250) och har modulär konstruktion.", "d": true}, {"t": "h3", "x": "Skarv- och optobrunnar", "d": true}, {"t": "p", "x": "Skarvlådor och dragbrunnar i betong med gjutjärnsbetäckning, samt optobrunnar och slingbrunnar med vattentätt lock för optisk kabel.", "d": true}, {"t": "h3", "x": "Kabelrännor, kabelskyddsrör och flerfackskanaler", "d": true}, {"t": "p", "x": "Kabelrännor och kabelkanaler finns i komposit, aluminium och betong, även körbara betongrännor för överfarter och tung trafik. Kabelskyddsrör finns som släta rör enligt Verksnorm 5200 och som delbara rör för redan installerad kabel. Flerfackskanaler används som tvärkanalisation under vägar och järnvägar.", "d": true}, {"t": "p", "x": "Välj en produktgrupp ovan, eller ring oss på 0920-52 00 56 om du vill ha hjälp att välja.", "d": true}], "faq": []}, "fi": {"intro": "Kaapelikaivot, jatkoskaivot, kaapelikourut ja kaapelinsuojaputket sähkö-, tele- ja dataverkkoihin maahan sekä teiden ja rautateiden varsille. Toimitamme muun muassa rautateille, sähköasemille ja tuulivoimapuistoihin.", "introDraft": true, "h": "Tietoa sähköinfrasta", "blocks": [{"t": "h3", "x": "Kaapelikaivot", "d": true}, {"t": "p", "x": "Kaapelikaivoja on saatavana komposiittisina ja betonisina. Komposiittikaivot UC ja OXPRO kestävät 40 tonnin kuormat (D400) ilman vastavalua, OXPRO aina 90 tonniin asti (F900). NEXUS on mitoitettu enintään 25 tonnin kuormille (C250), ja sen rakenne on modulaarinen.", "d": true}, {"t": "h3", "x": "Jatkos- ja optokaivot", "d": true}, {"t": "p", "x": "Betoniset jatkoskaivot ja vetokaivot valurautakansistolla sekä optokaivot ja lenkkikaivot, joissa on vesitiivis kansi optiselle kaapelille.", "d": true}, {"t": "h3", "x": "Kaapelikourut, kaapelinsuojaputket ja monikanavaputket", "d": true}, {"t": "p", "x": "Kaapelikouruja ja kaapelikanavia on saatavana komposiitista, alumiinista ja betonista, myös ajettavina betonikouruina ylityskohtiin ja raskaalle liikenteelle. Kaapelinsuojaputkia on saatavana sileinä putkina Verksnorm 5200 -normin mukaisesti sekä jaettavina putkina jo asennetulle kaapelille. Monikanavaputkia käytetään poikittaiskanavointina teiden ja rautateiden alla.", "d": true}, {"t": "p", "x": "Valitse tuoteryhmä yllä tai soita meille numeroon 0920-52 00 56, jos haluat apua valinnassa.", "d": true}], "faq": []}}, "el/kabelbrunn": {"status": "kombinerad", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/kabelbrunnar-2", "name": "Kabelbrunnar", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/kabelbrunnar-2/kabelbrunn-i-komposit", "name": "Kabelbrunn UC", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/kabelbrunnar-2/oxpro", "name": "Kabelbrunn OXPRO", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/kabelbrunnar-2/kabelbrunn-nexus", "name": "Kabelbrunn NEXUS", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/material-kabelbrunnar/kabelbrunn", "name": "Brunnsring kabelbrunn", "use": "text+faq"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/kabelbrunnar-2/kabelbrunn-i-betong", "name": "Kabelbrunn i betong (rund)", "use": "sammanfogad"}], "words": 728, "faqWords": 81, "check": "Viisi tekstiä yhdistetty (yleinen + UC, OXPRO, NEXUS, betoni). \"Marknadens kraftigaste och mest prisvärda\" (OXPRO) on SB:n oma väite.", "sv": {"intro": "Vi levererar olika typer av kabelbrunnar till ett flertal infrastrukturområden som till järnvägar, ställverk, vindkraftsparker, mm.", "introDraft": false, "blocks": [{"t": "h3", "x": "Kabelbrunn: central komponent för effektiv kabelhantering"}, {"t": "p", "x": "På Svenska Brunnslock är vi experter på infrastrukturlösningar och förstår vikten av effektiv kabelhantering i moderna byggprojekt och stadsutveckling. Vår produktkategori för kabelbrunn är speciellt utvecklad för att tillgodose behovet av säker och organiserad kabeldragning. Vad är en kabelbrunn och vilka är de avgörande fördelarna med att använda dem i ditt projekt?"}, {"t": "h4", "x": "Vad är en kabelbrunn?"}, {"t": "p", "x": "En kabelbrunn är en underjordisk installation som används för att husera och skydda elektriska kablar och ledningar. Det är en viktig del av infrastrukturen för el-, tele-, och datanät, vilket möjliggör enkel åtkomst för underhåll samt skydd mot yttre påverkan. Kabelbrunnar från Svenska Brunnslock är tillverkade av hållbara material som betong, plast eller aluminium och är designade för att tåla de påfrestningar som kan uppstå från såväl miljön som mänsklig aktivitet."}, {"t": "h4", "x": "Fördelar med kabelbrunnar från Svenska Brunnslock"}, {"t": "p", "x": "Att investera i kabelbrunnar från Svenska Brunnslock innebär flera konkreta fördelar:"}, {"t": "p", "x": "Skydd: Våra kabelbrunnar ger överlägset skydd för känsliga kablar och ledningar, vilket minskar risken för skador och förlänga deras livslängd."}, {"t": "p", "x": "Tillgänglighet: Genom att använda kabelbrunnar underlättas underhållsarbeten, eftersom tekniker enkelt kan få åtkomst till kablarna utan att behöva gräva."}, {"t": "p", "x": "Organisering: De hjälper till att hålla kablar organiserade, vilket förenklar både diagnostik av problem och framtida uppgraderingar av nätverket."}, {"t": "p", "x": "Säkerhet: Korrekt installerade kabelbrunnar minskar risken för olyckor och skador för både personal och allmänheten."}, {"t": "h4", "x": "Välja rätt kabelbrunn"}, {"t": "p", "x": "Att välja rätt kabelbrunn är avgörande för projektets framgång. På Svenska Brunnslock erbjuder vi kabelbrunnar i olika storlekar och modeller för att matcha de specifika behoven i ditt projekt, oavsett om det är stora infrastrukturprojekt eller mindre installationer. Vårt expertteam kan hjälpa dig att välja rätt modell baserat på dina krav och de tekniska specifikationerna för ditt projekt."}, {"t": "p", "x": "Våra modeller:"}, {"t": "ul", "items": ["Kabelbrunn OXPRO", "Kabelbrunn i komposit", "Kabelbrunn NEXUS", "Kabelbrunn i betong", "Kabelbrunn skarvlåda 3-lock", "Optobrunn och slingbrunn"]}, {"t": "h4", "x": "Investera i kabelbrunnar från Svenska Brunnslock"}, {"t": "p", "x": "Genom att investera i kabelbrunnar från Svenska Brunnslock säkerställer du att ditt projekt är utrustat med en lösning som erbjuder hållbarhet, effektivitet och hög prestanda. Kontakta oss idag för att diskutera hur våra kabelbrunnar kan integreras i ditt nästa projekt och bidra till en säkrare och mer organiserad infrastruktur."}, {"t": "p", "x": "Hos Svenska Brunnslock är vi engagerade i att leverera högkvalitativa lösningar som möter och överträffar våra kunders förväntningar. Vår dedikation till innovation och kvalitet gör oss till en pålitlig partner i ditt projekt."}, {"t": "h3", "x": "Kabelbrunn i komposit UC"}, {"t": "p", "x": "Ultima Connect är en modulär och skalbar brunnslösning som enkelt monteras på plats."}, {"t": "p", "x": "Brunnen tillverkas i GRP (glasfiberarmerad polyester), bestående av glasfiber, polyester och gelcoat. Materialet ger hög kemikalie- och temperaturbeständighet. Modulerna levereras “flat packed” för en smart och yteffektiv logistik."}, {"t": "p", "x": "Brunnen är dimensionerad för att klara belastningar upp till 40 ton (D400) utan behov av motgjutning."}, {"t": "h3", "x": "Kabelbrunn OXPRO i komposit"}, {"t": "p", "x": "Marknadens kraftigaste och mest prisvärda kompositbrunn! Den klarar en belastning från 40 ton (D400) upp till 90 ton (F900) utan motgjutning och är därmed den starkaste och effektivaste kompositbrunnen som finns på marknaden."}, {"t": "h4", "x": "Så väljer du rätt OXPRO i 3 steg"}, {"t": "ul", "items": ["Välj invändigt mått utifrån hur mycket utrymme du behöver för skarvar, kabelslingor och montage. OXPRO finns i bl.a. 600×600, 750×750, 900×600, 900×900, 1200×600, 1200×1200, 1500×750, 1500×1500, 2250×750.", "Välj höjd/djup genom att bygga brunnen i 150 mm-moduler tills du når önskat mått."]}, {"t": "p", "x": "Välj lucka/lock utifrån placering och inspektionsbehov (t.ex. gångjärn för frekvent öppning). Vi har luckor för brunnens alla storlekar och era behov."}, {"t": "h3", "x": "Kabelbrunn NEXUS"}, {"t": "p", "x": "En mycket konkurrenskraftig kabelbrunn i komposit med dubbelväggs konstruktion, dimensionerad för att klara belastningar upp till 25 ton (C250) utan behov av motgjutning."}, {"t": "p", "x": "Brunnen är lämplig för användning i exempelvis grönområden, parkeringar, trottoarer och vägar, och fungerar utmärkt som installations- och dragbrunn för kablar m.m. Den finns i flera olika storlekar och kan levereras med betäckning."}, {"t": "p", "x": "Nexus-brunnen har en modulär konstruktion som möjliggör anpassning i både storlek och höjd efter behov."}, {"t": "h3", "x": "Kabelbrunn i betong"}, {"t": "p", "x": "Brunnsringar i betong sätts ihop av flera ringar till önskad höjd. Vi har brunnsringar med innerdiameter från 500, 3000mm."}, {"t": "h4", "x": "Brunnsring: viktig komponent för kabelbrunnar"}, {"t": "p", "x": "En brunnsring är en central del av kabelbrunnar, som bidrar till strukturell integritet och skydd av kablar. På Svenska Brunnslock erbjuder vi högkvalitativa brunnsringar som är utformade för att möta de stränga kraven på hållbarhet och prestanda."}], "faq": [{"q": "Vad är syftet med en kabelbrunn?", "a": ["En kabelbrunn skyddar elektriska och kommunikationskablar under marken och gör dem lätt åtkomliga för underhåll och reparation."]}, {"q": "Vilka storlekar finns för kabelbrunnar?", "a": ["Våra kabelbrunnar finns i storlekar från 500 mm till 3000 mm i innerdiameter för att passa olika installationsbehov."]}, {"q": "Är kabelbrunnar väderbeständiga?", "a": ["Ja, våra kabelbrunnar är konstruerade för att klara tuffa väderförhållanden och ge långvarigt skydd."]}, {"q": "Hur installeras en kabelbrunn?", "a": ["Installationen är relativt enkel och våra kabelbrunnar levereras med tydliga installationsanvisningar för korrekt montering."]}]}, "fi": {"intro": "Toimitamme erityyppisiä kaapelikaivoja useille infrastruktuurin osa-alueille, kuten rautateille, sähköasemille, tuulivoimapuistoihin ym.", "introDraft": false, "h": "Tietoa kaapelikaivoista", "blocks": [{"t": "h3", "x": "Kaapelikaivo: keskeinen osa tehokasta kaapelinhallintaa"}, {"t": "p", "x": "Svenska Brunnslockilla olemme infrastruktuuriratkaisujen asiantuntijoita ja ymmärrämme tehokkaan kaapelinhallinnan merkityksen nykyaikaisissa rakennushankkeissa ja kaupunkikehityksessä. Kaapelikaivojen tuoteryhmämme on kehitetty erityisesti turvallisen ja järjestelmällisen kaapeloinnin tarpeisiin. Mikä kaapelikaivo on, ja mitkä ovat sen käytön ratkaisevat edut hankkeessasi?"}, {"t": "h4", "x": "Mikä on kaapelikaivo?"}, {"t": "p", "x": "Kaapelikaivo on maanalainen asennus, jota käytetään sähkökaapeleiden ja johtojen sijoittamiseen ja suojaamiseen. Se on tärkeä osa sähkö-, tele- ja dataverkkojen infrastruktuuria, ja se mahdollistaa helpon pääsyn huoltoa varten sekä suojan ulkoisilta vaikutuksilta. Svenska Brunnslockin kaapelikaivot on valmistettu kestävistä materiaaleista, kuten betonista, muovista tai alumiinista, ja ne on suunniteltu kestämään rasituksia, joita voi aiheutua sekä ympäristöstä että ihmisen toiminnasta."}, {"t": "h4", "x": "Svenska Brunnslockin kaapelikaivojen edut"}, {"t": "p", "x": "Svenska Brunnslockin kaapelikaivoihin investoiminen tuo useita konkreettisia etuja:"}, {"t": "p", "x": "Suojaus: Kaapelikaivomme tarjoavat ylivertaisen suojan herkille kaapeleille ja johdoille, mikä vähentää vaurioiden riskiä ja pidentää niiden käyttöikää."}, {"t": "p", "x": "Saavutettavuus: Kaapelikaivot helpottavat huoltotöitä, koska teknikot pääsevät kaapeleihin helposti ilman kaivamista."}, {"t": "p", "x": "Järjestys: Ne auttavat pitämään kaapelit järjestyksessä, mikä helpottaa sekä vianmääritystä että verkon tulevia päivityksiä."}, {"t": "p", "x": "Turvallisuus: Oikein asennetut kaapelikaivot vähentävät onnettomuuksien ja vahinkojen riskiä sekä henkilöstölle että yleisölle."}, {"t": "h4", "x": "Oikean kaapelikaivon valinta"}, {"t": "p", "x": "Oikean kaapelikaivon valinta on ratkaisevaa hankkeen onnistumiselle. Svenska Brunnslockilla tarjoamme kaapelikaivoja eri kokoina ja malleina hankkeesi erityistarpeisiin, olipa kyseessä suuri infrastruktuurihanke tai pienempi asennus. Asiantuntijatiimimme voi auttaa sinua valitsemaan oikean mallin vaatimustesi ja hankkeesi teknisten määritysten perusteella."}, {"t": "p", "x": "Mallimme:"}, {"t": "ul", "items": ["Kaapelikaivo OXPRO", "Kaapelikaivo komposiitista", "Kaapelikaivo NEXUS", "Kaapelikaivo betonista", "Kaapelikaivo, jatkoskaivo 3 kantta", "Optokaivo ja lenkkikaivo"]}, {"t": "h4", "x": "Investoi Svenska Brunnslockin kaapelikaivoihin"}, {"t": "p", "x": "Investoimalla Svenska Brunnslockin kaapelikaivoihin varmistat, että hankkeessasi on ratkaisu, joka tarjoaa kestävyyttä, tehokkuutta ja korkean suorituskyvyn. Ota yhteyttä jo tänään, niin keskustellaan siitä, miten kaapelikaivomme voidaan integroida seuraavaan hankkeeseesi ja miten ne voivat edistää turvallisempaa ja järjestelmällisempää infrastruktuuria."}, {"t": "p", "x": "Svenska Brunnslockilla olemme sitoutuneet toimittamaan korkealaatuisia ratkaisuja, jotka täyttävät ja ylittävät asiakkaidemme odotukset. Omistautumisemme innovaatioille ja laadulle tekee meistä luotettavan kumppanin hankkeeseesi."}, {"t": "h3", "x": "Kaapelikaivo komposiitista UC"}, {"t": "p", "x": "Ultima Connect on modulaarinen ja skaalautuva kaivoratkaisu, joka on helppo koota paikan päällä."}, {"t": "p", "x": "Kaivo valmistetaan GRP:stä (lasikuituvahvisteinen polyesteri), joka koostuu lasikuidusta, polyesteristä ja gelcoatista. Materiaali kestää hyvin kemikaaleja ja lämpötiloja. Moduulit toimitetaan litteinä pakkauksina (“flat packed”), mikä tekee logistiikasta fiksua ja tilatehokasta."}, {"t": "p", "x": "Kaivo on mitoitettu kestämään enintään 40 tonnin kuormat (D400) ilman vastavalua."}, {"t": "h3", "x": "Kaapelikaivo OXPRO komposiitista"}, {"t": "p", "x": "Markkinoiden vahvin ja hinta-laatusuhteeltaan paras komposiittikaivo! Se kestää kuormitusta 40 tonnista (D400) aina 90 tonniin (F900) ilman vastavalua ja on siten markkinoiden vahvin ja tehokkain komposiittikaivo."}, {"t": "h4", "x": "Näin valitset oikean OXPRO:n 3 vaiheessa"}, {"t": "ul", "items": ["Valitse sisämitta sen mukaan, kuinka paljon tilaa tarvitset jatkoksille, kaapelilenkeille ja asennukselle. OXPRO:ta on saatavana mm. kokoina 600×600, 750×750, 900×600, 900×900, 1200×600, 1200×1200, 1500×750, 1500×1500, 2250×750.", "Valitse korkeus/syvyys rakentamalla kaivo 150 mm:n moduuleista, kunnes saavutat halutun mitan."]}, {"t": "p", "x": "Valitse luukku/kansi sijoituksen ja tarkastustarpeen mukaan (esim. saranat, jos kantta avataan usein). Meillä on luukkuja kaikkiin kaivokokoihin ja tarpeisiinne."}, {"t": "h3", "x": "Kaapelikaivo NEXUS"}, {"t": "p", "x": "Erittäin kilpailukykyinen kaksiseinäinen komposiittikaapelikaivo, joka on mitoitettu kestämään enintään 25 tonnin kuormat (C250) ilman vastavalua."}, {"t": "p", "x": "Kaivo soveltuu käytettäväksi esimerkiksi viheralueilla, pysäköintialueilla, jalkakäytävillä ja teillä, ja se toimii erinomaisesti kaapeleiden ym. asennus- ja vetokaivona. Sitä on saatavana useina eri kokoina, ja se voidaan toimittaa kansiston kanssa."}, {"t": "p", "x": "Nexus-kaivon modulaarinen rakenne mahdollistaa sekä koon että korkeuden mukauttamisen tarpeen mukaan."}, {"t": "h3", "x": "Kaapelikaivo betonista"}, {"t": "p", "x": "Betoniset kaivonrenkaat kootaan useista renkaista haluttuun korkeuteen. Meillä on kaivonrenkaita sisähalkaisijaltaan 500-3000 mm."}, {"t": "h4", "x": "Kaivonrengas: tärkeä osa kaapelikaivoja"}, {"t": "p", "x": "Kaivonrengas on kaapelikaivojen keskeinen osa, joka lisää rakenteellista eheyttä ja suojaa kaapeleita. Svenska Brunnslockilla tarjoamme korkealaatuisia kaivonrenkaita, jotka on suunniteltu täyttämään kestävyyden ja suorituskyvyn tiukat vaatimukset."}], "faq": [{"q": "Mikä on kaapelikaivon tarkoitus?", "a": ["Kaapelikaivo suojaa sähkö- ja tietoliikennekaapeleita maan alla ja tekee niistä helposti saavutettavia huoltoa ja korjausta varten."]}, {"q": "Minkä kokoisia kaapelikaivoja on saatavana?", "a": ["Kaapelikaivojamme on saatavana sisähalkaisijaltaan 500 mm:stä 3000 mm:iin erilaisiin asennustarpeisiin."]}, {"q": "Ovatko kaapelikaivot säänkestäviä?", "a": ["Kyllä, kaapelikaivomme on suunniteltu kestämään vaativia sääolosuhteita ja antamaan pitkäaikaisen suojan."]}, {"q": "Miten kaapelikaivo asennetaan?", "a": ["Asennus on suhteellisen helppoa, ja kaapelikaivojemme mukana toimitetaan selkeät asennusohjeet oikeaa kokoamista varten."]}]}}, "el/skarv": {"status": "kombinerad + utkast", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/kabelbrunnar-2/kabelbrunn-skarvlada-3-lock", "name": "Kabelbrunn Skarvlåda 3-lock", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/kabelbrunnar-2/opto-slingbrunn", "name": "Opto/slingbrunn", "use": "text"}], "words": 104, "faqWords": 0, "check": "Lyhyet vanhat tekstit + luonnoslisäys tuotekuvauksesta. RISTIRIITA: vanha teksti Ø110 tai 160 mm, tuotekuvaus Ø120 mm.", "sv": {"intro": "Kabelbrunn typ K-Prefabs Skarvlåda 3-lock förberedd med 8st hål Ø110 eller 160mm i varje gavel eller motsvarande, inklusive körbar beteckning.", "introDraft": false, "blocks": [{"t": "h3", "x": "Optobrunn och slingbrunn"}, {"t": "p", "x": "Optobrunn/slingbrunn/kopplingsbrunn."}, {"t": "p", "x": "Anslutningskammare för optisk kabel med vattentätt lock med gummitätning för underjordiska installationer."}, {"t": "h3", "x": "Dragbrunn och skarvbrunn i betong", "d": true}, {"t": "p", "x": "Rektangulär kabelbrunn av typ skarvlåda i våtgjuten betong utan botten, med 8 hål Ø120 mm i varje gavel. De fyra nedersta hålen har slits och kan avlägsnas vid montage på befintlig kabeldragning. Brunnen är dimensionerad för trafiklast upp till 40 ton och har flytande gjutjärnsbetäckning med stålram och tre lock för enkel nivåanpassning. Nyckel till låsgallret finns som tillbehör.", "d": true}], "faq": []}, "fi": {"intro": "Kaapelikaivo, tyyppi K-Prefabin jatkoskaivo 3 kantta, valmiiksi varustettu 8 kpl Ø110 tai 160 mm reiällä kummassakin päädyssä tai vastaavalla, sisältää ajettavan kansiston.", "introDraft": false, "h": "Tietoa jatkos- ja optokaivoista", "blocks": [{"t": "h3", "x": "Optokaivo ja lenkkikaivo"}, {"t": "p", "x": "Optokaivo/lenkkikaivo/kytkentäkaivo."}, {"t": "p", "x": "Optisen kaapelin liitäntäkammio maanalaisiin asennuksiin, vesitiiviillä kumitiivisteisellä kannella."}, {"t": "h3", "x": "Vetokaivo ja jatkoskaivo betonista", "d": true}, {"t": "p", "x": "Suorakaiteen muotoinen jatkoskaivotyyppinen kaapelikaivo märkävalettua betonia ilman pohjaa, 8 reikää Ø120 mm kummassakin päädyssä. Neljä alinta reikää on uritettu, ja ne voidaan irrottaa, kun kaivo asennetaan olemassa olevan kaapeloinnin kohdalle. Kaivo on mitoitettu enintään 40 tonnin liikennekuormalle, ja siinä on kelluva valurautakansisto teräskehyksellä ja kolmella kannella helppoa tasonsovitusta varten. Lukitusritilän avain on saatavana lisävarusteena.", "d": true}], "faq": []}}, "el/rannor": {"status": "kombinerad", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/kabelrannor", "name": "Kabelrännor", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/kabelskyddsror/broranna-kabelranna", "name": "Broränna Kabelränna", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/material-kabelbrunnar/broranna-jarnvag", "name": "Broränna Järnväg", "use": "text+faq"}], "words": 597, "faqWords": 103, "check": "Kolme tekstiä yhdistetty. Kuormat 57,5 kN ja 70 kN tarkistettava.", "sv": {"intro": "Vi levererar ett antal olika kabelkanaler och rännor i komposit-, aluminium- och betongmaterial. Användningsområden sträcker sig från järnvägar, broar, gasledningar, bensinstationer, el-ställverk mm.", "introDraft": false, "blocks": [{"t": "p", "x": "Vi är unika när det gäller körbara kabelkanaler i form av betongrännor och lock som klarar en belastning upp till 57,5kN (beräknat/hjularea) används vid överfarter eller där det förekommer tung trafik. Vid riktigt tung trafik som vid hamnar och flygplatser kan vi leverera körbara kabelkanaler med upp till 70kN (beräknat/hjularea)"}, {"t": "h3", "x": "Kabelrännor: effektiva lösningar för kabelhantering och skydd"}, {"t": "p", "x": "På Svenska Brunnslock är vi specialister på att erbjuda genomtänkta och hållbara lösningar för infrastrukturella behov. Våra kabelrännor är designade för att effektivt skydda och organisera kablar och ledningar, vilket är avgörande för säkerheten och funktionaliteten i såväl offentliga som privata miljöer. Men vad är det som gör våra kabelrännor till ett idealiskt val, och vilka fördelar medför de för ditt projekt?"}, {"t": "h4", "x": "Vad är kabelrännor?"}, {"t": "p", "x": "Kabelrännor är konstruktioner avsedda för att säkert leda och skydda elektriska kablar och ledningar. De är essentiella komponenter i byggprojekt och underhåll av infrastruktur, där de bidrar till att förebygga skador och hålla kablage organiserat och lättåtkomligt. Tillverkade från hållbara material som stål, betong eller komposit, erbjuder våra kabelrännor en robust lösning som står emot både mekanisk påverkan och väderförhållanden."}, {"t": "h4", "x": "Fördelar med kabelrännor från Svenska Brunnslock"}, {"t": "p", "x": "Investering i kabelrännor från Svenska Brunnslock kommer med flera signifikanta fördelar:"}, {"t": "ul", "items": ["Skydd: Våra kabelrännor skyddar dyrbara kablar från yttre skador såsom tryck, stötar och väderpåverkan. Detta förlänger kablagets livslängd och minskar kostnaderna för underhåll och reparationer.", "Organisering: De bidrar till en bättre organisering av kablar, vilket underlättar underhåll och eventuell felsökning. Ett välorganiserat kabelsystem är enklare att uppgradera eller ändra vid behov.", "Säkerhet: Genom att minska risken för trassel och skador på kablar förbättras även säkerheten för både anläggningen och de personer som arbetar i dess närhet.", "Estetik: Ett välorganiserat kabelsystem ser inte bara bättre ut, det kan också bidra till en mer professionell uppfattning av arbetsplatsen eller den offentliga miljön."]}, {"t": "h4", "x": "Välja rätt kabelrännor"}, {"t": "p", "x": "Att välja rätt kabelrännor kräver en förståelse för både de specifika behoven i ditt projekt och de miljöer där de ska installeras. På Svenska Brunnslock erbjuder vi en rad olika modeller som kan anpassas för att möta dessa krav, oavsett om det gäller lätta installationer för kontorsmiljöer eller tunga system för väg och järnvägsprojekt samt industriella tillämpningar."}, {"t": "h4", "x": "Investera i kabelrännor från Svenska Brunnslock"}, {"t": "p", "x": "Genom att investera i kabelrännor från Svenska Brunnslock säkerställer du inte bara en hållbar och effektiv hantering av ditt kablage, utan även en långsiktig lösning som skyddar din investering över tid. Våra produkter är konstruerade för att möta de högsta standarderna i hållbarhet och funktionalitet."}, {"t": "p", "x": "Kontakta oss idag för att lära dig mer om vårt sortiment av kabelrännor och hur vi kan assistera i att hitta den bästa lösningen för ditt projekt. På Svenska Brunnslock är vi dedikerade till att erbjuda förstklassiga produkter som förbättrar både säkerhet och effektivitet i alla typer av installationsprojekt."}, {"t": "h3", "x": "Broränna och kabelränna"}, {"t": "p", "x": "Kabelrännan används som:"}, {"t": "ul", "items": ["Broränna på broar utmed järnvägar", "Kanalisation till ställverk, eller annan verksamhet."]}, {"t": "h3", "x": "Broränna för järnväg"}, {"t": "p", "x": "Brorännor i aluminium inklusive lock, tillverkas enligt Trafikverkets ritning. Tillverkad så att den kan jordas."}, {"t": "p", "x": "Bredd invändigt: 200 mm Höjd invändigt: 150 mm."}, {"t": "h4", "x": "Vikt inklusive lock: 7 kg/m"}, {"t": "p", "x": "Vi tillverkar även brorännor i samma utförande med valfritt innermått samt med en- eller flera mellanväggar. Rännorna är slät invändigt och skadar inte elkabel."}, {"t": "h4", "x": "Broränna: hållbara lösningar för järnvägsapplikationer"}, {"t": "p", "x": "En broränna är en viktig komponent för att hantera vattenavrinning och skydda järnvägsinfrastruktur. På Svenska Brunnslock erbjuder vi robusta och hållbara brorännor som är designade för att uppfylla de specifika behoven inom järnvägsindustrin."}], "faq": [{"q": "Vad används en broränna till inom järnvägsinfrastruktur?", "a": ["En broränna används för att effektivt hantera vattenavrinning kring järnvägsspår och broar, vilket förhindrar erosion och skyddar infrastrukturen från skador."]}, {"q": "Vilka dimensioner finns för brorännor?", "a": ["Standarddimensionerna är 200 mm i bredd och 150 mm i höjd, men vi erbjuder också anpassade mått med en eller flera mellanväggar."]}, {"q": "Vilka material används för brorännor?", "a": ["Våra brorännor tillverkas i aluminium och är designade för att kunna jordas, vilket gör dem hållbara och motståndskraftiga mot korrosion."]}, {"q": "Är det enkelt att installera en broränna?", "a": ["Ja, våra brorännor är lätta att installera och levereras med tydliga instruktioner för säker och effektiv montering."]}]}, "fi": {"intro": "Toimitamme useita erilaisia kaapelikanavia ja kouruja komposiitti-, alumiini- ja betonimateriaaleista. Käyttökohteet ulottuvat rautateistä siltoihin, kaasuputkiin, huoltoasemiin, sähköasemiin ym.", "introDraft": false, "h": "Tietoa kaapelikouruista", "blocks": [{"t": "p", "x": "Olemme ainutlaatuisia ajettavissa kaapelikanavissa: betonikouruja ja kansia, jotka kestävät enintään 57,5 kN:n kuormituksen (laskettu/pyörän pinta-ala), käytetään ylityskohdissa tai paikoissa, joissa on raskasta liikennettä. Todella raskaaseen liikenteeseen, kuten satamiin ja lentokentille, voimme toimittaa ajettavia kaapelikanavia, jotka kestävät enintään 70 kN (laskettu/pyörän pinta-ala)"}, {"t": "h3", "x": "Kaapelikourut: tehokkaita ratkaisuja kaapelinhallintaan ja suojaukseen"}, {"t": "p", "x": "Svenska Brunnslockilla olemme erikoistuneet tarjoamaan harkittuja ja kestäviä ratkaisuja infrastruktuurin tarpeisiin. Kaapelikourumme on suunniteltu suojaamaan ja järjestämään kaapeleita ja johtoja tehokkaasti, mikä on ratkaisevaa turvallisuuden ja toimivuuden kannalta niin julkisissa kuin yksityisissä ympäristöissä. Mutta mikä tekee kaapelikouruistamme ihanteellisen valinnan, ja mitä etuja ne tuovat hankkeellesi?"}, {"t": "h4", "x": "Mitä kaapelikourut ovat?"}, {"t": "p", "x": "Kaapelikourut ovat rakenteita, jotka on tarkoitettu sähkökaapeleiden ja johtojen turvalliseen ohjaamiseen ja suojaamiseen. Ne ovat olennaisia osia rakennushankkeissa ja infrastruktuurin kunnossapidossa, joissa ne auttavat ehkäisemään vaurioita ja pitämään kaapeloinnin järjestyksessä ja helposti saavutettavana. Kestävistä materiaaleista, kuten teräksestä, betonista tai komposiitista, valmistetut kaapelikourumme tarjoavat järeän ratkaisun, joka kestää sekä mekaanista rasitusta että sääolosuhteita."}, {"t": "h4", "x": "Svenska Brunnslockin kaapelikourujen edut"}, {"t": "p", "x": "Svenska Brunnslockin kaapelikouruihin investoiminen tuo useita merkittäviä etuja:"}, {"t": "ul", "items": ["Suojaus: Kaapelikourumme suojaavat arvokkaita kaapeleita ulkoisilta vaurioilta, kuten paineelta, iskuilta ja sään vaikutuksilta. Tämä pidentää kaapeloinnin käyttöikää ja vähentää huolto- ja korjauskustannuksia.", "Järjestys: Ne auttavat pitämään kaapelit paremmin järjestyksessä, mikä helpottaa huoltoa ja mahdollista vianetsintää. Hyvin järjestettyä kaapelijärjestelmää on helpompi päivittää tai muuttaa tarvittaessa.", "Turvallisuus: Kun kaapeleiden sotkeutumisen ja vaurioiden riski pienenee, paranee myös sekä laitoksen että sen läheisyydessä työskentelevien ihmisten turvallisuus.", "Estetiikka: Hyvin järjestetty kaapelijärjestelmä ei ainoastaan näytä paremmalta, vaan se voi myös antaa työpaikasta tai julkisesta ympäristöstä ammattimaisemman vaikutelman."]}, {"t": "h4", "x": "Oikeiden kaapelikourujen valinta"}, {"t": "p", "x": "Oikeiden kaapelikourujen valinta edellyttää ymmärrystä sekä hankkeesi erityistarpeista että ympäristöistä, joihin ne asennetaan. Svenska Brunnslockilla tarjoamme useita erilaisia malleja, jotka voidaan mukauttaa näihin vaatimuksiin, olipa kyse kevyistä asennuksista toimistoympäristöihin tai raskaista järjestelmistä tie- ja rautatiehankkeisiin sekä teollisiin sovelluksiin."}, {"t": "h4", "x": "Investoi Svenska Brunnslockin kaapelikouruihin"}, {"t": "p", "x": "Investoimalla Svenska Brunnslockin kaapelikouruihin varmistat paitsi kaapelointisi kestävän ja tehokkaan hallinnan myös pitkäaikaisen ratkaisun, joka suojaa investointiasi ajan mittaan. Tuotteemme on suunniteltu täyttämään korkeimmat kestävyyden ja toimivuuden standardit."}, {"t": "p", "x": "Ota yhteyttä jo tänään saadaksesi lisätietoa kaapelikouruvalikoimastamme ja siitä, miten voimme auttaa löytämään hankkeeseesi parhaan ratkaisun. Svenska Brunnslockilla olemme sitoutuneet tarjoamaan ensiluokkaisia tuotteita, jotka parantavat sekä turvallisuutta että tehokkuutta kaikentyyppisissä asennushankkeissa."}, {"t": "h3", "x": "Siltakouru ja kaapelikouru"}, {"t": "p", "x": "Kaapelikourua käytetään:"}, {"t": "ul", "items": ["Siltakouruna rautateiden varrella olevilla silloilla", "Kanavointina sähköasemille tai muuhun toimintaan."]}, {"t": "h3", "x": "Siltakouru rautateille"}, {"t": "p", "x": "Alumiiniset siltakourut kansineen valmistetaan Trafikverketin piirustuksen mukaan. Valmistettu siten, että se voidaan maadoittaa."}, {"t": "p", "x": "Sisäleveys: 200 mm Sisäkorkeus: 150 mm."}, {"t": "h4", "x": "Paino kansineen: 7 kg/m"}, {"t": "p", "x": "Valmistamme myös samanlaisia siltakouruja vapaavalintaisella sisämitalla sekä yhdellä tai useammalla väliseinällä. Kourut ovat sisältä sileitä eivätkä vahingoita sähkökaapelia."}, {"t": "h4", "x": "Siltakouru: kestäviä ratkaisuja rautatiesovelluksiin"}, {"t": "p", "x": "Siltakouru on tärkeä osa valumavesien hallintaa ja rautatieinfrastruktuurin suojaamista. Svenska Brunnslockilla tarjoamme järeitä ja kestäviä siltakouruja, jotka on suunniteltu vastaamaan rautatiealan erityistarpeisiin."}], "faq": [{"q": "Mihin siltakourua käytetään rautatieinfrastruktuurissa?", "a": ["Siltakourulla hallitaan tehokkaasti valumavesiä rautatien raiteiden ja siltojen ympärillä, mikä estää eroosiota ja suojaa infrastruktuuria vaurioilta."]}, {"q": "Mitä mittoja siltakouruista on saatavana?", "a": ["Vakiomitat ovat 200 mm leveys ja 150 mm korkeus, mutta tarjoamme myös mukautettuja mittoja yhdellä tai useammalla väliseinällä."]}, {"q": "Mistä materiaaleista siltakourut valmistetaan?", "a": ["Siltakourumme valmistetaan alumiinista, ja ne on suunniteltu maadoitettaviksi, mikä tekee niistä kestäviä ja korroosionkestäviä."]}, {"q": "Onko siltakourun asentaminen helppoa?", "a": ["Kyllä, siltakourumme on helppo asentaa, ja niiden mukana toimitetaan selkeät ohjeet turvallista ja tehokasta asennusta varten."]}]}}, "el/skyddsror": {"status": "kombinerad + utkast", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/kabelskyddsror/delbara-kabelskyddsror", "name": "Delbara Kabelskyddsrör", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/kabelskyddsror/opi-distanshallare", "name": "OPI distanshållare", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/kabelskyddsror", "name": "Kabelskyddsrör", "use": "ingen text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/kabelskyddsror/slata-kabelskyddsror-srn-och-srs", "name": "Släta kabelskyddsrör SRN och SRS", "use": "ingen text"}], "words": 136, "faqWords": 0, "check": "Lyhyet vanhat tekstit + luonnoslisäys sileistä SRN/SRS-putkista tuotekuvauksista (Verksnorm 5200).", "sv": {"intro": "Delat kabelskyddsrör för skydd av redan installerade kabel samt temporär förläggning.", "introDraft": false, "blocks": [{"t": "h3", "x": "Delbara kabelskyddsrör"}, {"t": "p", "x": "Kan även användas som reparationskit för släta eller korrugerade kabelskyddsrör."}, {"t": "p", "x": "Tillverkas i återvunnen PP plast."}, {"t": "h3", "x": "OPI distanshållare"}, {"t": "p", "x": "OPI distanshållare eller klämmor för kabelskyddsrör 50, 110 och 160 mm rör. Används när det skall förläggas flera rör i samma kabelschakt och man efterfrågar en flexibel lösning"}, {"t": "h3", "x": "Släta kabelskyddsrör SRN och SRS", "d": true}, {"t": "p", "x": "Släta kabelskyddsrör med konmuff, märkta Kraftkabel SRN eller SRS, uppfyller Verksnorm 5200. Rören är tillverkade av återvunnet material och levereras i längder om 6 m, i dimensioner från 50 till 200 mm beroende på typ. Det finns även SRS-rör utan muff för tryckning.", "d": true}, {"t": "p", "x": "Korrugerade kabelrör i HDPE med slät insida finns för elkraft (gul) och för svagström och opto (grön). I samma produktgrupp finns inspektions- och kopplingsbrunnar för PUS, jordning och åskledare.", "d": true}], "faq": []}, "fi": {"intro": "Jaettava kaapelinsuojaputki jo asennettujen kaapeleiden suojaamiseen sekä tilapäiseen asentamiseen.", "introDraft": false, "h": "Tietoa kaapelinsuojaputkista", "blocks": [{"t": "h3", "x": "Jaettavat kaapelinsuojaputket"}, {"t": "p", "x": "Voidaan käyttää myös korjaussarjana sileille tai korrugoiduille kaapelinsuojaputkille."}, {"t": "p", "x": "Valmistettu kierrätetystä PP-muovista."}, {"t": "h3", "x": "OPI-välikkeet"}, {"t": "p", "x": "OPI-välikkeet tai pidikkeet 50, 110 ja 160 mm:n kaapelinsuojaputkille. Käytetään, kun samaan kaapelikaivantoon asennetaan useita putkia ja halutaan joustava ratkaisu"}, {"t": "h3", "x": "Sileät kaapelinsuojaputket SRN ja SRS", "d": true}, {"t": "p", "x": "Sileät kaapelinsuojaputket kartiomuhvilla, merkinnällä Kraftkabel SRN tai SRS, täyttävät Verksnorm 5200 -normin vaatimukset. Putket on valmistettu kierrätysmateriaalista, ja ne toimitetaan 6 m:n pituisina, kokoina 50-200 mm tyypistä riippuen. Saatavana on myös muhvittomia SRS-putkia tunkkausta varten.", "d": true}, {"t": "p", "x": "Korrugoituja HDPE-kaapeliputkia, joissa on sileä sisäpinta, on saatavana voimakaapeleille (keltainen) sekä heikkovirralle ja optiikalle (vihreä). Samassa tuoteryhmässä on myös tarkastus- ja kytkentäkaivoja PUS:lle, maadoitukselle ja ukkosenjohdattimille.", "d": true}], "faq": []}}, "el/flerfack": {"status": "befintlig", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/kabelskyddsror/flerfackskanaler", "name": "Flerfackskanaler", "use": "text"}], "words": 64, "faqWords": 0, "check": "Teksti sellaisenaan.", "sv": {"intro": "Systemet används främst som tvärkanalisation under vägar och järnvägar, där påfrestningarna gör det omöjligt att förlägga vanliga rör. Det har sedan 1998 varit föreskrivet av Trafikverket som tvärkanalisation.", "introDraft": false, "blocks": [{"t": "p", "x": "I förfrågningsunderlagen benämns QA-kanalen som flerfackskanal eller flerfackskanaler."}, {"t": "p", "x": "Vid förläggning kan man med fördel sammanfoga tre till fyra kanaler sida vid sida och därefter montera dem i schaktet. På så sätt kan installationstiden avsevärt förkortas."}], "faq": []}, "fi": {"intro": "Järjestelmää käytetään pääasiassa poikittaiskanavointina teiden ja rautateiden alla, missä rasitukset tekevät tavallisten putkien asentamisen mahdottomaksi. Trafikverket on vuodesta 1998 määrännyt sen poikittaiskanavointiratkaisuksi.", "introDraft": false, "h": "Tietoa monikanavaputkista", "blocks": [{"t": "p", "x": "Tarjouspyyntöasiakirjoissa QA-kanavasta käytetään nimitystä monikanavaputki tai monikanavaputket."}, {"t": "p", "x": "Asennettaessa kolme tai neljä kanavaa voidaan edullisesti liittää yhteen rinnakkain ja asentaa sen jälkeen kaivantoon. Näin asennusaikaa voidaan lyhentää huomattavasti."}], "faq": []}}, "bygg": {"status": "utkast", "sources": [], "words": 121, "faqWords": 0, "check": "Luonnos alakategorioiden teksteistä.", "sv": {"intro": "Grundläggning och tillbehör för byggen i mark: betongplintar, stolpfundament och stolpskor, markskruvar, glasfiberstegar och fallskydd för brunnar.", "introDraft": true, "blocks": [{"t": "h3", "x": "Betongplintar", "d": true}, {"t": "p", "x": "Betongplintar med bred fot finns i fyra modeller, från AP med maxbelastning 900 kg till KP+ med maxbelastning 10 000 kg. De används för altaner, friggebodar, carportar, sommarstugor, teknikhus och andra byggnader.", "d": true}, {"t": "h3", "x": "Stolpskor och stolpfundament", "d": true}, {"t": "p", "x": "Stolpskor, balkskor, monteringsplattor och vinkeljärn passar AP-, TP- och KP-plintar. Stolpfundament PP passar vägmärken, laddningsstolpar för elbilar, värmestolpar, lyktstolpar och lättare staket.", "d": true}, {"t": "h3", "x": "Markskruvar", "d": true}, {"t": "p", "x": "Markskruvar i varmförzinkat stål skruvas ner direkt i marken och används som grund för staket, altaner och mindre byggnader, utan gjutning.", "d": true}, {"t": "h3", "x": "Stegar och fallskydd", "d": true}, {"t": "p", "x": "Glasfiberstegar leder inte ström och används ofta av elektriker. Fallskydd i rostfritt stål monteras i brunnar för att förhindra fallolyckor.", "d": true}], "faq": []}, "fi": {"intro": "Perustukset ja tarvikkeet maahan rakentamiseen: betoniplintit, pylväsperustukset ja pylväskengät, maaruuvit, lasikuitutikkaat ja putoamissuojat kaivoihin.", "introDraft": true, "h": "Tietoa rakentamisesta", "blocks": [{"t": "h3", "x": "Betoniplintit", "d": true}, {"t": "p", "x": "Leveäjalkaisia betoniplinttejä on saatavana neljänä mallina, AP:stä, jonka maksimikuormitus on 900 kg, KP+:aan, jonka maksimikuormitus on 10 000 kg. Niitä käytetään terasseihin, pihamajoihin, autokatoksiin, kesämökkeihin, tekniikkarakennuksiin ja muihin rakennuksiin.", "d": true}, {"t": "h3", "x": "Pylväskengät ja pylväsperustukset", "d": true}, {"t": "p", "x": "Pylväskengät, palkkikengät, asennuslevyt ja kulmaraudat sopivat AP-, TP- ja KP-plintteihin. Pylväsperustus PP sopii liikennemerkeille, sähköautojen latauspylväille, lämpötolpille, valaisinpylväille ja kevyemmille aidoille.", "d": true}, {"t": "h3", "x": "Maaruuvit", "d": true}, {"t": "p", "x": "Kuumasinkitystä teräksestä valmistetut maaruuvit ruuvataan suoraan maahan, ja niitä käytetään aitojen, terassien ja pienempien rakennusten perustuksena ilman valua.", "d": true}, {"t": "h3", "x": "Tikkaat ja putoamissuojat", "d": true}, {"t": "p", "x": "Lasikuitutikkaat eivät johda sähköä, ja sähköasentajat käyttävät niitä usein. Ruostumattomasta teräksestä valmistetut putoamissuojat asennetaan kaivoihin putoamisonnettomuuksien estämiseksi.", "d": true}], "faq": []}}, "bygg/plintar": {"status": "kombinerad", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/betongplintar", "name": "Betongplintar", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/betongplintar/betongplint-ap-maxbelastning-900kg", "name": "Betongplint AP (Maxbelastning 900kg)", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/betongplintar/betongplint-tp-barighet-1600kg", "name": "Betongplint TP (Maxbelastning 1600kg)", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/betongplintar/betongplint-kp-barighet-7000kg", "name": "Betongplint KP (Maxbelastning 7000kg)", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/betongplintar/betongplint-kp-maxbelastning-10000kg", "name": "Betongplint KP+ (Maxbelastning 10000kg)", "use": "text"}], "words": 202, "faqWords": 0, "check": "RISTIRIITA: yleisteksti sanoo KP \"upp till 5000 kg\", KP-teksti 7000 kg. Yleisteksti mainitsee 2 mallia, alakategoriat 4 (AP, TP, KP, KP+).", "sv": {"intro": "Marknadens stadigaste betongplintar, med bred fot. Finns i 2 st. olika modeller.", "introDraft": false, "blocks": [{"t": "p", "x": "Modell TP med en bärighet upp till 1600 kg och modell KP för bärighet upp till 5000 kg. Se även betongplint KP+ och betongplint TP 200. Användningsområde: carportar, altaner med tak, sommarstugor större bastu byggnader, byggbaracker, mindre hus, teknikhus, pumphus."}, {"t": "h3", "x": "Betongplint AP"}, {"t": "p", "x": "Betongplint AP är den minsta modellen med en bottenplatta på 330 × 330 mm och maxbelastning 900 kg. Den är smidig och lätt att hantera, passar för lättare konstruktioner som altaner, mindre friggebodar, utedass och bastur."}, {"t": "h3", "x": "Betongplint TP"}, {"t": "p", "x": "Betongplint TP är modellen med en bottenplatta på 450 × 450 mm och maxbelastning 1 600 kg. Den passar för något tyngre konstruktioner altaner, friggebodar och byggnader upp till 40 m2."}, {"t": "h3", "x": "Betongplint KP"}, {"t": "p", "x": "Betongplint KP är den kraftigare modellen med en bottenplatta på 600 × 600 mm och maxbelastning 7000 kg. Den passar för tyngre byggen som carportar, altaner med tak, sommarstugor, små gårdsbyggnader och teknikhus."}, {"t": "h3", "x": "Betongplint KP+"}, {"t": "p", "x": "Betongplint KP +1000 är den kraftigaste modellen med en bottenplatta på 800x800 mm och maxbelastning 10 000 kg. Kan levereras med ingjutna gänghylsor (M20) eller en ingjuten svetsplatta i toppen. Passar till större hus och byggnader, teknikhus, pumpstationer, modulhus och även som fundament till bullerskydd."}], "faq": []}, "fi": {"intro": "Markkinoiden tukevimmat betoniplintit leveällä jalalla. Saatavana 2 eri mallia.", "introDraft": false, "h": "Tietoa betoniplinteistä", "blocks": [{"t": "p", "x": "Malli TP, kantavuus enintään 1600 kg, ja malli KP, kantavuus enintään 5000 kg. Katso myös betoniplintti KP+ ja betoniplintti TP 200. Käyttökohteet: autokatokset, katetut terassit, kesämökit, suuremmat saunarakennukset, työmaaparakit, pienet talot, tekniikkarakennukset, pumppuhuoneet."}, {"t": "h3", "x": "Betoniplintti AP"}, {"t": "p", "x": "Betoniplintti AP on pienin malli, jonka pohjalaatta on 330 × 330 mm ja maksimikuormitus 900 kg. Se on kätevä ja helppo käsitellä, ja se sopii kevyemmille rakenteille, kuten terasseille, pienemmille pihamajoille, ulkohuusseille ja saunoille."}, {"t": "h3", "x": "Betoniplintti TP"}, {"t": "p", "x": "Betoniplintti TP on malli, jonka pohjalaatta on 450 × 450 mm ja maksimikuormitus 1 600 kg. Se sopii hieman raskaammille rakenteille, kuten terasseille, pihamajoille ja enintään 40 m2:n rakennuksille."}, {"t": "h3", "x": "Betoniplintti KP"}, {"t": "p", "x": "Betoniplintti KP on järeämpi malli, jonka pohjalaatta on 600 × 600 mm ja maksimikuormitus 7000 kg. Se sopii raskaampiin rakennuskohteisiin, kuten autokatoksiin, katettuihin terasseihin, kesämökkeihin, pieniin piharakennuksiin ja tekniikkarakennuksiin."}, {"t": "h3", "x": "Betoniplintti KP+"}, {"t": "p", "x": "Betoniplintti KP +1000 on järein malli, jonka pohjalaatta on 800x800 mm ja maksimikuormitus 10 000 kg. Se voidaan toimittaa valetuilla kierreholkeilla (M20) tai yläpäähän valetulla hitsauslevyllä. Sopii suurempiin taloihin ja rakennuksiin, tekniikkarakennuksiin, pumppaamoihin, moduulitaloihin ja myös meluesteiden perustukseksi."}], "faq": []}}, "bygg/stolp": {"status": "kombinerad", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/betongplintar/stolpskor-m20-och-beslag-till-betongplintar", "name": "Stolpskor M20 och byggbeslag", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/betongplintar/stolpfundament-pp", "name": "Stolpfundament PP", "use": "text"}], "words": 71, "faqWords": 0, "check": "Kaksi lyhyttä tekstiä yhdistetty.", "sv": {"intro": "Passar till AP-, TP- och KP- plintar. Beroende på användningsområde kan du välja mellan stolpskor, balkskor, monteringsplattor eller vinkeljärn för att stabilisera strukturen.", "introDraft": false, "blocks": [{"t": "p", "x": "Kombinationen av plintar och tillbehör gör att du enkelt hittar lösningar som passar olika monteringsbehov. Med lyftöglan förflyttar du plintarna enkelt och smidigt."}, {"t": "h3", "x": "Stolpfundament PP"}, {"t": "p", "x": "Ett stabilt fundament för olika stolpar. Passar utmärkt för vägmärken, laddningsstolpar för elbilar, värmestolpar för bilar, lyktstolpar och som fundament för lättare staket."}], "faq": []}, "fi": {"intro": "Sopii AP-, TP- ja KP-plintteihin. Käyttötarkoituksesta riippuen voit valita pylväskengät, palkkikengät, asennuslevyt tai kulmaraudat rakenteen vakauttamiseen.", "introDraft": false, "h": "Tietoa pylväsperustuksista ja pylväskengistä", "blocks": [{"t": "p", "x": "Plinttien ja tarvikkeiden yhdistelmän ansiosta löydät helposti ratkaisut erilaisiin asennustarpeisiin. Nostolenkin avulla siirrät plinttejä helposti ja kätevästi."}, {"t": "h3", "x": "Pylväsperustus PP"}, {"t": "p", "x": "Vakaa perustus erilaisille pylväille. Sopii erinomaisesti liikennemerkeille, sähköautojen latauspylväille, autojen lämpötolpille, valaisinpylväille ja kevyempien aitojen perustukseksi."}], "faq": []}}, "bygg/markskruv": {"status": "utkast", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/markskruvar", "name": "Markskruvar", "use": "ingen text"}], "words": 158, "faqWords": 0, "check": "Luonnos tuotekuvauksista (Arctic, Aurora, Polar). Kantavuusluvut jätetty tuotesivuille.", "sv": {"intro": "Markskruvar i varmförzinkat stål som skruvas ner direkt i marken och fungerar som grund utan gjutning. De används som grundförankring för exempelvis staket, altaner och mindre byggnader.", "introDraft": true, "blocks": [{"t": "p", "x": "Eftersom marken bara påverkas vid infästningspunkten passar markskruvar särskilt bra i marina miljöer, trädgårdar och grönområden där omgivande ytor ska bevaras.", "d": true}, {"t": "h3", "x": "Modeller", "d": true}, {"t": "ul", "items": ["Arctic markskruv med fast platta: längd 800, 1 000 eller 1 250 mm, diameter 76 mm.", "Aurora markskruv V-76, förlängningsbar: längd 800 eller 1 250 mm. Kan kombineras med förlängning (500 eller 1 050 mm) och topp för att öka förankringsdjupet.", "Polar rörskruv G3: längd 800 eller 1 250 mm, för exempelvis belysningsstolpar och skyltar. Stolpröret förs ner i skruven och fixeras med tre M16-bultar."], "d": true}, {"t": "h3", "x": "Tillbehör", "d": true}, {"t": "p", "x": "Justerbara stolpskor för reglar och stolpar (43-53, 62-77 och 84-104 mm), förstoringsplatta 300 × 300 mm för jämnare lastfördelning och L-konsol för infästning.", "d": true}, {"t": "p", "x": "Bärigheten påverkas av markförhållanden och förutsätter korrekt installation. Uppgifter om bärighet finns på respektive produkt.", "d": true}], "faq": []}, "fi": {"intro": "Kuumasinkitystä teräksestä valmistetut maaruuvit ruuvataan suoraan maahan, ja ne toimivat perustuksena ilman valua. Niitä käytetään perustuksen ankkurointiin esimerkiksi aidoille, terasseille ja pienemmille rakennuksille.", "introDraft": true, "h": "Tietoa maaruuveista", "blocks": [{"t": "p", "x": "Koska maaperään vaikutetaan vain kiinnityskohdassa, maaruuvit sopivat erityisen hyvin meriympäristöihin, puutarhoihin ja viheralueille, joissa ympäröivät pinnat on tarkoitus säilyttää.", "d": true}, {"t": "h3", "x": "Mallit", "d": true}, {"t": "ul", "items": ["Arctic-maaruuvi kiinteällä levyllä: pituus 800, 1 000 tai 1 250 mm, halkaisija 76 mm.", "Aurora-maaruuvi V-76, jatkettava: pituus 800 tai 1 250 mm. Voidaan yhdistää jatkokappaleeseen (500 tai 1 050 mm) ja yläosaan ankkurointisyvyyden lisäämiseksi.", "Polar-putkiruuvi G3: pituus 800 tai 1 250 mm, esimerkiksi valaisinpylväille ja kylteille. Pylväsputki viedään ruuvin sisään ja kiinnitetään kolmella M16-pultilla."], "d": true}, {"t": "h3", "x": "Tarvikkeet", "d": true}, {"t": "p", "x": "Säädettävät pylväskengät rimoille ja pylväille (43-53, 62-77 ja 84-104 mm), laajennuslevy 300 × 300 mm tasaisempaa kuormanjakoa varten ja L-kannake kiinnitykseen.", "d": true}, {"t": "p", "x": "Kantavuuteen vaikuttavat maaperän olosuhteet, ja se edellyttää oikeaa asennusta. Tiedot kantavuudesta löytyvät kunkin tuotteen kohdalta.", "d": true}], "faq": []}}, "bygg/stegar": {"status": "befintlig + utkast", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/glasfiberstegar", "name": "Glasfiberstegar", "use": "text"}], "words": 90, "faqWords": 0, "check": "Lyhyt vanha teksti + luonnoslisäys tuotekuvauksesta.", "sv": {"intro": "Glasfiberstegar används vanligtvis av elektriker, eftersom stegarna är lätta att bära runt på och samtidigt inte leder elektricitet/ström.", "introDraft": false, "blocks": [{"t": "p", "x": "Kan levereras med väggfäste"}, {"t": "h3", "x": "Längder och väggfäste", "d": true}, {"t": "p", "x": "Glasfiberstegen finns i längderna 2 000, 2 500, 3 000 och 3 500 mm. Stegen är lätt att bära med sig och leder inte elektricitet, vilket minskar riskerna vid arbete nära strömförande installationer.", "d": true}, {"t": "p", "x": "Som tillval finns väggfästen i syrafast stål: 2 st. till stegarna på 2 000 och 2 500 mm, 3 st. till 3 000 mm och 4 st. till 3 500 mm.", "d": true}], "faq": []}, "fi": {"intro": "Lasikuitutikkaita käyttävät yleensä sähköasentajat, koska tikkaat ovat kevyitä kantaa mukana eivätkä samalla johda sähköä/virtaa.", "introDraft": false, "h": "Tietoa lasikuitutikkaista", "blocks": [{"t": "p", "x": "Voidaan toimittaa seinäkiinnikkeellä"}, {"t": "h3", "x": "Pituudet ja seinäkiinnike", "d": true}, {"t": "p", "x": "Lasikuitutikkaita on saatavana pituuksina 2 000, 2 500, 3 000 ja 3 500 mm. Tikkaat on helppo kantaa mukana, eivätkä ne johda sähköä, mikä vähentää riskejä jännitteisten asennusten lähellä työskenneltäessä.", "d": true}, {"t": "p", "x": "Lisävarusteena on saatavana haponkestävästä teräksestä valmistettuja seinäkiinnikkeitä: 2 kpl 2 000 ja 2 500 mm:n tikkaisiin, 3 kpl 3 000 mm:n tikkaisiin ja 4 kpl 3 500 mm:n tikkaisiin.", "d": true}], "faq": []}}, "bygg/fallskydd": {"status": "utkast", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/fallskydd", "name": "Fallskydd och Trumögon", "use": "ingen text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/fallskydd/fallskydd-fallskydd", "name": "Fallskydd", "use": "ingen text"}], "words": 133, "faqWords": 0, "check": "Luonnos tuotekuvauksista. Viittaus ordningslagen (1993) on SB:n tuotekuvauksista: SB vahvistaa, että sen saa sanoa kategoriatekstissä.", "sv": {"intro": "Fallskydd i rostfritt, syrafast stål (SS 316) som monteras i brunnen för att förhindra fallolyckor. Olyckor i oskyddade brunnar drabbar i många fall barn.", "introDraft": true, "blocks": [{"t": "h3", "x": "Storlekar", "d": true}, {"t": "p", "x": "Fallskydden passar betong- och plastbrunnar med innerdiameter 280-315, 350-410, 470-510, 550-610 och 950-1 100 mm. Det finns även modeller för korrugerade plastbrunnsrör med innerdiameter 315 och 425 mm, och en modell för betong- och plastkonor med innermått 600-655 mm.", "d": true}, {"t": "h3", "x": "Material och funktion", "d": true}, {"t": "p", "x": "Fallskydden tål aggressiva miljöer utan att rosta och uppfyller hälso- och miljökraven i BASTA. De har öppningsmöjlighet för spolning, de större modellerna även för sugning. RSK-nummer finns på respektive produkt.", "d": true}, {"t": "h3", "x": "Krav på skydd i brunnar", "d": true}, {"t": "p", "x": "Enligt ordningslagen från 1993 krävs en säkerhetsanordning på brunnar, med särskilt fokus på områden där barn vistas. Kravet gäller både nya och befintliga brunnar.", "d": true}], "faq": []}, "fi": {"intro": "Ruostumattomasta, haponkestävästä teräksestä (SS 316) valmistettu putoamissuoja, joka asennetaan kaivoon putoamisonnettomuuksien estämiseksi. Suojaamattomien kaivojen onnettomuudet kohdistuvat monissa tapauksissa lapsiin.", "introDraft": true, "h": "Tietoa putoamissuojauksesta", "blocks": [{"t": "h3", "x": "Koot", "d": true}, {"t": "p", "x": "Putoamissuojat sopivat betoni- ja muovikaivoihin, joiden sisähalkaisija on 280-315, 350-410, 470-510, 550-610 ja 950-1 100 mm. Saatavana on myös malleja korrugoiduille muovisille kaivoputkille, joiden sisähalkaisija on 315 ja 425 mm, sekä malli betoni- ja muovikartioille, joiden sisämitta on 600-655 mm.", "d": true}, {"t": "h3", "x": "Materiaali ja toiminta", "d": true}, {"t": "p", "x": "Putoamissuojat kestävät aggressiivisia ympäristöjä ruostumatta ja täyttävät BASTA:n terveys- ja ympäristövaatimukset. Niissä on avausmahdollisuus huuhtelua varten, suuremmissa malleissa myös imua varten. RSK-numero löytyy kunkin tuotteen kohdalta.", "d": true}, {"t": "h3", "x": "Kaivojen suojausvaatimukset", "d": true}, {"t": "p", "x": "Ruotsin järjestyslain (ordningslagen) vuodelta 1993 mukaan kaivoissa on oltava turvalaite, ja erityistä huomiota on kiinnitettävä alueisiin, joilla oleskelee lapsia. Vaatimus koskee sekä uusia että olemassa olevia kaivoja.", "d": true}], "faq": []}}, "trafik": {"status": "utkast", "sources": [], "words": 134, "faqWords": 0, "check": "Luonnos alakategorioiden teksteistä.", "sv": {"intro": "Gjutjärnsbetäckningar, gatugods och produkter för väg och trafikmiljö: betäckningar för betong- och plastbrunnar, kanalgaller, betäckningar för flygplatser och hamnar, trumögon och stolpar för bullerskärmar.", "introDraft": true, "blocks": [{"t": "h3", "x": "Gjutjärnsbetäckningar och gatugods", "d": true}, {"t": "p", "x": "Betäckningar och gatugods i gjutjärn och segjärn för gator, trottoarer och industriområden. Kanalgaller finns i belastningsklass C250, D400 och F900 enligt EN 124, och teleskoprör används för att anpassa betäckningens höjd.", "d": true}, {"t": "p", "x": "Belastningsklassen visar var betäckningen kan användas: C250 för parkering och kantsten, D400 för väg och gata och F900 för hamn och flygplats. Klassen anges på varje produkt.", "d": true}, {"t": "h3", "x": "Flygplatser och hamnar", "d": true}, {"t": "p", "x": "För de tyngsta belastningarna finns betäckningar för flygplatser och hamnar i gjutjärn och komposit.", "d": true}, {"t": "h3", "x": "Trumögon och stolpar för bullerskärmar", "d": true}, {"t": "p", "x": "Trumögon i rostfritt stål monteras i dagvattenledningens in- och utlopp för att förhindra drunkningsolyckor. Stolpar för bullerskärmar tillverkas enligt Trafikverkets regler för användning utmed vägar och järnvägar.", "d": true}], "faq": []}, "fi": {"intro": "Valurautakansistot, katuvalut ja tuotteet tie- ja liikenneympäristöihin: kansistot betoni- ja muovikaivoihin, koururitilät, kansistot lentokentille ja satamiin, rumpusilmät sekä meluesteiden pylväät.", "introDraft": true, "h": "Tietoa liikenteestä", "blocks": [{"t": "h3", "x": "Valurautakansistot ja katuvalut", "d": true}, {"t": "p", "x": "Kansistot ja katuvalut valuraudasta ja pallografiittivaluraudasta kaduille, jalkakäytäville ja teollisuusalueille. Koururitilöitä on saatavana kuormitusluokissa C250, D400 ja F900 EN 124 -standardin mukaisesti, ja teleskooppiputkia käytetään kansiston korkeuden sovittamiseen.", "d": true}, {"t": "p", "x": "Kuormitusluokka kertoo, missä kansistoa voidaan käyttää: C250 pysäköintiin ja reunakiven kohdalle, D400 teille ja kaduille ja F900 satamiin ja lentokentille. Luokka on ilmoitettu jokaisen tuotteen kohdalla.", "d": true}, {"t": "h3", "x": "Lentokentät ja satamat", "d": true}, {"t": "p", "x": "Raskaimpiin kuormituksiin on saatavana lentokenttien ja satamien kansistoja valuraudasta ja komposiitista.", "d": true}, {"t": "h3", "x": "Rumpusilmät ja meluesteiden pylväät", "d": true}, {"t": "p", "x": "Ruostumattomasta teräksestä valmistetut rumpusilmät asennetaan hulevesiputken tulo- ja lähtöpäähän hukkumisonnettomuuksien estämiseksi. Meluesteiden pylväät valmistetaan Trafikverketin määräysten mukaisesti käytettäviksi teiden ja rautateiden varrella.", "d": true}], "faq": []}}, "trafik/gjutjarn": {"status": "kombinerad", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/betackningar", "name": "Gjutjärns betäckningar Gatugods", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/betackningar/betackningar-for-betongbrunnar", "name": "Betäckningar för betongbrunnar", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/betackningar/betackningar-for-plastbrunnar", "name": "Betäckningar för plastbrunnar", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/betackningar/teleskopror-och-manschetter", "name": "Teleskoprör och Manschetter", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/betackningar/kanalgaller", "name": "Kanalgaller", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/betackningar/betackningar-for-ventilbrunnar", "name": "Betäckningar för ventilbrunnar", "use": "ingen text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/betackningar/spygatter-betackningar", "name": "Spygatter", "use": "ingen text"}], "words": 342, "faqWords": 0, "check": "Viisi tekstiä yhdistetty, toistuvat SEO-osiot pois.", "sv": {"intro": "Gjutjärnsbetäckningar för gatugods är en viktig del av stadens infrastruktur, utformade för att säkerställa hållbarhet och pålitlighet i trafikmiljöer. På Svenska Brunnslock erbjuder vi högkvalitativa gjutjärnsbetäckningar som uppfyller de strängaste kraven för säkerhet och hållbarhet.", "introDraft": false, "blocks": [{"t": "h3", "x": "Gjutjärnsbetäckningar för gatugods: hållbara och pålitliga"}, {"t": "p", "x": "Här går vi igenom fördelarna med våra produkter, de olika alternativen och hur de används."}, {"t": "h3", "x": "Fördelar med gjutjärnsbetäckningar"}, {"t": "p", "x": "Gjutjärnsbetäckningar är kända för sin styrka och hållbarhet, vilket gör dem idealiska för användning i områden med tung trafik, såsom gator, trottoarer och industriområden. De är resistenta mot slitage, korrosion och extrema väderförhållanden. Genom att använda gjutjärnsbetäckningar från Svenska Brunnslock, kan du säkerställa långvarig prestanda och minimalt underhåll."}, {"t": "h3", "x": "Våra produkter"}, {"t": "p", "x": "Vi erbjuder ett brett utbud av gjutjärnsbetäckningar i olika storlekar och utföranden för att passa olika behov och tillämpningar. Våra betäckningar är designade för att vara lätta att installera och underhålla, samtidigt som de erbjuder maximalt skydd och stabilitet."}, {"t": "h3", "x": "Användning och installation"}, {"t": "p", "x": "Gjutjärnsbetäckningar är enkla att installera och kräver minimal underhåll. Våra produkter kommer med detaljerade installationsanvisningar för att säkerställa korrekt montering och långvarig prestanda. Genom att följa dessa anvisningar kan du snabbt och enkelt förbättra säkerheten och hållbarheten i din infrastruktur."}, {"t": "h3", "x": "Betäckningar för betongbrunn: starka och pålitliga lösningar"}, {"t": "p", "x": "Betäckningar för betongbrunn är avgörande för att skydda brunnar och säkerställa deras funktionalitet. På Svenska Brunnslock erbjuder vi betäckningar som kombinerar styrka och hållbarhet för att möta alla dina behov."}, {"t": "h3", "x": "Betäckningar för plastbrunn: lätta och hållbara"}, {"t": "p", "x": "Betäckningar för plastbrunn erbjuder en lätt och hållbar lösning för skydd och säkerhet. På Svenska Brunnslock erbjuder vi högkvalitativa betäckningar som är designade för att passa olika typer av plastbrunnar."}, {"t": "h3", "x": "Teleskoprör: flexibla och justerbara lösningar"}, {"t": "p", "x": "Teleskoprör är en mångsidig komponent som används för att anpassa höjden på brunnslock och andra betäckningar. På Svenska Brunnslock erbjuder vi högkvalitativa teleskoprör som ger flexibilitet och enkel justering för dina behov."}, {"t": "h3", "x": "Kanalgaller"}, {"t": "p", "x": "Kanalgaller och ram tillverkas i segjärn och finns i belastningsklass C250, D400 och F900 enligt EN 124."}, {"t": "p", "x": "Gallren används främst som rännstenskanter på vägar och motorvägar samt i gatukorsningar där trafiken går långsamt, till exempel vid trafikplatser, korsningar och bilparkeringar"}], "faq": []}, "fi": {"intro": "Katuvalujen valurautakansistot ovat tärkeä osa kaupungin infrastruktuuria, ja ne on suunniteltu varmistamaan kestävyys ja luotettavuus liikenneympäristöissä. Svenska Brunnslockilla tarjoamme korkealaatuisia valurautakansistoja, jotka täyttävät tiukimmat turvallisuus- ja kestävyysvaatimukset.", "introDraft": false, "h": "Tietoa valurautakansista ja katuvaluista", "blocks": [{"t": "h3", "x": "Katuvalujen valurautakansistot: kestäviä ja luotettavia"}, {"t": "p", "x": "Tässä käymme läpi tuotteidemme edut, eri vaihtoehdot ja niiden käytön."}, {"t": "h3", "x": "Valurautakansistojen edut"}, {"t": "p", "x": "Valurautakansistot tunnetaan lujuudestaan ja kestävyydestään, mikä tekee niistä ihanteellisia käytettäviksi raskaan liikenteen alueilla, kuten kaduilla, jalkakäytävillä ja teollisuusalueilla. Ne kestävät kulutusta, korroosiota ja äärimmäisiä sääolosuhteita. Käyttämällä Svenska Brunnslockin valurautakansistoja voit varmistaa pitkäaikaisen suorituskyvyn ja minimaalisen huollon tarpeen."}, {"t": "h3", "x": "Tuotteemme"}, {"t": "p", "x": "Tarjoamme laajan valikoiman valurautakansistoja eri kokoina ja toteutuksina erilaisiin tarpeisiin ja sovelluksiin. Kansistomme on suunniteltu helposti asennettaviksi ja huollettaviksi, ja samalla ne tarjoavat maksimaalisen suojan ja vakauden."}, {"t": "h3", "x": "Käyttö ja asennus"}, {"t": "p", "x": "Valurautakansistot on helppo asentaa, ja ne vaativat vain vähän huoltoa. Tuotteidemme mukana tulevat yksityiskohtaiset asennusohjeet, jotka varmistavat oikean asennuksen ja pitkäaikaisen suorituskyvyn. Noudattamalla näitä ohjeita voit nopeasti ja helposti parantaa infrastruktuurisi turvallisuutta ja kestävyyttä."}, {"t": "h3", "x": "Kansistot betonikaivoihin: vahvoja ja luotettavia ratkaisuja"}, {"t": "p", "x": "Betonikaivojen kansistot ovat ratkaisevan tärkeitä kaivojen suojaamisessa ja niiden toimivuuden varmistamisessa. Svenska Brunnslockilla tarjoamme kansistoja, joissa yhdistyvät lujuus ja kestävyys ja jotka vastaavat kaikkiin tarpeisiisi."}, {"t": "h3", "x": "Kansistot muovikaivoihin: kevyitä ja kestäviä"}, {"t": "p", "x": "Muovikaivojen kansistot tarjoavat kevyen ja kestävän ratkaisun suojaukseen ja turvallisuuteen. Svenska Brunnslockilla tarjoamme korkealaatuisia kansistoja, jotka on suunniteltu sopimaan erityyppisiin muovikaivoihin."}, {"t": "h3", "x": "Teleskooppiputket: joustavia ja säädettäviä ratkaisuja"}, {"t": "p", "x": "Teleskooppiputki on monipuolinen komponentti, jolla sovitetaan kaivonkansien ja muiden kansistojen korkeutta. Svenska Brunnslockilla tarjoamme korkealaatuisia teleskooppiputkia, jotka tuovat joustavuutta ja helppoa säädettävyyttä tarpeisiisi."}, {"t": "h3", "x": "Koururitilät"}, {"t": "p", "x": "Koururitilät ja kehykset valmistetaan pallografiittivaluraudasta, ja niitä on saatavana kuormitusluokissa C250, D400 ja F900 EN 124 -standardin mukaisesti."}, {"t": "p", "x": "Ritilöitä käytetään pääasiassa katukourujen reunoissa teillä ja moottoriteillä sekä katuliittymissä, joissa liikenne kulkee hitaasti, esimerkiksi eritasoliittymissä, risteyksissä ja pysäköintialueilla"}], "faq": []}}, "trafik/flyg": {"status": "befintlig", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/betackningar/flygplatser-hamnar", "name": "Betäckningar för flygplatser & hamnar", "use": "text"}], "words": 193, "faqWords": 0, "check": "Teksti sellaisenaan.", "sv": {"intro": "Betäckningar för flygplatser och hamnar är utformade för att klara extremt tunga belastningar och hårda miljöförhållanden. På Svenska Brunnslock erbjuder vi specialiserade betäckningar som möter de stränga kraven inom dessa områden.", "introDraft": false, "blocks": [{"t": "h3", "x": "Betäckningar för flygplatser och hamnar: hög belastningskapacitet och säkerhet"}, {"t": "p", "x": "Här diskuterar vi fördelarna med våra produkter, våra alternativ och hur de används."}, {"t": "h3", "x": "Fördelar med betäckningar för flygplatser och hamnar"}, {"t": "p", "x": "Betäckningar för flygplatser och hamnar är konstruerade för att hantera hög trafikintensitet och tunga laster, såsom flygplan och stora fartyg. De erbjuder överlägsen styrka och hållbarhet, vilket säkerställer säkerheten och funktionaliteten i dessa kritiska infrastrukturer. Genom att använda våra betäckningar kan du säkerställa långvarig prestanda och minimera underhållsbehovet."}, {"t": "h3", "x": "Våra produkter"}, {"t": "p", "x": "Vi erbjuder betäckningar för flygplatser och hamnar i olika storlekar och material, inklusive gjutjärn och kompositmaterial. Våra produkter är designade för att vara korrosionsbeständiga och hållbara, vilket garanterar lång livslängd och pålitlig prestanda under de mest krävande förhållanden."}, {"t": "h3", "x": "Användning och installation"}, {"t": "p", "x": "Betäckningar för flygplatser och hamnar är enkla att installera och använda. Våra produkter levereras med detaljerade installationsanvisningar för att säkerställa korrekt montering och optimal funktion. Genom att följa dessa anvisningar kan du snabbt och enkelt förbättra säkerheten och hållbarheten i dina infrastrukturer."}], "faq": []}, "fi": {"intro": "Lentokenttien ja satamien kansistot on suunniteltu kestämään äärimmäisen raskaita kuormituksia ja ankaria ympäristöolosuhteita. Svenska Brunnslockilla tarjoamme erikoiskansistoja, jotka täyttävät näiden alueiden tiukat vaatimukset.", "introDraft": false, "h": "Tietoa lentokenttien ja satamien kansista", "blocks": [{"t": "h3", "x": "Lentokenttien ja satamien kansistot: suuri kuormituskapasiteetti ja turvallisuus"}, {"t": "p", "x": "Tässä käsittelemme tuotteidemme etuja, vaihtoehtojamme ja niiden käyttöä."}, {"t": "h3", "x": "Lentokenttien ja satamien kansistojen edut"}, {"t": "p", "x": "Lentokenttien ja satamien kansistot on rakennettu kestämään suurta liikennemäärää ja raskaita kuormia, kuten lentokoneita ja suuria aluksia. Ne tarjoavat ylivertaista lujuutta ja kestävyyttä, mikä varmistaa näiden kriittisten infrastruktuurien turvallisuuden ja toimivuuden. Käyttämällä kansistojamme voit varmistaa pitkäaikaisen suorituskyvyn ja minimoida huollon tarpeen."}, {"t": "h3", "x": "Tuotteemme"}, {"t": "p", "x": "Tarjoamme lentokenttien ja satamien kansistoja eri kokoina ja materiaaleina, mukaan lukien valurauta ja komposiittimateriaalit. Tuotteemme on suunniteltu korroosionkestäviksi ja kestäviksi, mikä takaa pitkän käyttöiän ja luotettavan suorituskyvyn vaativimmissakin olosuhteissa."}, {"t": "h3", "x": "Käyttö ja asennus"}, {"t": "p", "x": "Lentokenttien ja satamien kansistot on helppo asentaa ja käyttää. Tuotteidemme mukana toimitetaan yksityiskohtaiset asennusohjeet, jotka varmistavat oikean asennuksen ja optimaalisen toiminnan. Noudattamalla näitä ohjeita voit nopeasti ja helposti parantaa infrastruktuuriesi turvallisuutta ja kestävyyttä."}], "faq": []}}, "trafik/trumogon": {"status": "utkast", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/fallskydd/trumogon", "name": "Trumögon", "use": "ingen text"}], "words": 114, "faqWords": 0, "check": "Luonnos tuotekuvauksista (SS 316, BASTA, Trafikverkets krav).", "sv": {"intro": "Trumögon är galler som monteras i dagvattenledningens in- och utlopp, exempelvis i ett dike eller en trumma. De är framtagna för att förhindra drunkningsolyckor i dagvattenledningar och trummor, som i de flesta fall drabbar barn.", "introDraft": true, "blocks": [{"t": "h3", "x": "Storlekar", "d": true}, {"t": "p", "x": "Trumögon finns för rör och trummor med innerdiameter 190-250, 290-310, 390-430, 470-510, 550-610, 750-900 och 950-1 100 mm. Mät rörets eller trummans innerdiameter och välj den storlek som täcker måttet.", "d": true}, {"t": "h3", "x": "Material", "d": true}, {"t": "p", "x": "Trumögonen tillverkas enligt Trafikverkets krav i rostfritt, syrafast stål SS 316, vilket ger hög beständighet mot korrosion. Produkterna uppfyller hälso- och miljökraven i BASTA.", "d": true}, {"t": "p", "x": "Behöver du skydd i en brunn i stället för i en ledning? Se fallskydd under Bygg.", "d": true}], "faq": []}, "fi": {"intro": "Rumpusilmät ovat ritilöitä, jotka asennetaan hulevesiputken tulo- ja lähtöpäähän, esimerkiksi ojaan tai rumpuun. Ne on kehitetty estämään hulevesiputkissa ja rummuissa tapahtuvia hukkumisonnettomuuksia, jotka useimmissa tapauksissa kohdistuvat lapsiin.", "introDraft": true, "h": "Tietoa rumpusilmistä", "blocks": [{"t": "h3", "x": "Koot", "d": true}, {"t": "p", "x": "Rumpusilmiä on saatavana putkiin ja rumpuihin, joiden sisähalkaisija on 190-250, 290-310, 390-430, 470-510, 550-610, 750-900 ja 950-1 100 mm. Mittaa putken tai rummun sisähalkaisija ja valitse koko, joka kattaa mitan.", "d": true}, {"t": "h3", "x": "Materiaali", "d": true}, {"t": "p", "x": "Rumpusilmät valmistetaan Trafikverketin vaatimusten mukaisesti ruostumattomasta, haponkestävästä teräksestä SS 316, mikä antaa hyvän korroosionkestävyyden. Tuotteet täyttävät BASTA:n terveys- ja ympäristövaatimukset.", "d": true}, {"t": "p", "x": "Tarvitsetko suojan kaivoon putken sijaan? Katso putoamissuojat kohdasta Rakentaminen.", "d": true}], "faq": []}}, "trafik/stolpar": {"status": "utkast", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/stolpar-for-bullerskarmar", "name": "Stolpar för bullerskärmar", "use": "ingen text"}], "words": 84, "faqWords": 0, "check": "Luonnos yhden tuotteen kuvauksesta.", "sv": {"intro": "Stolpar för bullerplank och bullerskärmar, främst för användning utmed vägar och järnvägar. Stolparna tillverkas i enlighet med Trafikverkets regler.", "introDraft": true, "blocks": [{"t": "h3", "x": "Montering", "d": true}, {"t": "p", "x": "Stolparna passar de flesta fundament och kan även monteras direkt i fast underlag, exempelvis betong. Betongplint KP+ under Bygg kan användas som fundament till bullerskydd.", "d": true}, {"t": "h3", "x": "Material och utförande", "d": true}, {"t": "ul", "items": ["Stolpe: HEA 160 eller UNP 160, S235JR", "Fästöra: S235JR", "Fotplåt: S355N Z3", "Utförandeklass EXC3, svetsning enligt SS-EN 1090-2, 7.4.2"], "d": true}, {"t": "p", "x": "Stolparna kan även tillverkas i andra utföranden och längder. Pris lämnas på offert.", "d": true}], "faq": []}, "fi": {"intro": "Pylväät meluaidoille ja meluesteille, pääasiassa käytettäviksi teiden ja rautateiden varrella. Pylväät valmistetaan Trafikverketin määräysten mukaisesti.", "introDraft": true, "h": "Tietoa meluesteiden pylväistä", "blocks": [{"t": "h3", "x": "Asennus", "d": true}, {"t": "p", "x": "Pylväät sopivat useimpiin perustuksiin, ja ne voidaan asentaa myös suoraan kiinteälle alustalle, esimerkiksi betoniin. Betoniplinttiä KP+ (kohdassa Rakentaminen) voidaan käyttää meluesteen perustuksena.", "d": true}, {"t": "h3", "x": "Materiaali ja toteutus", "d": true}, {"t": "ul", "items": ["Pylväs: HEA 160 tai UNP 160, S235JR", "Kiinnityskorvake: S235JR", "Jalkalevy: S355N Z3", "Toteutusluokka EXC3, hitsaus SS-EN 1090-2:n kohdan 7.4.2 mukaisesti"], "d": true}, {"t": "p", "x": "Pylväitä voidaan valmistaa myös muina toteutuksina ja pituuksina. Hinta annetaan tarjouksella.", "d": true}], "faq": []}}, "jvg": {"status": "befintlig", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/material-kabelbrunnar", "name": "Material till kabelbrunnar för järnväg och ställverk", "use": "text"}], "words": 402, "faqWords": 0, "check": "Teksti sellaisenaan (pääkategoria). Mainitsee KTL-fundamentit, jotka ovat nyt alakategoriassa.", "sv": {"intro": "Svenska Brunnslock levererar material och tillbehör till kabelbrunnar för järnväg, ställverk, tunnelbana och kanalisation. Sortimentet är anpassat för entreprenörer och anläggningsbolag som arbetar under Trafikverkets krav och behöver produkter med dokumenterad bärighet och lång livslängd.", "introDraft": false, "blocks": [{"t": "p", "x": "Här hittar du allt tillbehörsmaterial på ett ställe, från betongfundament och stolpfundament till skavskydd, pendelskena och märkskylt för kabelbrunn."}, {"t": "h3", "x": "Betongfundament och KTL-fundament för järnvägsanläggning"}, {"t": "p", "x": "Betongfundament och KTL-fundament används som fäste för kontaktledningsstolpar, sugtransformatorer och bryggstolpar längs järnvägsspår. Fundamenten är tillverkade i armerad betong och dimensionerade för att klara de belastningar och vibrationer som uppstår i järnvägsmiljö. Vi erbjuder stolpfundament i flera utföranden, anpassade för olika markförhållanden och stolpdiametrar. Kontaktledningsfundament och sugtransformatorfundament levereras med dokumenterade bärighetsdata och är direktanpassade för KTL-installationer (kontaktledningsanläggningar)."}, {"t": "h3", "x": "Trälock för tunnelbana och kanalisation"}, {"t": "p", "x": "Trälock för brunnar används i tunnelbane- och kanalisationsmiljöer där kabelbrunnens lock ska integreras med omgivande markbeläggning. Locken är robusta och anpassade för de specifika öppningsmått som förekommer i tunnelbane- och spårtrafikprojekt. Används av entreprenörer som arbetar mot SL, Trafikverket och kommunala infrastrukturprojekt."}, {"t": "h3", "x": "Pendelskena för kabelupphängning"}, {"t": "p", "x": "Pendelskena används för att hänga upp och ordna kablar inuti kabelbrunnar och kabelkanaler längs järnväg och i ställverk. Skenan monteras på brunnens innervägg och håller kablar på rätt höjd och i rätt läge, vilket underlättar underhåll och inspektion. Levereras i standardlängder och kan kombineras med övriga fästdetaljer i sortimentet."}, {"t": "h3", "x": "Skavskydd och gummiduk"}, {"t": "p", "x": "Skavskydd och gummiduk monteras i kabelbrunnens genomföringar och öppningar för att skydda kablar mot mekanisk åverkan. Produkterna reducerar risken för isolationsskador och förläng kabelns livslängd i anläggningar med höga krav på driftsäkerhet, till exempel järnväg och kraftdistribution."}, {"t": "h3", "x": "Aluminiumlock, durkplåtslock och övriga brunnslock"}, {"t": "p", "x": "För kabelbrunnar som kräver ett hållbart och lätt lock erbjuder vi brunnslock i aluminium och durkplåt. Aluminiumlock är korrosionsbeständiga och lämpliga för utemiljöer med krav på låg vikt kombinerat med tillräcklig bärighet. Aluminiumlock används i regel till kabelbrunnar med en innerdiameter om 1200 mm och 1500 mm. Durkplåtslock används till kabelbrunnar med en innerdiameter från 600 mm och upp till 1200 mm."}, {"t": "h3", "x": "Märkskylt, plattform för kabelskåp och övriga tillbehör"}, {"t": "p", "x": "Märkskylt för kabelbrunn används för att identifiera brunnar i fältarbete och underlättar dokumentation och underhållsplanering. Plattform för kabelskåp ger ett stabilt och justerat underlag för kabelskåp i mark- och järnvägsanläggningar. Vi erbjuder också grod- och kräldjursevakueringsanordningar som uppfyller miljökrav vid banarbete nära vattendrag och naturmiljöer."}, {"t": "p", "x": "Har du frågor om vilket material som passar ditt projekt? Kontakta oss så hjälper vi dig att välja rätt produkt för din kabelbrunn och anläggningstyp."}], "faq": []}, "fi": {"intro": "Svenska Brunnslock toimittaa materiaaleja ja tarvikkeita kaapelikaivoihin rautateille, kytkinlaitoksille, metroon ja kaapelikanavointiin. Valikoima on suunniteltu urakoitsijoille ja infrarakennusyhtiöille, jotka työskentelevät Trafikverketin vaatimusten mukaisesti ja tarvitsevat tuotteita, joiden kantavuus on dokumentoitu ja käyttöikä pitkä.", "introDraft": false, "h": "Tietoa rautatiestä", "blocks": [{"t": "p", "x": "Täältä löydät kaikki tarvikkeet yhdestä paikasta, betoniperustuksista ja pylväsperustuksista hankaussuojiin, kaapelikiskoihin ja kaapelikaivon merkintäkilpiin."}, {"t": "h3", "x": "Betoniperustukset ja KTL-perustukset rautatielaitteistoihin"}, {"t": "p", "x": "Betoniperustuksia ja KTL-perustuksia käytetään ajojohdinpylväiden, imumuuntajien ja porttipylväiden kiinnitykseen rautatieraiteiden varrella. Perustukset valmistetaan raudoitetusta betonista, ja ne on mitoitettu kestämään rautatieympäristössä syntyvät kuormitukset ja tärinät. Tarjoamme pylväsperustuksia useina eri malleina, jotka on sovitettu erilaisiin maaperäolosuhteisiin ja pylväiden halkaisijoihin. Ajojohdinperustukset ja imumuuntajaperustukset toimitetaan dokumentoiduin kantavuustiedoin, ja ne on sovitettu suoraan KTL-asennuksiin (ajojohdinlaitteistot)."}, {"t": "h3", "x": "Puukannet metroon ja kaapelikanavointiin"}, {"t": "p", "x": "Kaivojen puukansia käytetään metro- ja kaapelikanavointiympäristöissä, joissa kaapelikaivon kansi on sovitettava ympäröivään pinnoitteeseen. Kannet ovat tukevia ja sovitettu metro- ja raideliikennehankkeissa esiintyviin erityisiin aukkomittoihin. Niitä käyttävät urakoitsijat, jotka tekevät töitä SL:lle, Trafikverketille ja kunnallisiin infrastruktuurihankkeisiin."}, {"t": "h3", "x": "Kaapelikisko kaapelien ripustukseen"}, {"t": "p", "x": "Kaapelikiskoa käytetään kaapelien ripustamiseen ja järjestämiseen kaapelikaivoissa ja kaapelikanavissa rautateiden varrella ja kytkinlaitoksissa. Kisko asennetaan kaivon sisäseinään, ja se pitää kaapelit oikealla korkeudella ja oikeassa asennossa, mikä helpottaa huoltoa ja tarkastuksia. Toimitetaan vakiopituuksina, ja sitä voi yhdistää valikoiman muihin kiinnitysosiin."}, {"t": "h3", "x": "Hankaussuoja ja kumimatto"}, {"t": "p", "x": "Hankaussuoja ja kumimatto asennetaan kaapelikaivon läpivienteihin ja aukkoihin suojaamaan kaapeleita mekaanisilta vaurioilta. Tuotteet vähentävät eristysvaurioiden riskiä ja pidentävät kaapelin käyttöikää laitoksissa, joissa käyttövarmuudelle asetetaan korkeat vaatimukset, esimerkiksi rautateillä ja sähkönjakelussa."}, {"t": "h3", "x": "Alumiinikannet, kyynellevykannet ja muut kaivonkannet"}, {"t": "p", "x": "Kaapelikaivoihin, jotka vaativat kestävän ja kevyen kannen, tarjoamme kaivonkansia alumiinista ja kyynellevystä. Alumiinikannet kestävät korroosiota ja sopivat ulkoympäristöihin, joissa vaaditaan pientä painoa yhdistettynä riittävään kantavuuteen. Alumiinikansia käytetään yleensä kaapelikaivoissa, joiden sisähalkaisija on 1200 mm tai 1500 mm. Kyynellevykansia käytetään kaapelikaivoissa, joiden sisähalkaisija on 600 mm:stä aina 1200 mm:iin."}, {"t": "h3", "x": "Merkintäkilpi, kaapelikaappitaso ja muut tarvikkeet"}, {"t": "p", "x": "Kaapelikaivon merkintäkilpeä käytetään kaivojen tunnistamiseen kenttätyössä, ja se helpottaa dokumentointia ja huollon suunnittelua. Kaapelikaappitaso antaa kaapelikaapeille vakaan ja oikeaan tasoon säädetyn alustan maa- ja rautatielaitoksissa. Tarjoamme myös sammakoiden ja matelijoiden poistumisratkaisuja, jotka täyttävät ympäristövaatimukset ratatöissä vesistöjen ja luontoympäristöjen läheisyydessä."}, {"t": "p", "x": "Onko sinulla kysyttävää siitä, mikä materiaali sopii hankkeeseesi? Ota meihin yhteyttä, niin autamme sinua valitsemaan oikean tuotteen kaapelikaivoosi ja laitostyyppiisi."}], "faq": []}}, "jvg/lock": {"status": "kombinerad", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/material-kabelbrunnar/brunnslock-i-durkplat", "name": "Brunnslock i Durkplåt", "use": "text+faq"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/material-kabelbrunnar/aluminiumlock-forstarkt", "name": "Brunnslock i Aluminium", "use": "text+faq"}], "words": 305, "faqWords": 178, "check": "Kaksi tekstiä ja kaksi FAQ:ta yhdistetty.", "sv": {"intro": "Brunnslock i durkplåt är en pålitlig och robust lösning för kabelbrunnar och andra liknande tillämpningar. På Svenska Brunnslock erbjuder vi ett brett sortiment av brunnslock tillverkade av durkplåt, kända för sin hållbarhet och styrka.", "introDraft": false, "blocks": [{"t": "h3", "x": "Brunnslock i durkplåt: robust och hållbart"}, {"t": "p", "x": "Här diskuterar vi varför du bör välja brunnslock i durkplåt, vilka produkter vi erbjuder och hur de används."}, {"t": "h3", "x": "Varför välja brunnslock i durkplåt?"}, {"t": "p", "x": "Brunnslock i durkplåt är idealiska för områden med hög belastning och trafik, såsom industriområden, parkeringsplatser och trottoarer. Durkplåtens räfflade yta ger utmärkt halkskydd, vilket gör den säker att använda i både våta och torra förhållanden. Dessutom är durkplåt extremt hållbart och kan motstå tung belastning och slitage över tid."}, {"t": "h3", "x": "Våra produkter"}, {"t": "p", "x": "Vi erbjuder brunnslock i durkplåt i olika storlekar och utföranden för att passa olika behov och tillämpningar. Våra brunnslock är tillverkade av högkvalitativt stål, vilket garanterar lång livslängd och motståndskraft mot korrosion. Oavsett om du behöver ett litet brunnslock för en gångväg eller ett stort lock för en industribrunn, har vi rätt produkt för dig."}, {"t": "h3", "x": "Användning och installation"}, {"t": "p", "x": "Brunnslock i durkplåt är enkla att installera och använda. De kan monteras på befintliga brunnar med minimal ansträngning och kräver lite underhåll. Våra produkter levereras med tydliga installationsanvisningar för att säkerställa korrekt montering och långvarig prestanda."}, {"t": "h3", "x": "Brunnslock i aluminium: lättvikt och hållbarhet"}, {"t": "p", "x": "Brunnslock i aluminium är en utmärkt lösning för applikationer där låg vikt och hög hållbarhet är avgörande. På Svenska Brunnslock erbjuder vi förstärkta brunnslock i aluminium som kombinerar dessa egenskaper med enkel hantering."}, {"t": "h4", "x": "Fördelar med brunnslock i aluminium"}, {"t": "p", "x": "Aluminium är känt för sin låga vikt och höga hållbarhet, vilket gör det till ett idealiskt material för brunnslock som ofta behöver lyftas och hanteras. Aluminiumets korrosionsbeständighet gör det också lämpligt för användning i fuktiga eller kemiskt aggressiva miljöer. Brunnslock i aluminium är dessutom lättare att installera och underhålla jämfört med tyngre alternativ."}], "faq": [{"q": "Varför välja brunnslock i durkplåt?", "a": ["Brunnslock i durkplåt är mycket hållbara, har räfflad yta som halkskydd och klarar hög belastning, vilket gör dem idealiska för kabelbrunnar utmed järnvägar, industriområden och parkeringsplatser."]}, {"q": "Vilka storlekar finns för brunnslock i durkplåt?", "a": ["Vi erbjuder runda lock från dimension 600 mm upp till 2000 mm i diameter, för inspektionsbrunnar och kabelbrunnar."]}, {"q": "Är brunnslock i durkplåt korrosionsbeständiga?", "a": ["Ja, våra durkplåtslock är tillverkade av varmförzinkat stål som motstår korrosion och har lång livslängd."]}, {"q": "Hur installeras ett brunnslock i durkplåt?", "a": ["Installation är enkel, och brunnslocket kan monteras på befintliga brunnar med minimalt underhåll."]}, {"q": "Varför välja ett brunnslock i aluminium?", "a": ["Aluminium är lätt, hållbart och korrosionsbeständigt, vilket gör det idealiskt för områden där locket ofta måste hanteras."]}, {"q": "Vilka storlekar finns för förstärkta aluminiumlock?", "a": ["Våra förstärkta aluminiumlock finns i olika storlekar från 600 mm upp till dimension 2000 mm i diameter för att passa olika kabel- och inspektionsbrunnar."]}, {"q": "Är aluminiumlocken väderbeständiga?", "a": ["Ja, de är konstruerade för att tåla salt och aggressiva miljöer."]}, {"q": "Hur installeras ett förstärkt aluminiumlock?", "a": ["Installationen är enkel och kräver minimal underhåll; detaljerade anvisningar medföljer produkten."]}]}, "fi": {"intro": "Kyynellevystä valmistettu kaivonkansi on luotettava ja tukeva ratkaisu kaapelikaivoihin ja muihin vastaaviin käyttökohteisiin. Svenska Brunnslockilla tarjoamme laajan valikoiman kyynellevystä valmistettuja kaivonkansia, jotka tunnetaan kestävyydestään ja lujuudestaan.", "introDraft": false, "h": "Tietoa alumiini- ja ruutulevykansista", "blocks": [{"t": "h3", "x": "Kyynellevykansi: tukeva ja kestävä"}, {"t": "p", "x": "Tässä kerromme, miksi kannattaa valita kyynellevystä valmistettu kaivonkansi, mitä tuotteita tarjoamme ja miten niitä käytetään."}, {"t": "h3", "x": "Miksi valita kyynellevykansi?"}, {"t": "p", "x": "Kyynellevykannet sopivat erinomaisesti alueille, joilla on suuri kuormitus ja paljon liikennettä, kuten teollisuusalueille, pysäköintialueille ja jalkakäytäville. Kyynellevyn kuvioitu pinta antaa erinomaisen liukastumissuojan, minkä ansiosta sitä on turvallista käyttää sekä märissä että kuivissa olosuhteissa. Lisäksi kyynellevy on erittäin kestävää ja kestää raskasta kuormitusta ja kulutusta ajan mittaan."}, {"t": "h3", "x": "Tuotteemme"}, {"t": "p", "x": "Tarjoamme kyynellevykansia eri kokoina ja malleina erilaisiin tarpeisiin ja käyttökohteisiin. Kaivonkantemme on valmistettu laadukkaasta teräksestä, mikä takaa pitkän käyttöiän ja korroosionkestävyyden. Tarvitsitpa pienen kaivonkannen kävelytielle tai suuren kannen teollisuuskaivoon, meiltä löytyy sinulle oikea tuote."}, {"t": "h3", "x": "Käyttö ja asennus"}, {"t": "p", "x": "Kyynellevykannet on helppo asentaa ja käyttää. Ne voidaan asentaa olemassa oleviin kaivoihin vähäisellä vaivalla, ja ne vaativat vain vähän huoltoa. Tuotteidemme mukana toimitetaan selkeät asennusohjeet, jotka varmistavat oikean asennuksen ja pitkäaikaisen toimivuuden."}, {"t": "h3", "x": "Alumiininen kaivonkansi: keveys ja kestävyys"}, {"t": "p", "x": "Alumiininen kaivonkansi on erinomainen ratkaisu käyttökohteisiin, joissa pieni paino ja hyvä kestävyys ovat ratkaisevia. Svenska Brunnslockilla tarjoamme vahvistettuja alumiinisia kaivonkansia, joissa nämä ominaisuudet yhdistyvät helppoon käsittelyyn."}, {"t": "h4", "x": "Alumiinisen kaivonkannen edut"}, {"t": "p", "x": "Alumiini tunnetaan keveydestään ja hyvästä kestävyydestään, mikä tekee siitä ihanteellisen materiaalin kaivonkansiin, joita täytyy usein nostaa ja käsitellä. Alumiinin korroosionkestävyys tekee siitä myös sopivan käytettäväksi kosteissa tai kemiallisesti aggressiivisissa ympäristöissä. Alumiiniset kaivonkannet on lisäksi helpompi asentaa ja huoltaa kuin raskaammat vaihtoehdot."}], "faq": [{"q": "Miksi valita kyynellevykansi?", "a": ["Kyynellevykannet ovat erittäin kestäviä, niiden kuvioitu pinta toimii liukastumissuojana ja ne kestävät suuren kuormituksen, minkä vuoksi ne sopivat erinomaisesti kaapelikaivoihin rautateiden varrella, teollisuusalueille ja pysäköintialueille."]}, {"q": "Missä koissa kyynellevykansia on saatavilla?", "a": ["Tarjoamme pyöreitä kansia halkaisijaltaan 600 mm:stä aina 2000 mm:iin tarkastuskaivoihin ja kaapelikaivoihin."]}, {"q": "Kestävätkö kyynellevykannet korroosiota?", "a": ["Kyllä, kyynellevykantemme on valmistettu kuumasinkitystä teräksestä, joka kestää korroosiota ja jolla on pitkä käyttöikä."]}, {"q": "Miten kyynellevykansi asennetaan?", "a": ["Asennus on helppoa, ja kaivonkansi voidaan asentaa olemassa oleviin kaivoihin vähäisellä huollolla."]}, {"q": "Miksi valita alumiininen kaivonkansi?", "a": ["Alumiini on kevyttä, kestävää ja korroosionkestävää, mikä tekee siitä ihanteellisen alueille, joilla kantta täytyy usein käsitellä."]}, {"q": "Missä koissa vahvistettuja alumiinikansia on saatavilla?", "a": ["Vahvistettuja alumiinikansiamme on saatavilla eri kokoina halkaisijaltaan 600 mm:stä aina 2000 mm:iin, jotta ne sopivat erilaisiin kaapeli- ja tarkastuskaivoihin."]}, {"q": "Kestävätkö alumiinikannet säätä?", "a": ["Kyllä, ne on suunniteltu kestämään suolaa ja aggressiivisia ympäristöjä."]}, {"q": "Miten vahvistettu alumiinikansi asennetaan?", "a": ["Asennus on helppoa ja vaatii vain vähän huoltoa; yksityiskohtaiset ohjeet toimitetaan tuotteen mukana."]}]}}, "jvg/fundament": {"status": "kombinerad + utkast", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/fundament-for-60mm-stolpe-hojd-700", "name": "Fundament för 60mm rör, höjd 700", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/material-kabelbrunnar/betong-fundament", "name": "Betong fundament", "use": "faq"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/material-kabelbrunnar/stolpror-60mm-galvaniserad-l3000-mm", "name": "Stolprör 60mm Galvaniserad L:3000 mm", "use": "ingen text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/material-kabelbrunnar/betongfundament-med-stolpror-60-mm", "name": "Betongfundament med stolprör 60 mm", "use": "ingen text"}], "words": 157, "faqWords": 84, "check": "Vanha teksti + luonnoslisäys perustustyypeistä tuotekuvauksista.", "sv": {"intro": "Betongfundament för 60 mm stolpe. Ingjuten armerad mantelhylsa för starkast möjliga montage av stolpe ingår.", "introDraft": false, "blocks": [{"t": "p", "x": "Åttakantig form ger maximal markstabilitet. Betongfundament för nedgrävning. Enkelt och billigt montage. Man gräver en grop och ställer fundamentet i botten på hålet. Sen fyller man hålet runt fundamentet med fyllnadsmassa så som grus, sand eller dylikt. Detta betongfundament passar våra Ø 60 mm galvade stolpar. Används för installation av papperskorgar, trafikspeglar, parkbänkar mm."}, {"t": "h3", "x": "Fundament för järnväg och signal", "d": true}, {"t": "p", "x": "Här finns även fundament enligt Trafikverkets ritningar: kontaktledningsfundament med eller utan fot, sugtransformatorfundament, stagankare för kontaktledningar, plint för fällbomsdriv och kioskfundament. Fundament typ A och typ B C ingår i ett modulsystem och har samma bygghöjd som kanalisationen, vilket förenklar markarbetet.", "d": true}, {"t": "h3", "x": "Lätta fundament i återvunnen plast", "d": true}, {"t": "p", "x": "Plastgjutna fundament för 60 mm-stolpe och för belysningsstolpar Ø108 mm (höjd 900 mm) är lättare att transportera och hantera än betongfundament. Stolprör 60 × 3,2 mm i galvaniserat stål, längd 3 000 mm, finns som tillbehör.", "d": true}], "faq": [{"q": "Vilka användningsområden har betongfundament?", "a": ["Betongfundament används för att stabilisera och stödja olika strukturer, som kabelskåp, kontaktledningar och andra byggkonstruktioner inom infrastruktur och järnvägar."]}, {"q": "Vilka typer av betongfundament erbjuder ni?", "a": ["Vi erbjuder flera typer av betongfundament, inklusive fundament för kontaktledningar, kioskfundament, plintar för fällbomsdriv och stagankare."]}, {"q": "Är betongfundament väderbeständiga?", "a": ["Ja, våra betongfundament är designade för att klara tuffa väderförhållanden och ge långvarig stabilitet."]}, {"q": "Är det svårt att installera ett betongfundament?", "a": ["Installationen kan utföras av fackmän och kräver rätt verktyg och säkerhetsföreskrifter, särskilt för större installationer."]}]}, "fi": {"intro": "Betoniperustus 60 mm:n pylväälle. Mukana valettu raudoitettu vaippaholkki pylvään mahdollisimman lujaa asennusta varten.", "introDraft": false, "h": "Tietoa betoniperustuksista ja pylväsputkista", "blocks": [{"t": "p", "x": "Kahdeksankulmainen muoto antaa maksimaalisen vakauden maassa. Betoniperustus maahan kaivettavaksi. Helppo ja edullinen asennus. Kaivetaan kuoppa ja asetetaan perustus kuopan pohjalle. Sen jälkeen perustuksen ympärillä oleva kuoppa täytetään täyttömaalla, kuten soralla, hiekalla tai vastaavalla. Tämä betoniperustus sopii Ø 60 mm:n sinkittyihin pylväisiimme. Käytetään roska-astioiden, liikennepeilien, puistonpenkkien ym. asennukseen."}, {"t": "h3", "x": "Perustukset rautateille ja opastimille", "d": true}, {"t": "p", "x": "Täältä löytyvät myös Trafikverketin piirustusten mukaiset perustukset: ajojohdinpylväsperustukset jalalla tai ilman, imumuuntajaperustukset, harusankkurit ajojohtimille, sokkeli puomikoneistolle ja kioskiperustukset. Perustukset tyyppi A ja tyyppi B C kuuluvat moduulijärjestelmään, ja niillä on sama rakennuskorkeus kuin kaapelikanavoinnilla, mikä helpottaa maanrakennustöitä.", "d": true}, {"t": "h3", "x": "Kevyet perustukset kierrätysmuovista", "d": true}, {"t": "p", "x": "Muovivaletut perustukset 60 mm:n pylväälle ja valaisinpylväille Ø108 mm (korkeus 900 mm) ovat kevyempiä kuljettaa ja käsitellä kuin betoniperustukset. Lisävarusteena on saatavilla pylväsputki 60 × 3,2 mm sinkitystä teräksestä, pituus 3 000 mm.", "d": true}], "faq": [{"q": "Mihin betoniperustuksia käytetään?", "a": ["Betoniperustuksia käytetään erilaisten rakenteiden, kuten kaapelikaappien, ajojohtimien ja muiden rakennelmien, vakauttamiseen ja tukemiseen infrastruktuurissa ja rautateillä."]}, {"q": "Millaisia betoniperustuksia tarjoatte?", "a": ["Tarjoamme useita betoniperustustyyppejä, muun muassa ajojohdinperustuksia, kioskiperustuksia, puomikoneistojen sokkeleita ja harusankkureita."]}, {"q": "Kestävätkö betoniperustukset säätä?", "a": ["Kyllä, betoniperustuksemme on suunniteltu kestämään ankaria sääolosuhteita ja antamaan pitkäaikaisen vakauden."]}, {"q": "Onko betoniperustuksen asentaminen vaikeaa?", "a": ["Asennuksen voivat tehdä ammattilaiset, ja se edellyttää oikeita työkaluja ja turvallisuusmääräysten noudattamista, etenkin suuremmissa asennuksissa."]}]}}, "jvg/planering": {"status": "utkast", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/material-kabelbrunnar/planeringslada-for-makadam-jarnvag", "name": "Planeringslåda för makadam järnväg", "use": "ingen text"}], "words": 104, "faqWords": 0, "check": "Luonnos tuotekuvauksista.", "sv": {"intro": "Planeringslåda för makadam och grus, utvecklad för planeringsarbeten vid järnväg och infrastruktur, exempelvis inför läggning av kabelkanal.", "introDraft": true, "blocks": [{"t": "h3", "x": "Två arbetsbredder", "d": true}, {"t": "ul", "items": ["Planeringslåda 550 mm: mått 550 × 950 × 500 mm, vikt ca 174 kg, anpassad för Trafikverkets och SL:s kabelränna 350.", "Planeringslåda 950 mm: mått 950 × 950 × 500 mm, vikt ca 207 kg, anpassad för Trafikverkets och SL:s kabelränna 535."], "d": true}, {"t": "h3", "x": "Material", "d": true}, {"t": "p", "x": "Lådan är tillverkad i S355-stål med pulverlackering och har fäste S60. Kantstålen är i HB450 slitstål och är vändbara och utbytbara.", "d": true}, {"t": "h3", "x": "Reservdelar", "d": true}, {"t": "p", "x": "Kantstål finns som reservdel för enkelt byte vid arbete med makadam, grus och andra slitande material. Vagnsskruvar, brickor och muttrar ingår.", "d": true}], "faq": []}, "fi": {"intro": "Sepelilaatikko sepelille ja soralle, kehitetty rautatie- ja infrastruktuurikohteiden tasaustöihin, esimerkiksi ennen kaapelikanavan asentamista.", "introDraft": true, "h": "Tietoa sepelilaatikoista", "blocks": [{"t": "h3", "x": "Kaksi työleveyttä", "d": true}, {"t": "ul", "items": ["Sepelilaatikko 550 mm: mitat 550 × 950 × 500 mm, paino n. 174 kg, sovitettu Trafikverketin ja SL:n kaapelikouruun 350.", "Sepelilaatikko 950 mm: mitat 950 × 950 × 500 mm, paino n. 207 kg, sovitettu Trafikverketin ja SL:n kaapelikouruun 535."], "d": true}, {"t": "h3", "x": "Materiaali", "d": true}, {"t": "p", "x": "Laatikko on valmistettu jauhemaalatusta S355-teräksestä, ja siinä on S60-kiinnitys. Reunaterät ovat HB450-kulutusterästä, ja ne ovat käännettäviä ja vaihdettavia.", "d": true}, {"t": "h3", "x": "Varaosat", "d": true}, {"t": "p", "x": "Reunateriä on saatavilla varaosina, joten ne on helppo vaihtaa, kun työskennellään sepelin, soran ja muiden kuluttavien materiaalien kanssa. Lukkopultit, aluslevyt ja mutterit sisältyvät toimitukseen.", "d": true}], "faq": []}}, "jvg/stegjarn": {"status": "befintlig", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/material-kabelbrunnar/stegjarn-nedstigningshjalpmedel", "name": "Stegjärn/ nedstigningshjälpmedel", "use": "text+faq"}], "words": 188, "faqWords": 92, "check": "Teksti ja FAQ sellaisenaan.", "sv": {"intro": "Stegjärn är viktiga hjälpmedel för säker och bekväm nedstigning i kabelbrunnar och andra underjordiska strukturer. På Svenska Brunnslock erbjuder vi högkvalitativa stegjärn som är designade för att möta de strängaste säkerhetskraven.", "introDraft": false, "blocks": [{"t": "h3", "x": "Stegjärn: säkerhet och bekvämlighet för nedstigning"}, {"t": "p", "x": "Här går vi igenom fördelarna med stegjärn, våra produkter och deras användning."}, {"t": "h3", "x": "Fördelar med stegjärn"}, {"t": "p", "x": "Stegjärn ger ett säkert och stabilt fotfäste vid nedstigning i kabelbrunnar, vilket minskar risken för olyckor och skador. De är särskilt viktiga i djupa eller trånga brunnar där traditionella stegar inte är praktiska. Genom att använda stegjärn från Svenska Brunnslock kan du säkerställa att dina arbetare har en säker och bekväm nedstigning."}, {"t": "h3", "x": "Våra produkter"}, {"t": "p", "x": "Vi erbjuder stegjärn i olika storlekar och material, inklusive rostfritt stål och aluminium. Våra stegjärn är utformade för att vara hållbara och korrosionsbeständiga, vilket garanterar lång livslängd och pålitlig prestanda. Oavsett dina specifika krav har vi rätt stegjärn för dina behov."}, {"t": "h3", "x": "Användning och installation"}, {"t": "p", "x": "Stegjärn är enkla att installera och använda. Våra produkter kommer med detaljerade installationsanvisningar för att säkerställa korrekt montering och optimal säkerhet. Genom att följa dessa anvisningar kan du snabbt och effektivt förbättra säkerheten vid nedstigning i dina kabelbrunnar."}], "faq": [{"q": "Vad är fördelen med att använda stegjärn i kabelbrunnar?", "a": ["Stegjärn ger ett säkert fotfäste vid nedstigning, vilket minskar risken för olyckor, särskilt i djupa eller trånga brunnar där vanliga stegar kan vara opraktiska."]}, {"q": "Vilka material finns stegjärn i?", "a": ["Våra stegjärn tillverkas i hållbart rostfritt stål och aluminium för hög korrosionsbeständighet och lång livslängd."]}, {"q": "Är stegjärn enkla att installera?", "a": ["Ja, stegjärnen levereras med tydliga installationsanvisningar för enkel och säker montering."]}, {"q": "Vilka storlekar finns tillgängliga för stegjärn?", "a": ["Vi erbjuder stegjärn i olika storlekar för att möta specifika installations behov i olika typer av brunnar."]}]}, "fi": {"intro": "Kiipeilyraudat ovat tärkeitä apuvälineitä turvalliseen ja mukavaan laskeutumiseen kaapelikaivoihin ja muihin maanalaisiin rakenteisiin. Svenska Brunnslockilla tarjoamme laadukkaita kiipeilyrautoja, jotka on suunniteltu täyttämään tiukimmatkin turvallisuusvaatimukset.", "introDraft": false, "h": "Tietoa kiipeilyraudoista ja laskeutumistikkaista", "blocks": [{"t": "h3", "x": "Kiipeilyraudat: turvallisuutta ja mukavuutta laskeutumiseen"}, {"t": "p", "x": "Tässä käymme läpi kiipeilyrautojen edut, tuotteemme ja niiden käytön."}, {"t": "h3", "x": "Kiipeilyrautojen edut"}, {"t": "p", "x": "Kiipeilyraudat antavat turvallisen ja vakaan jalansijan kaapelikaivoihin laskeuduttaessa, mikä vähentää onnettomuuksien ja vammojen riskiä. Ne ovat erityisen tärkeitä syvissä tai ahtaissa kaivoissa, joissa perinteiset tikkaat eivät ole käytännöllisiä. Käyttämällä Svenska Brunnslockin kiipeilyrautoja voit varmistaa, että työntekijäsi voivat laskeutua turvallisesti ja mukavasti."}, {"t": "h3", "x": "Tuotteemme"}, {"t": "p", "x": "Tarjoamme kiipeilyrautoja eri kokoina ja materiaaleina, muun muassa ruostumattomasta teräksestä ja alumiinista. Kiipeilyrautamme on suunniteltu kestäviksi ja korroosionkestäviksi, mikä takaa pitkän käyttöiän ja luotettavan toimivuuden. Olivatpa erityisvaatimuksesi mitkä tahansa, meiltä löytyvät oikeat kiipeilyraudat tarpeisiisi."}, {"t": "h3", "x": "Käyttö ja asennus"}, {"t": "p", "x": "Kiipeilyraudat on helppo asentaa ja käyttää. Tuotteidemme mukana tulevat yksityiskohtaiset asennusohjeet, jotka varmistavat oikean asennuksen ja optimaalisen turvallisuuden. Noudattamalla näitä ohjeita voit nopeasti ja tehokkaasti parantaa turvallisuutta kaapelikaivoihin laskeuduttaessa."}], "faq": [{"q": "Mitä etua kiipeilyrautojen käytöstä kaapelikaivoissa on?", "a": ["Kiipeilyraudat antavat turvallisen jalansijan laskeuduttaessa, mikä vähentää onnettomuuksien riskiä etenkin syvissä tai ahtaissa kaivoissa, joissa tavalliset tikkaat voivat olla epäkäytännöllisiä."]}, {"q": "Mistä materiaaleista kiipeilyrautoja on saatavilla?", "a": ["Kiipeilyrautamme valmistetaan kestävästä ruostumattomasta teräksestä ja alumiinista, joten niillä on hyvä korroosionkestävyys ja pitkä käyttöikä."]}, {"q": "Onko kiipeilyraudat helppo asentaa?", "a": ["Kyllä, kiipeilyrautojen mukana toimitetaan selkeät asennusohjeet helppoa ja turvallista asennusta varten."]}, {"q": "Missä koissa kiipeilyrautoja on saatavilla?", "a": ["Tarjoamme kiipeilyrautoja eri kokoina erilaisten kaivotyyppien erityisiin asennustarpeisiin."]}]}}, "jvg/profiler": {"status": "kombinerad", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/material-kabelbrunnar/u-och-l-profiler", "name": "U- och L-profiler", "use": "text+faq"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/material-kabelbrunnar/pendelskena", "name": "Pendelskena", "use": "text+faq"}], "words": 305, "faqWords": 201, "check": "Kaksi tekstiä ja FAQ yhdistetty.", "sv": {"intro": "U & L profiler är viktiga komponenter för att bygga och förstärka kabelbrunnar och andra strukturer. På Svenska Brunnslock erbjuder vi högkvalitativa U & L profiler som är designade för att ge maximal styrka och flexibilitet.", "introDraft": false, "blocks": [{"t": "h3", "x": "U & L profil: mångsidiga lösningar för kabelbrunnar"}, {"t": "p", "x": "Här går vi igenom fördelarna med dessa profiler, våra produktalternativ och hur de används."}, {"t": "h3", "x": "Fördelar med U & L profiler"}, {"t": "p", "x": "U & L profiler erbjuder mångsidiga lösningar för byggnation och förstärkning av kabelbrunnar. Deras design gör dem idealiska för att skapa robusta och stabila strukturer som kan motstå tunga belastningar och påfrestningar. Profilerna är också enkla att anpassa och installera, vilket gör dem till en favorit bland byggare och ingenjörer."}, {"t": "h3", "x": "Våra produkter"}, {"t": "p", "x": "Vi erbjuder ett brett utbud av U & L profiler i olika storlekar och material, inklusive stål och aluminium. Våra profiler är tillverkade av högkvalitativa material som garanterar lång hållbarhet och motståndskraft mot korrosion. Oavsett om du behöver profiler för små projekt eller stora kommersiella installationer, har vi rätt lösning för dig."}, {"t": "h3", "x": "Användning och installation"}, {"t": "p", "x": "U & L profiler är enkla att använda och installera. De kan skäras och anpassas för att passa specifika behov och strukturer. Våra produkter levereras med detaljerade installationsanvisningar för att säkerställa korrekt montering och optimal prestanda. Genom att använda våra U & L profiler kan du skapa starka och hållbara konstruktioner för dina kabelbrunnar och andra byggprojekt."}, {"t": "h3", "x": "Pendelskena: flexibilitet och funktionalitet för dina kabelbrunnar"}, {"t": "p", "x": "En pendelskena är en mångsidig komponent som erbjuder flexibilitet och enkel hantering av kablar i brunnar och andra installationer. På Svenska Brunnslock erbjuder vi pendelskenor som är designade för att möta dina specifika behov."}, {"t": "h4", "x": "Fördelar med pendelskena"}, {"t": "p", "x": "Pendelskenor möjliggör enkel justering och hantering av kablar, vilket gör dem idealiska för komplexa kabelinstallationer. De erbjuder flexibilitet och hållbarhet, vilket säkerställer att kablarna hålls organiserade och lättillgängliga. Detta minskar risken för skador på kablarna och underlättar framtida underhåll och omkonfigurationer."}], "faq": [{"q": "Vad används U- och L-profiler till i kabelbrunnar?", "a": ["U- och L-profiler används för att förstärka och stabilisera kabelbrunnar samt andra strukturer, vilket ökar deras hållbarhet och belastningskapacitet."]}, {"q": "Vilka material finns U- och L-profiler i?", "a": ["Våra U- och L-profiler finns i stål och aluminium för att ge hållbarhet och motståndskraft mot korrosion."]}, {"q": "Är U- och L-profiler enkla att installera?", "a": ["Ja, profilerna är utformade för enkel installation och kan justeras för att passa olika strukturer. Installationsanvisningar medföljer produkten."]}, {"q": "Vilka storlekar finns tillgängliga för U- och L-profiler?", "a": ["Vi erbjuder ett brett utbud av storlekar för att passa specifika behov i både små och stora installationsprojekt."]}, {"q": "Vad är en pendelskena?", "a": ["En pendelskena eller kabelstege som man kallar dessa är en flexibel komponent som underlättar hantering och organisering av kablar i brunnar, vilket minskar risken för kabelskador och gör underhåll enklare."]}, {"q": "Var används pendelskenor vanligtvis?", "a": ["Pendelskenor används främst i kabelbrunnar och andra installationsmiljöer där kablar måste hållas organiserade och lättillgängliga."]}, {"q": "Vilka storlekar finns för pendelskenor?", "a": ["Vi erbjuder pendelskenor i olika storlekar och utföranden för att passa specifika installationsbehov."]}, {"q": "Är det svårt att installera en pendelskena?", "a": ["Nej, pendelskenor är enkla att installera och levereras med installationsanvisningar för att säkerställa korrekt montering"]}]}, "fi": {"intro": "U- ja L-profiilit ovat tärkeitä komponentteja kaapelikaivojen ja muiden rakenteiden rakentamisessa ja vahvistamisessa. Svenska Brunnslockilla tarjoamme laadukkaita U- ja L-profiileja, jotka on suunniteltu antamaan maksimaalinen lujuus ja joustavuus.", "introDraft": false, "h": "Tietoa profiileista", "blocks": [{"t": "h3", "x": "U- ja L-profiilit: monipuolisia ratkaisuja kaapelikaivoihin"}, {"t": "p", "x": "Tässä käymme läpi näiden profiilien edut, tuotevaihtoehtomme ja niiden käytön."}, {"t": "h3", "x": "U- ja L-profiilien edut"}, {"t": "p", "x": "U- ja L-profiilit tarjoavat monipuolisia ratkaisuja kaapelikaivojen rakentamiseen ja vahvistamiseen. Niiden muotoilu tekee niistä ihanteellisia tukevien ja vakaiden rakenteiden tekemiseen, jotka kestävät raskaita kuormituksia ja rasituksia. Profiilit on myös helppo muokata ja asentaa, minkä vuoksi ne ovat rakentajien ja insinöörien suosikki."}, {"t": "h3", "x": "Tuotteemme"}, {"t": "p", "x": "Tarjoamme laajan valikoiman U- ja L-profiileja eri kokoina ja materiaaleina, muun muassa teräksestä ja alumiinista. Profiilimme on valmistettu laadukkaista materiaaleista, jotka takaavat pitkän kestävyyden ja korroosionkestävyyden. Tarvitsitpa profiileja pieniin hankkeisiin tai suuriin kaupallisiin asennuksiin, meiltä löytyy sinulle oikea ratkaisu."}, {"t": "h3", "x": "Käyttö ja asennus"}, {"t": "p", "x": "U- ja L-profiilit on helppo käyttää ja asentaa. Ne voidaan leikata ja muokata sopimaan tiettyihin tarpeisiin ja rakenteisiin. Tuotteidemme mukana toimitetaan yksityiskohtaiset asennusohjeet, jotka varmistavat oikean asennuksen ja optimaalisen toimivuuden. Käyttämällä U- ja L-profiilejamme voit tehdä vahvoja ja kestäviä rakenteita kaapelikaivoihisi ja muihin rakennushankkeisiisi."}, {"t": "h3", "x": "Kaapelikisko: joustavuutta ja toimivuutta kaapelikaivoihisi"}, {"t": "p", "x": "Kaapelikisko on monipuolinen komponentti, joka tarjoaa joustavuutta ja helpottaa kaapelien käsittelyä kaivoissa ja muissa asennuksissa. Svenska Brunnslockilla tarjoamme kaapelikiskoja, jotka on suunniteltu vastaamaan juuri sinun tarpeitasi."}, {"t": "h4", "x": "Kaapelikiskon edut"}, {"t": "p", "x": "Kaapelikiskojen ansiosta kaapeleita on helppo säätää ja käsitellä, mikä tekee niistä ihanteellisia monimutkaisiin kaapeliasennuksiin. Ne tarjoavat joustavuutta ja kestävyyttä, mikä varmistaa, että kaapelit pysyvät järjestyksessä ja helposti saatavilla. Tämä vähentää kaapelivaurioiden riskiä ja helpottaa tulevia huoltoja ja uudelleenjärjestelyjä."}], "faq": [{"q": "Mihin U- ja L-profiileja käytetään kaapelikaivoissa?", "a": ["U- ja L-profiileja käytetään kaapelikaivojen ja muiden rakenteiden vahvistamiseen ja vakauttamiseen, mikä lisää niiden kestävyyttä ja kuormituskapasiteettia."]}, {"q": "Mistä materiaaleista U- ja L-profiileja on saatavilla?", "a": ["U- ja L-profiilejamme on saatavilla teräksestä ja alumiinista, jotta ne olisivat kestäviä ja korroosionkestäviä."]}, {"q": "Onko U- ja L-profiilit helppo asentaa?", "a": ["Kyllä, profiilit on suunniteltu helposti asennettaviksi, ja niitä voi säätää sopimaan erilaisiin rakenteisiin. Asennusohjeet toimitetaan tuotteen mukana."]}, {"q": "Missä koissa U- ja L-profiileja on saatavilla?", "a": ["Tarjoamme laajan kokovalikoiman erityistarpeisiin sekä pienissä että suurissa asennushankkeissa."]}, {"q": "Mikä on kaapelikisko?", "a": ["Kaapelikisko (riippukisko) eli kaapelitikas, kuten näitä kutsutaan, on joustava komponentti, joka helpottaa kaapelien käsittelyä ja järjestämistä kaivoissa, mikä vähentää kaapelivaurioiden riskiä ja helpottaa huoltoa."]}, {"q": "Missä kaapelikiskoja tavallisesti käytetään?", "a": ["Kaapelikiskoja käytetään pääasiassa kaapelikaivoissa ja muissa asennusympäristöissä, joissa kaapelit on pidettävä järjestyksessä ja helposti saatavilla."]}, {"q": "Missä koissa kaapelikiskoja on saatavilla?", "a": ["Tarjoamme kaapelikiskoja eri kokoina ja malleina erityisiin asennustarpeisiin."]}, {"q": "Onko kaapelikiskon asentaminen vaikeaa?", "a": ["Ei, kaapelikiskot on helppo asentaa, ja niiden mukana toimitetaan asennusohjeet oikean asennuksen varmistamiseksi."]}]}}, "jvg/grod": {"status": "befintlig", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/material-kabelbrunnar/grod-och-kraldjursevakuering", "name": "Grod och kräldjursevakuering", "use": "text+faq"}], "words": 263, "faqWords": 107, "check": "Teksti ja FAQ sellaisenaan.", "sv": {"intro": "Evakueringsrör Dim. 110mm för grod- och kräldjur i kabelbrunnar.", "introDraft": false, "blocks": [{"t": "p", "x": "Rören är täta med korrugerad insida som gör att kräldjur lättare kan ta sig ut ur brunnar. Materialet är tillverkat i HD-PE, är UV-beständigt, belastningsklass SN8 (normala förhållanden)."}, {"t": "p", "x": "Säljs på rulle av 50 meter."}, {"t": "h3", "x": "Kräldjur evakuering: skydda djurlivet i kabelbrunnar"}, {"t": "p", "x": "Kräldjursevakuering är en viktig åtgärd för att skydda djurlivet, särskilt kräldjur, som ofta kan fastna i kabelbrunnar och andra underjordiska strukturer. På Svenska Brunnslock erbjuder vi lösningar för kräldjursevakuering som hjälper till att säkert och effektivt evakuera djur. Här diskuterar vi varför kräldjursevakuering är viktig, våra produkter och deras användning."}, {"t": "h3", "x": "Varför kräldjursevakuering?"}, {"t": "p", "x": "Kräldjur som ormar och ödlor kan lätt fastna i kabelbrunnar, vilket kan leda till skador eller dödsfall för djuren. Att installera lösningar för kräldjursevakuering är inte bara en åtgärd för djurskydd, utan också för att förhindra potentiella driftstopp och underhållsproblem. Genom att använda våra produkter kan du säkerställa en säkrare miljö för både djur och människor."}, {"t": "h3", "x": "Våra produkter"}, {"t": "p", "x": "Vi erbjuder olika typer av kräldjursevakuering, inklusive ramp- och stegsystem som gör det möjligt för djuren att själva ta sig ut ur brunnarna. Våra produkter är tillverkade av hållbara material som tål de påfrestningar som kommer med daglig användning i tuffa miljöer. Oavsett dina specifika behov har vi rätt lösning för att skydda djurlivet i dina kabelbrunnar."}, {"t": "h3", "x": "Användning och installation"}, {"t": "p", "x": "Kräldjursevakuering är enkel att installera och integrera i befintliga kabelbrunnssystem. Våra produkter kommer med detaljerade installationsanvisningar för att säkerställa korrekt montering och maximal effektivitet. Genom att följa dessa anvisningar kan du säkerställa att dina kabelbrunnar är säkra för både djur och människor."}], "faq": [{"q": "Vad är syftet med grod- och kräldjursevakuering i kabelbrunnar?", "a": ["Grod- och kräldjursevakuering skyddar djurlivet genom att ge grodor och kräldjur en väg ut ur kabelbrunnar, vilket minskar risken för att de fastnar och skadas."]}, {"q": "Vilket material används för evakueringsrören?", "a": ["Evakueringsrören är tillverkade i HD-PE, vilket gör dem slitstarka och UV-beständiga för att klara olika väderförhållanden."]}, {"q": "Hur installeras evakueringsrören för kräldjur?", "a": ["Rören är enkla att installera i kabelbrunnar och levereras med instruktioner för att säkerställa att de ger effektiv evakuering för djur."]}, {"q": "Vilka dimensioner finns för evakueringsrören?", "a": ["Våra evakueringsrör har en standard diameter på 110 mm och säljs i rullar om 50 meter för enkel hantering."]}]}, "fi": {"intro": "Poistumisputki, koko 110 mm, sammakoille ja matelijoille kaapelikaivoihin.", "introDraft": false, "h": "Tietoa sammakko- ja matelijaesteistä", "blocks": [{"t": "p", "x": "Putket ovat tiiviitä, ja niiden sisäpinta on korrugoitu, jolloin matelijat pääsevät helpommin ulos kaivoista. Materiaali on HD-PE:tä, UV-kestävä, kuormitusluokka SN8 (normaalit olosuhteet)."}, {"t": "p", "x": "Myydään 50 metrin rullissa."}, {"t": "h3", "x": "Matelijoiden poistumisratkaisut: suojele eläimistöä kaapelikaivoissa"}, {"t": "p", "x": "Matelijoiden poistumisratkaisut ovat tärkeä toimenpide eläimistön, erityisesti matelijoiden, suojelemiseksi, sillä ne voivat helposti jäädä loukkuun kaapelikaivoihin ja muihin maanalaisiin rakenteisiin. Svenska Brunnslockilla tarjoamme matelijoiden poistumisratkaisuja, jotka auttavat eläimiä pääsemään pois turvallisesti ja tehokkaasti. Tässä kerromme, miksi matelijoiden poistumisratkaisut ovat tärkeitä, sekä esittelemme tuotteemme ja niiden käytön."}, {"t": "h3", "x": "Miksi matelijoiden poistumisratkaisuja?"}, {"t": "p", "x": "Matelijat, kuten käärmeet ja sisiliskot, voivat helposti jäädä loukkuun kaapelikaivoihin, mikä voi johtaa eläinten vahingoittumiseen tai kuolemaan. Matelijoiden poistumisratkaisujen asentaminen ei ole vain eläinsuojelutoimenpide, vaan sillä myös ehkäistään mahdollisia käyttökatkoja ja huolto-ongelmia. Käyttämällä tuotteitamme voit varmistaa turvallisemman ympäristön sekä eläimille että ihmisille."}, {"t": "h3", "x": "Tuotteemme"}, {"t": "p", "x": "Tarjoamme erityyppisiä matelijoiden poistumisratkaisuja, muun muassa ramppi- ja porrasjärjestelmiä, joiden avulla eläimet pääsevät itse ulos kaivoista. Tuotteemme on valmistettu kestävistä materiaaleista, jotka kestävät päivittäisen käytön rasitukset vaativissa ympäristöissä. Olivatpa erityistarpeesi mitkä tahansa, meiltä löytyy oikea ratkaisu eläimistön suojelemiseen kaapelikaivoissasi."}, {"t": "h3", "x": "Käyttö ja asennus"}, {"t": "p", "x": "Matelijoiden poistumisratkaisut on helppo asentaa ja liittää olemassa oleviin kaapelikaivojärjestelmiin. Tuotteidemme mukana tulevat yksityiskohtaiset asennusohjeet, jotka varmistavat oikean asennuksen ja maksimaalisen tehokkuuden. Noudattamalla näitä ohjeita voit varmistaa, että kaapelikaivosi ovat turvallisia sekä eläimille että ihmisille."}], "faq": [{"q": "Mikä on sammakoiden ja matelijoiden poistumisratkaisujen tarkoitus kaapelikaivoissa?", "a": ["Sammakoiden ja matelijoiden poistumisratkaisut suojelevat eläimistöä antamalla sammakoille ja matelijoille reitin ulos kaapelikaivoista, mikä vähentää riskiä, että ne jäävät loukkuun ja vahingoittuvat."]}, {"q": "Mistä materiaalista poistumisputket on valmistettu?", "a": ["Poistumisputket on valmistettu HD-PE:stä, minkä ansiosta ne ovat kulutusta kestäviä ja UV-kestäviä ja kestävät erilaiset sääolosuhteet."]}, {"q": "Miten matelijoiden poistumisputket asennetaan?", "a": ["Putket on helppo asentaa kaapelikaivoihin, ja niiden mukana toimitetaan ohjeet, joilla varmistetaan, että ne toimivat tehokkaana poistumisreittinä eläimille."]}, {"q": "Missä koissa poistumisputkia on saatavilla?", "a": ["Poistumisputkiemme vakiohalkaisija on 110 mm, ja niitä myydään 50 metrin rullissa käsittelyn helpottamiseksi."]}]}}, "jvg/ovrigt": {"status": "kombinerad + utkast", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/material-kabelbrunnar/tralock-tunnelbana-kanalisation", "name": "Trälock, tunnelbana kanalisation", "use": "text+faq"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/material-kabelbrunnar/plattform-for-kabelskap", "name": "Plattform för kabelskåp", "use": "text+faq"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/material-kabelbrunnar/markskylt-for-kabelbrunn", "name": "Märkskylt för kabelbrunn", "use": "text+faq"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/material-kabelbrunnar/skavskydd-gummiduk", "name": "Skavskydd/gummiduk", "use": "text+faq"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/material-kabelbrunnar/bryggstolpe-kontaktledningstolpe", "name": "Bryggstolpe/kontaktledningstolpe", "use": "text"}], "words": 414, "faqWords": 375, "check": "Viisi tekstiä ja neljä FAQ:ta yhdistetty; intro on Genero-luonnos (kooste). Pitkä: SB voi karsia.", "sv": {"intro": "Trälock, plattformar för kabelskåp, märkskyltar, skavskydd och bryggstolpar för kabelbrunnar längs järnväg och i kanalisation.", "introDraft": true, "blocks": [{"t": "h3", "x": "Trälock för tunnelbana och kanalisation"}, {"t": "p", "x": "Trälocken tillverkas i tryckimpregnerat virke klass NTR-AB. Virkes dimensioner 28x120 och 28x95 mm. Locken skruvas ihop med träskruv 4,2x45 mm. Träskruv monteras från undersida lock. Tillverkas enligt SL (Stockholms Lokaltrafik) ritnings nr. 0021-6220-0042. Används bl.a i tunnlar som kanalisationslock."}, {"t": "h4", "x": "Trälock för brunnar: traditionell och estetisk lösning"}, {"t": "p", "x": "Trälock för brunnar erbjuder en estetiskt tilltalande och funktionell lösning för specifika tillämpningar såsom tunnelbanor och kanalisationer. På Svenska Brunnslock erbjuder vi trälock som kombinerar traditionellt utseende med moderna funktioner."}, {"t": "h3", "x": "Plattform för kabelskåp"}, {"t": "p", "x": "Finns i standardlängder i lager."}, {"t": "ul", "items": ["Plattform 2000 mm", "Plattform 3000 mm"]}, {"t": "p", "x": "Vi tillverkar även plattformar i andra bredder efter beställning, exempelvis:"}, {"t": "ul", "items": ["Plattform bredd 1000 mm.", "Plattform bredd 2200 mm", "Plattform bredd 6000 mm.", "Plattform bredd 9000 mm."]}, {"t": "p", "x": "BASTA registrerad."}, {"t": "p", "x": "Tillverkas enligt trafikverkets ritningsunderlag 7-801 656."}, {"t": "p", "x": "Vi varmgalvaniserar alla detaljer enligt SS-EN ISO 1461."}, {"t": "h4", "x": "Plattform för kabelskåp: stabil och säker grund"}, {"t": "p", "x": "En plattform för kabelskåp är avgörande för att säkerställa en stabil och säker installation av kabelskåp och annan utrustning. På Svenska Brunnslock erbjuder vi plattformar som kombinerar hållbarhet med enkel installation."}, {"t": "h3", "x": "Märkskylt för kabelbrunn: enkel och tydlig identifiering"}, {"t": "p", "x": "En märkskylt för kabelbrunn är avgörande för att säkerställa enkel och tydlig identifiering av brunnar och deras innehåll. På Svenska Brunnslock erbjuder vi märkplattor som är designade för att vara hållbara och lätta att läsa."}, {"t": "h4", "x": "Fördelar med märkskyltar"}, {"t": "p", "x": "Märkskyltar gör det enkelt att identifiera kabelbrunnar och dess innehåll, vilket är viktigt för effektiv underhåll och säkerhet. Tydliga och hållbara skyltar minskar risken för misstag och felaktig hantering av kablar och utrustning. Genom att använda märkplattor från Svenska Brunnslock, kan du säkerställa att all nödvändig information alltid är lätt tillgänglig."}, {"t": "h3", "x": "Skavskydd brunn: skydda kablar och utrustning"}, {"t": "p", "x": "Skavskydd för brunnar är en viktig komponent för att skydda kablar och annan utrustning från slitage och skador. På Svenska Brunnslock erbjuder vi effektiva skavskydd som är designade för att förlänga livslängden på dina kablar och utrustning."}, {"t": "h4", "x": "Varför välja skavskydd?"}, {"t": "p", "x": "Skavskydd skyddar kablar och utrustning från nötning och mekaniska skador, vilket är särskilt viktigt i miljöer där kablar dras genom trånga utrymmen eller utsätts för rörelse. Genom att använda skavskydd från Svenska Brunnslock, kan du minimera risken för kabelbrott och andra skador, vilket säkerställer pålitlig drift och minskat underhåll."}, {"t": "h3", "x": "Bryggstolpe och kontaktledningsstolpe"}, {"t": "p", "x": "Kontaktledningsstolpar eller bryggstolpar tillverkas utifrån Trafikverkets ritningsunderlag."}, {"t": "ul", "items": ["513 142/0411037 & 0411039", "513 330/0411057", "513 385/0411030", "513 201/0411031", "515 200/0411067"]}], "faq": [{"q": "Vilka är fördelarna med trälock för brunnar?", "a": ["Trälock är estetiska, ger naturlig isolering och är ideala för miljöer där man vill undvika elektrisk ledningsförmåga."]}, {"q": "I vilka miljöer används trälock för brunnar?", "a": ["Trälock används ofta i tunnelbanor, kanalisationer och naturskyddsområden där ett naturligt utseende och låg ledningsförmåga behövs."]}, {"q": "Hur underhålls trälock för brunnar?", "a": ["Trälock kräver grundläggande underhåll för att hålla länge, vilket inkluderar att kontrollera skruvar och eventuellt ytbehandling vid behov."]}, {"q": "Är trälocken impregnerade?", "a": ["Ja, våra trälock är tryckimpregnerade för att tåla fukt och slitage över tid."]}, {"q": "Vad är syftet med en plattform för kabelskåp?", "a": ["En plattform för kabelskåp ger en stabil och säker grund för kabelskåp, vilket skyddar dem från markfukt, vibrationer och andra skador."]}, {"q": "Vilka storlekar finns för plattformar till kabelskåp?", "a": ["Vi erbjuder standardlängder på 2000 mm och 3000 mm samt anpassade bredder från 1000 mm till 9000 mm."]}, {"q": "Är plattformarna korrosionsbeständiga?", "a": ["Ja, våra plattformar är varmgalvaniserade enligt SS-EN ISO 1461 för långvarigt skydd mot korrosion."]}, {"q": "Hur installeras en plattform för kabelskåp?", "a": ["Plattformarna är enkla att installera och levereras med tydliga anvisningar för säker montering och stabilitet."]}, {"q": "Vad är syftet med en märkskylt för kabelbrunn?", "a": ["En märkskylt för kabelbrunn säkerställer tydlig och enkel identifiering av brunnar och kablar, vilket underlättar underhåll och ökar säkerheten."]}, {"q": "Vilka material är märkskyltarna gjorda av?", "a": ["Våra märkplattor är tillverkade av hållbara, väderbeständiga, rostfri syrafast stålmaterial som behåller sin läsbarhet över tid."]}, {"q": "Är det enkelt att installera en märkskylt för kabelbrunn?", "a": ["Ja, märkskyltar är enkla att installera och kan fästas på flera typer av ytor. Installationsanvisningar medföljer produkten."]}, {"q": "Vilka storlekar finns tillgängliga för märkplattor?", "a": ["Vi erbjuder märkplattor i olika storlekar, följer Trafikverkets ritningar för att passa både små installationer och större nätverk av kabelbrunnar."]}, {"q": "Vad är syftet med skavskydd i en brunn?", "a": ["Skavskydd skyddar kablar och annan utrustning från slitage och skador, vilket förlänger deras livslängd och minskar risken för driftstopp."]}, {"q": "Vilka material används för skavskydd?", "a": ["Våra skavskydd består huvudsakligen av slitstark gummiduk och andra flexibla material som är anpassade för olika typer av brunnar och installationer."]}, {"q": "Hur installeras skavskydd?", "a": ["Skavskydd är enkla att installera och levereras med tydliga instruktioner för korrekt applicering i brunnar och kabelgenomföringar."]}, {"q": "Vilka storlekar finns tillgängliga för gummiduk?", "a": ["Vi erbjuder skavskydd i olika storlekar och tjocklekar för att passa specifika installations behov och utrymmen."]}]}, "fi": {"intro": "Puukannet, kaapelikaappitasot, merkintäkilvet, hankaussuojat ja porttipylväät kaapelikaivoihin rautateiden varrelle ja kaapelikanavointiin.", "introDraft": true, "h": "Tietoa muista kaapelikaivotarvikkeista", "blocks": [{"t": "h3", "x": "Puukannet metroon ja kaapelikanavointiin"}, {"t": "p", "x": "Puukannet valmistetaan painekyllästetystä puutavarasta, luokka NTR-AB. Puutavaran mitat 28x120 ja 28x95 mm. Kannet kootaan puuruuveilla 4,2x45 mm. Puuruuvit asennetaan kannen alapuolelta. Valmistetaan SL:n (Stockholms Lokaltrafik) piirustuksen nro 0021-6220-0042 mukaisesti. Käytetään mm. tunneleissa kaapelikanavien kansina."}, {"t": "h4", "x": "Kaivojen puukannet: perinteinen ja esteettinen ratkaisu"}, {"t": "p", "x": "Kaivojen puukannet ovat esteettisesti miellyttävä ja toimiva ratkaisu erityisiin käyttökohteisiin, kuten metroihin ja kaapelikanavointeihin. Svenska Brunnslockilla tarjoamme puukansia, joissa perinteinen ulkonäkö yhdistyy nykyaikaisiin toimintoihin."}, {"t": "h3", "x": "Kaapelikaappitaso"}, {"t": "p", "x": "Saatavilla vakiopituuksina varastosta."}, {"t": "ul", "items": ["Taso 2000 mm", "Taso 3000 mm"]}, {"t": "p", "x": "Valmistamme tilauksesta myös muun levyisiä tasoja, esimerkiksi:"}, {"t": "ul", "items": ["Taso, leveys 1000 mm.", "Taso, leveys 2200 mm", "Taso, leveys 6000 mm.", "Taso, leveys 9000 mm."]}, {"t": "p", "x": "BASTA-rekisteröity."}, {"t": "p", "x": "Valmistetaan Trafikverketin piirustuksen 7-801 656 mukaisesti."}, {"t": "p", "x": "Kuumasinkitsemme kaikki osat standardin SS-EN ISO 1461 mukaisesti."}, {"t": "h4", "x": "Kaapelikaappitaso: vakaa ja turvallinen perusta"}, {"t": "p", "x": "Kaapelikaappitaso on ratkaisevan tärkeä kaapelikaappien ja muiden laitteiden vakaan ja turvallisen asennuksen varmistamiseksi. Svenska Brunnslockilla tarjoamme tasoja, joissa kestävyys yhdistyy helppoon asennukseen."}, {"t": "h3", "x": "Kaapelikaivon merkintäkilpi: helppo ja selkeä tunnistus"}, {"t": "p", "x": "Kaapelikaivon merkintäkilpi on ratkaisevan tärkeä kaivojen ja niiden sisällön helpon ja selkeän tunnistamisen varmistamiseksi. Svenska Brunnslockilla tarjoamme merkintälaattoja, jotka on suunniteltu kestäviksi ja helppolukuisiksi."}, {"t": "h4", "x": "Merkintäkilpien edut"}, {"t": "p", "x": "Merkintäkilvet helpottavat kaapelikaivojen ja niiden sisällön tunnistamista, mikä on tärkeää tehokkaan huollon ja turvallisuuden kannalta. Selkeät ja kestävät kilvet vähentävät virheiden sekä kaapelien ja laitteiden väärän käsittelyn riskiä. Käyttämällä Svenska Brunnslockin merkintälaattoja voit varmistaa, että kaikki tarvittava tieto on aina helposti saatavilla."}, {"t": "h3", "x": "Kaivon hankaussuoja: suojaa kaapeleita ja laitteita"}, {"t": "p", "x": "Kaivojen hankaussuoja on tärkeä komponentti, joka suojaa kaapeleita ja muita laitteita kulumiselta ja vaurioilta. Svenska Brunnslockilla tarjoamme tehokkaita hankaussuojia, jotka on suunniteltu pidentämään kaapeliesi ja laitteidesi käyttöikää."}, {"t": "h4", "x": "Miksi valita hankaussuoja?"}, {"t": "p", "x": "Hankaussuoja suojaa kaapeleita ja laitteita hankautumiselta ja mekaanisilta vaurioilta, mikä on erityisen tärkeää ympäristöissä, joissa kaapelit vedetään ahtaiden tilojen läpi tai ne ovat alttiina liikkeelle. Käyttämällä Svenska Brunnslockin hankaussuojia voit minimoida kaapelikatkosten ja muiden vaurioiden riskin, mikä varmistaa luotettavan toiminnan ja vähentää huoltotarvetta."}, {"t": "h3", "x": "Porttipylväs ja ajojohdinpylväs"}, {"t": "p", "x": "Ajojohdinpylväät tai porttipylväät valmistetaan Trafikverketin piirustusten mukaisesti."}, {"t": "ul", "items": ["513 142/0411037 & 0411039", "513 330/0411057", "513 385/0411030", "513 201/0411031", "515 200/0411067"]}], "faq": [{"q": "Mitkä ovat kaivojen puukansien edut?", "a": ["Puukannet ovat esteettisiä, antavat luonnollisen eristyksen ja sopivat ihanteellisesti ympäristöihin, joissa halutaan välttää sähkönjohtavuutta."]}, {"q": "Millaisissa ympäristöissä kaivojen puukansia käytetään?", "a": ["Puukansia käytetään usein metroissa, kaapelikanavoinneissa ja luonnonsuojelualueilla, joissa tarvitaan luonnollista ulkonäköä ja vähäistä johtavuutta."]}, {"q": "Miten kaivojen puukansia huolletaan?", "a": ["Puukannet vaativat perushuoltoa kestääkseen pitkään, mihin kuuluu ruuvien tarkastaminen ja tarvittaessa pintakäsittely."]}, {"q": "Ovatko puukannet kyllästettyjä?", "a": ["Kyllä, puukantemme on painekyllästetty kestämään kosteutta ja kulutusta ajan mittaan."]}, {"q": "Mikä on kaapelikaappitason tarkoitus?", "a": ["Kaapelikaappitaso antaa kaapelikaapeille vakaan ja turvallisen perustan, joka suojaa niitä maakosteudelta, tärinältä ja muilta vaurioilta."]}, {"q": "Missä koissa kaapelikaappitasoja on saatavilla?", "a": ["Tarjoamme vakiopituudet 2000 mm ja 3000 mm sekä mittatilausleveydet 1000 mm:stä 9000 mm:iin."]}, {"q": "Kestävätkö tasot korroosiota?", "a": ["Kyllä, tasomme on kuumasinkitty standardin SS-EN ISO 1461 mukaisesti pitkäaikaista korroosiosuojaa varten."]}, {"q": "Miten kaapelikaappitaso asennetaan?", "a": ["Tasot on helppo asentaa, ja niiden mukana toimitetaan selkeät ohjeet turvallista asennusta ja vakautta varten."]}, {"q": "Mikä on kaapelikaivon merkintäkilven tarkoitus?", "a": ["Kaapelikaivon merkintäkilpi varmistaa kaivojen ja kaapelien selkeän ja helpon tunnistamisen, mikä helpottaa huoltoa ja parantaa turvallisuutta."]}, {"q": "Mistä materiaaleista merkintäkilvet on tehty?", "a": ["Merkintälaattamme on valmistettu kestävästä, säänkestävästä, ruostumattomasta haponkestävästä teräksestä, joka säilyttää luettavuutensa ajan mittaan."]}, {"q": "Onko kaapelikaivon merkintäkilpi helppo asentaa?", "a": ["Kyllä, merkintäkilvet on helppo asentaa, ja ne voidaan kiinnittää monenlaisiin pintoihin. Asennusohjeet toimitetaan tuotteen mukana."]}, {"q": "Missä koissa merkintälaattoja on saatavilla?", "a": ["Tarjoamme merkintälaattoja eri kokoina Trafikverketin piirustusten mukaisesti, jotta ne sopivat sekä pieniin asennuksiin että laajempiin kaapelikaivoverkostoihin."]}, {"q": "Mikä on kaivon hankaussuojan tarkoitus?", "a": ["Hankaussuoja suojaa kaapeleita ja muita laitteita kulumiselta ja vaurioilta, mikä pidentää niiden käyttöikää ja vähentää käyttökatkosten riskiä."]}, {"q": "Mistä materiaaleista hankaussuojat valmistetaan?", "a": ["Hankaussuojamme ovat pääasiassa kulutusta kestävää kumimattoa ja muita joustavia materiaaleja, jotka on sovitettu erityyppisiin kaivoihin ja asennuksiin."]}, {"q": "Miten hankaussuoja asennetaan?", "a": ["Hankaussuojat on helppo asentaa, ja niiden mukana toimitetaan selkeät ohjeet oikeaa asennusta varten kaivoihin ja kaapeliläpivienteihin."]}, {"q": "Missä koissa kumimattoa on saatavilla?", "a": ["Tarjoamme hankaussuojia eri kokoina ja paksuuksina erityisiin asennustarpeisiin ja tiloihin."]}]}}, "ent": {"status": "utkast", "sources": [], "words": 122, "faqWords": 0, "check": "Luonnos alakategorioiden teksteistä.", "sv": {"intro": "Produkter för mark, vatten och avlopp: brunnar, pumpar och pumphus, fett- och oljeavskiljare, glasfibertankar, tryckrör i PE, förhöjningsringar, stödmurar, markgaller och plastspont.", "introDraft": true, "blocks": [{"t": "h3", "x": "Vatten och avlopp", "d": true}, {"t": "p", "x": "Vattenmätarbrunnar, bevattningsbrunnar och dagvattenbrunnar i polyeten. Pumpar för borrade och grävda brunnar, pumpbrunnar och isolerade pumphus. Fett- och oljeavskiljare för mark och inomhus, samt slutna tankar och minireningsverk i glasfiber.", "d": true}, {"t": "h3", "x": "Rör och brunnsdelar", "d": true}, {"t": "p", "x": "Tryckrör och rördelar i polyeten (PE) för bland annat vattenförsörjning och avlopp. Förhöjningsringar och passdelar i betong för att få brunnens topp till rätt höjd.", "d": true}, {"t": "h3", "x": "Mark och anläggning", "d": true}, {"t": "p", "x": "Stödmurar och L-stöd i betong, markgaller och trädgropsfundament i gjutjärn, plastspont för vattentäta spontväggar och sjöledningsvikter i betong.", "d": true}, {"t": "p", "x": "Flera produkter i kategorin offereras efter behov. Ring oss på 0920-52 00 56 eller begär offert.", "d": true}], "faq": []}, "fi": {"intro": "Tuotteita maarakentamiseen sekä vesi- ja viemärihuoltoon: kaivot, pumput ja pumppukopit, rasva- ja öljynerottimet, lasikuitusäiliöt, PE-paineputket, korotusrenkaat, tukimuurit, puunjuuriritilät ja muoviponttilevyt.", "introDraft": true, "h": "Tietoa urakoinnista ja maarakennuksesta", "blocks": [{"t": "h3", "x": "Vesi ja viemäri", "d": true}, {"t": "p", "x": "Polyeteeniset vesimittarikaivot, kastelukaivot ja hulevesikaivot. Pumput porakaivoihin ja kaivettuihin kaivoihin, pumppaamot ja eristetyt pumppukopit. Rasva- ja öljynerottimet maahan ja sisätiloihin sekä lasikuituiset umpisäiliöt ja pienpuhdistamot.", "d": true}, {"t": "h3", "x": "Putket ja kaivon osat", "d": true}, {"t": "p", "x": "Polyeteeniset (PE) paineputket ja putkenosat muun muassa vedenjakeluun ja viemäröintiin. Betoniset korotusrenkaat ja sovitusrenkaat, joilla kaivon yläosa saadaan oikealle korkeudelle.", "d": true}, {"t": "h3", "x": "Maa- ja infrarakentaminen", "d": true}, {"t": "p", "x": "Betoniset tukimuurit ja L-tukimuurit, valurautaiset puunjuuriritilät ja puukuopan reunatuet, muoviponttilevyt vesitiiviisiin ponttiseiniin sekä betoniset vesistöputken painoelementit.", "d": true}, {"t": "p", "x": "Monista kategorian tuotteista tehdään tarjous tarpeen mukaan. Soita meille numeroon 0920-52 00 56 tai pyydä tarjous.", "d": true}], "faq": []}}, "ent/brunnar": {"status": "befintlig + utkast", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/brunnar-vatten-och-avlopp/vattenmatarbrunnar", "name": "Vattenmätarbrunnar", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/brunnar-vatten-och-avlopp", "name": "Brunnar Vatten och Avlopp", "use": "ingen text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/brunnar-vatten-och-avlopp/dagvattenbrunnar", "name": "Dagvattenbrunnar", "use": "ingen text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/brunnar-vatten-och-avlopp/bevattningsbrunn", "name": "Bevattningsbrunnar", "use": "ingen text"}], "words": 127, "faqWords": 0, "check": "Lyhyt vanha teksti + luonnoslisäys tuotekuvauksista.", "sv": {"intro": "Vattenmätarbrunn tillverkat i Polyeten, isolerat lock, vattentät, för utomhusbruk med upplyftningsbar vattenslang. Botten är svetsad och hela slangpaketet är utbytbart vid behov.", "introDraft": false, "blocks": [{"t": "h3", "x": "Vattenmätarbrunnar"}, {"t": "p", "x": "Flexibla vattenslangar gör det möjligt att lyfta upp hela mätarkonsolen via en lyftanordning. Livsmedelsgodkända vattenslangar."}, {"t": "h3", "x": "Bevattnings- och dagvattenbrunnar", "d": true}, {"t": "p", "x": "Bevattningsbrunnar och bevattningsbetäckningar i polyeten med slangkopplingar och avstängningsventiler, för trädgårdar och golfbanor. Bevattningsbrunnen LS 630 är låsbar och rymmer upp till 50 meter slang.", "d": true}, {"t": "p", "x": "Dagvattenbrunnen leder bort ytvatten och är utformad så att löv och växtdelar inte täpper igen den. Locket har belastningsklass A15, och överdelen är teleskopisk och kan justeras till önskad höjd.", "d": true}, {"t": "h3", "x": "Fler lösningar för vattenmätare", "d": true}, {"t": "p", "x": "Utöver vattenmätarbrunnen med upplyftningsbar slang finns vattenmätarbrunn för nedstigning (höjd 2 000-3 000 mm) och vattenmätarlåda med isolerat lock för sommarbostäder där ledningarna töms inför vintern.", "d": true}], "faq": []}, "fi": {"intro": "Polyeteenistä valmistettu vesimittarikaivo, eristetty kansi, vesitiivis, ulkokäyttöön, ylös nostettavalla vesiletkulla. Pohja on hitsattu, ja koko letkupaketti on tarvittaessa vaihdettavissa.", "introDraft": false, "h": "Tietoa vesi- ja viemärikaivoista", "blocks": [{"t": "h3", "x": "Vesimittarikaivot"}, {"t": "p", "x": "Joustavien vesiletkujen ansiosta koko mittarikonsoli voidaan nostaa ylös nostolaitteen avulla. Elintarvikehyväksytyt vesiletkut."}, {"t": "h3", "x": "Kastelu- ja hulevesikaivot", "d": true}, {"t": "p", "x": "Polyeteeniset kastelukaivot ja kastelukannet letkuliittimillä ja sulkuventtiileillä puutarhoihin ja golfkentille. Kastelukaivo LS 630 on lukittava, ja siihen mahtuu jopa 50 metriä letkua.", "d": true}, {"t": "p", "x": "Hulevesikaivo johtaa pois pintavedet, ja se on suunniteltu niin, etteivät lehdet ja kasvinosat tuki sitä. Kannen kuormitusluokka on A15, ja yläosa on teleskooppinen ja säädettävissä haluttuun korkeuteen.", "d": true}, {"t": "h3", "x": "Lisää ratkaisuja vesimittareille", "d": true}, {"t": "p", "x": "Ylös nostettavalla letkulla varustetun vesimittarikaivon lisäksi saatavilla on vesimittarikaivo, johon voi laskeutua (korkeus 2 000-3 000 mm), sekä eristetyllä kannella varustettu vesimittarilaatikko kesäasunnoille, joissa putket tyhjennetään talveksi.", "d": true}], "faq": []}}, "ent/pump": {"status": "kombinerad", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/pumpar", "name": "Pumpar och Pumpbrunnar", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/brunnsoverbyggnad-pumphus", "name": "Brunnsöverbyggnad/Pumphus", "use": "text"}], "words": 384, "faqWords": 0, "check": "Kaksi tekstiä yhdistetty; pumphus-tekstin rivitys korjattu. Pumphus-teksti alkaa kesken (\"Den mellanliggande isoleringen\"): SB täydentää alun.", "sv": {"intro": "Pumpar till både borrade och grävda brunnar, dränkbara länspumpar samt pumpbrunnar.", "introDraft": false, "blocks": [{"t": "h3", "x": "Pumpbrunnar: effektiva lösningar för vattenhantering"}, {"t": "p", "x": "På Svenska Brunnslock är vi specialiserade på att erbjuda hållbara och pålitliga lösningar för vattenhantering. Våra pumpbrunnar är utformade för att möta de krävande behoven hos såväl privata fastigheter som större infrastrukturprojekt. Men vad är en pumpbrunn, och vilka fördelar erbjuder den för effektiv vattenhantering?"}, {"t": "h4", "x": "Vad är pumpbrunnar?"}, {"t": "p", "x": "Pumpbrunnar är installationer som används för att effektivt hantera och transportera vatten och andra vätskor från en plats till en annan. De är avgörande komponenter i vattenhanteringssystem, särskilt där vatten måste pumpas från lägre liggande områden till högre, eller där det är nödvändigt att övervinna gravitationens begränsningar. Våra pumpbrunnar är tillverkade av högkvalitativa material som säkerställer långvarig hållbarhet och pålitlig prestanda under tuffa förhållanden."}, {"t": "h4", "x": "Fördelar med Svenska Brunnslocks pumpbrunnar"}, {"t": "p", "x": "Att välja pumpbrunnar från Svenska Brunnslock innebär flera fördelar:"}, {"t": "ul", "items": ["Effektivitet: Våra pumpbrunnar är designade för att maximera effektiviteten i vattenflöden, vilket minimerar energiförbrukning och ökar systemets övergripande effektivitet.", "Pålitlighet: Tillverkade med robusta material och avancerad teknologi, våra pumpbrunnar står emot korrosion, slitage och andra miljöpåverkningar som kan försämra funktionaliteten över tid.", "Anpassningsbarhet: Vi erbjuder pumpbrunnar i olika storlekar och konfigurationer för att passa specifika behov och applikationer, från enkla hushållsinstallationer till komplexa industriella system.", "Enkel underhåll: Designade för enkel åtkomst och underhåll, vilket minskar driftstopp och underhållskostnader."]}, {"t": "h4", "x": "Välja rätt pumpbrunn"}, {"t": "p", "x": "Att välja rätt pumpbrunn är avgörande för att säkerställa optimal prestanda och kostnadseffektivitet. På Svenska Brunnslock hjälper vi dig att analysera dina behov och rekommenderar den mest lämpliga lösningen baserat på din specifika situation och de tekniska kraven. Vårt team av experter är redo att erbjuda rådgivning och stöd genom hela urvals- och installationsprocessen."}, {"t": "h4", "x": "Investera i pumpbrunnar från Svenska Brunnslock"}, {"t": "p", "x": "Att investera i denna produkt från Svenska Brunnslock är att säkerställa en långsiktig lösning för dina vattenhanteringsbehov. Med vår expertis och högkvalitativa produkter kan du vara säker på att du får en pålitlig och hållbar installation som kommer att tjäna din fastighet eller ditt projekt väl över tid."}, {"t": "p", "x": "Kontakta oss idag för att utforska vårt sortiment av pumpbrunnar och börja din väg mot effektivare och säkrare vattenhantering. Med Svenska Brunnslock får du inte bara produkter av högsta kvalitet, utan också en partner som är engagerad i din framgång."}, {"t": "h3", "x": "Brunnsöverbyggnad och pumphus"}, {"t": "p", "x": "isoleringen består av 60 mm polyuretanskum. byggnaden enkelt lyftas av."}], "faq": []}, "fi": {"intro": "Pumput sekä porakaivoihin että kaivettuihin kaivoihin, upotettavat tyhjennyspumput sekä pumppaamot.", "introDraft": false, "h": "Tietoa pumppaamoista ja pumpuista", "blocks": [{"t": "h3", "x": "Pumppaamot: tehokkaita ratkaisuja vedenhallintaan"}, {"t": "p", "x": "Svenska Brunnslock on erikoistunut tarjoamaan kestäviä ja luotettavia ratkaisuja vedenhallintaan. Pumppaamomme on suunniteltu vastaamaan sekä yksityiskiinteistöjen että suurempien infrastruktuurihankkeiden vaativiin tarpeisiin. Mutta mikä pumppaamo on, ja mitä etuja se tarjoaa tehokkaassa vedenhallinnassa?"}, {"t": "h4", "x": "Mitä pumppaamot ovat?"}, {"t": "p", "x": "Pumppaamot ovat laitteistoja, joilla vettä ja muita nesteitä käsitellään ja siirretään tehokkaasti paikasta toiseen. Ne ovat ratkaisevan tärkeitä osia vedenhallintajärjestelmissä, erityisesti silloin, kun vettä on pumpattava alempana sijaitsevilta alueilta ylemmäs tai kun on tarpeen voittaa painovoiman rajoitukset. Pumppaamomme on valmistettu laadukkaista materiaaleista, jotka varmistavat pitkäaikaisen kestävyyden ja luotettavan toimivuuden vaativissa olosuhteissa."}, {"t": "h4", "x": "Svenska Brunnslockin pumppaamojen edut"}, {"t": "p", "x": "Svenska Brunnslockin pumppaamojen valitseminen tuo useita etuja:"}, {"t": "ul", "items": ["Tehokkuus: Pumppaamomme on suunniteltu maksimoimaan vesivirtojen tehokkuus, mikä minimoi energiankulutuksen ja parantaa järjestelmän kokonaistehokkuutta.", "Luotettavuus: Tukevista materiaaleista ja edistyneellä teknologialla valmistetut pumppaamomme kestävät korroosiota, kulumista ja muita ympäristövaikutuksia, jotka voivat ajan mittaan heikentää toimivuutta.", "Sovitettavuus: Tarjoamme pumppaamoja eri kokoina ja kokoonpanoina erityistarpeisiin ja käyttökohteisiin, yksinkertaisista kotitalousasennuksista monimutkaisiin teollisuusjärjestelmiin.", "Helppo huolto: Suunniteltu helppoa pääsyä ja huoltoa varten, mikä vähentää käyttökatkoja ja huoltokustannuksia."]}, {"t": "h4", "x": "Oikean pumppaamon valinta"}, {"t": "p", "x": "Oikean pumppaamon valitseminen on ratkaisevan tärkeää optimaalisen toimivuuden ja kustannustehokkuuden varmistamiseksi. Svenska Brunnslockilla autamme sinua analysoimaan tarpeesi ja suosittelemme sopivinta ratkaisua juuri sinun tilanteesi ja teknisten vaatimusten perusteella. Asiantuntijatiimimme on valmis tarjoamaan neuvontaa ja tukea koko valinta- ja asennusprosessin ajan."}, {"t": "h4", "x": "Investoi Svenska Brunnslockin pumppaamoihin"}, {"t": "p", "x": "Investoimalla tähän Svenska Brunnslockin tuotteeseen varmistat pitkäaikaisen ratkaisun vedenhallintatarpeisiisi. Asiantuntemuksemme ja laadukkaiden tuotteidemme ansiosta voit olla varma, että saat luotettavan ja kestävän asennuksen, joka palvelee kiinteistöäsi tai hankettasi hyvin pitkään."}, {"t": "p", "x": "Ota meihin yhteyttä jo tänään, tutustu pumppaamovalikoimaamme ja ota ensimmäinen askel kohti tehokkaampaa ja turvallisempaa vedenhallintaa. Svenska Brunnslockilta saat paitsi laadultaan huippuluokan tuotteita myös kumppanin, joka on sitoutunut menestykseesi."}, {"t": "h3", "x": "Kaivon päällysrakenne ja pumppukoppi"}, {"t": "p", "x": "Eristys koostuu 60 mm:n polyuretaanivaahdosta. Rakennelman voi nostaa helposti pois paikaltaan."}], "faq": []}}, "ent/avskiljare": {"status": "befintlig", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/fettavskiljare-oljeavskiljare", "name": "FETTAVSKILJARE & OLJEAVSKILJARE", "use": "text"}], "words": 109, "faqWords": 0, "check": "Teksti sellaisenaan.", "sv": {"intro": "Vi erbjuder både enklare fettavskiljare för mark och inomhusinstallation och helt automatiska fettavskiljare som sköter hela rengöringsprocessen från början till slut.", "introDraft": false, "blocks": [{"t": "h3", "x": "Fettavskiljare"}, {"t": "p", "x": "Både de markförlagda och inomhusinstallerade avskiljarna kan utrustas med flera olika tillbehör som avskiljarlarm, styrenheter för rengöring, förlängningshalsar för att få rätt markdjup och färdiga installationskit."}, {"t": "p", "x": "Större fettavskiljare finns att tillgå även för montering utomhus begär offert"}, {"t": "h4", "x": "Oljeavskiljare"}, {"t": "p", "x": "Oljeavskiljarna är tillverkade av hög kvalitet och är anpassade allt från den lilla verkstaden till större tvättanläggningar eller parkeringar. Programmet innehåller ett stort spann av storlekar och levereras helt kompletta. Oljeavskiljarna finns med integrerat eller separat slamfång, som klass 1 eller 2."}, {"t": "p", "x": "Andra oljeavskiljare finns att tillgå begär offert"}], "faq": []}, "fi": {"intro": "Tarjoamme sekä yksinkertaisempia rasvanerottimia maahan ja sisäasennukseen että täysin automaattisia rasvanerottimia, jotka hoitavat koko puhdistusprosessin alusta loppuun.", "introDraft": false, "h": "Tietoa rasva- ja öljynerottimista", "blocks": [{"t": "h3", "x": "Rasvanerottimet"}, {"t": "p", "x": "Sekä maahan asennettavat että sisätiloihin asennettavat erottimet voidaan varustaa useilla eri lisävarusteilla, kuten erotinhälyttimillä, puhdistuksen ohjausyksiköillä, jatkokauluksilla oikean asennussyvyyden saavuttamiseksi ja valmiilla asennussarjoilla."}, {"t": "p", "x": "Suurempia rasvanerottimia on saatavilla myös ulkoasennukseen, pyydä tarjous"}, {"t": "h4", "x": "Öljynerottimet"}, {"t": "p", "x": "Öljynerottimet ovat korkealaatuisia, ja ne on sovitettu kaikkeen pienestä korjaamosta suurempiin pesulaitoksiin tai pysäköintialueisiin. Valikoimassa on laaja kokohaarukka, ja erottimet toimitetaan täysin valmiina. Öljynerottimia on saatavilla integroidulla tai erillisellä lietepesällä, luokan 1 tai 2 erottimina."}, {"t": "p", "x": "Muita öljynerottimia on saatavilla, pyydä tarjous"}], "faq": []}}, "ent/tankar": {"status": "befintlig + utkast", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/glasfibertankar", "name": "Glasfibertankar", "use": "text"}], "words": 86, "faqWords": 0, "check": "Yhden lauseen vanha teksti + luonnoslisäys tuotekuvauksista.", "sv": {"intro": "Vi kan erbjuda glasfibertankar i önskad storlek till olika ändamål.", "introDraft": false, "blocks": [{"t": "h3", "x": "Slutna tankar och minireningsverk", "d": true}, {"t": "p", "x": "Om det inte är lämpligt att släppa ut avloppsvattnet på tomten kan det ledas till en sluten avloppstank som töms med slambil. Vi levererar glasfibertankar från 3 000 upp till 65 000 liter.", "d": true}, {"t": "p", "x": "Slutna avloppstankar finns i 3,0 och 5,2 m³ med tömningsrör och nivåvakt. Minireningsverken GRAF och Kemik är kompakta, har inga pumpar i tanken och behöver slamtömning 1-2 gånger per år. Tankar och minireningsverk offereras efter behov.", "d": true}], "faq": []}, "fi": {"intro": "Voimme tarjota lasikuitusäiliöitä halutun kokoisina eri käyttötarkoituksiin.", "introDraft": false, "h": "Tietoa lasikuitusäiliöistä", "blocks": [{"t": "h3", "x": "Umpisäiliöt ja pienpuhdistamot", "d": true}, {"t": "p", "x": "Jos jätevettä ei ole sopivaa johtaa tontille, se voidaan johtaa umpisäiliöön, joka tyhjennetään imuautolla. Toimitamme lasikuitusäiliöitä 3 000 litrasta aina 65 000 litraan.", "d": true}, {"t": "p", "x": "Jäteveden umpisäiliöitä on saatavilla 3,0 ja 5,2 m³:n kokoisina tyhjennysputkella ja pinnankorkeusvahdilla. GRAF- ja Kemik-pienpuhdistamot ovat kompakteja, säiliössä ei ole pumppuja, ja ne tarvitsevat lietteen tyhjennyksen 1-2 kertaa vuodessa. Säiliöistä ja pienpuhdistamoista tehdään tarjous tarpeen mukaan.", "d": true}], "faq": []}}, "ent/tryckror": {"status": "befintlig", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/tryckror-pe-ror", "name": "Tryckrör/PE-rör", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/tryckror-pe-ror/vatten", "name": "Vatten", "use": "ingen text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/tryckror-pe-ror/avlopp", "name": "Avlopp", "use": "ingen text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/tryckror-pe-ror/industri", "name": "Industri", "use": "ingen text"}], "words": 122, "faqWords": 0, "check": "Standardivuodet (ISO 9001:2009, 14001:2005) ja Suomen Kaivotarvikkeet Oy -maininta ajantasaisuus.", "sv": {"intro": "Vi har ett komplett sortiment av rör och rördelar i Polyeten PE. Tillverkning sker i Polen hos vår samarbetspartner ELPLAST +.", "introDraft": false, "blocks": [{"t": "p", "x": "Vi har tillsammans med vårt dotterbolag i Finland, Suomen Kaivotarvikkeet OY försäljningsagenturen i Norden på hela ELPLAST+ sortiment."}, {"t": "p", "x": "I sortimentet finns Tryckrör (Polyetenrör PE) och rördelar till:"}, {"t": "ul", "items": ["Vattenförsörjning.", "Avloppssystem.", "Kabelskyddsrör.", "Rör för gruvindustrin.", "Rörsystem till mudderverk med flytkroppar.", "Rörsystem för hockey rinkar och snötillverkning.", "Kulvert rör."]}, {"t": "p", "x": "Produkterna är kvalitetssäkrade enligt PN-EN ISO 9001:2009 och PN-EN ISO 14001:2005."}, {"t": "p", "x": "Vi har även tryckrör i PE100 RC-material, som är certifierat av PAS 1075, har exempelvis 17 gånger högre kravnivå än normen vad gäller motståndskraft mot långsam spricktillväxt (SCG)."}, {"t": "p", "x": "Våra kunder sträcker sig från återförsäljare, grossister och större entreprenörer och industrier."}], "faq": []}, "fi": {"intro": "Meillä on kattava valikoima polyeteenistä (PE) valmistettuja putkia ja putkenosia. Tuotteet valmistaa Puolassa yhteistyökumppanimme ELPLAST +.", "introDraft": false, "h": "Tietoa paineputkista", "blocks": [{"t": "p", "x": "Meillä on yhdessä Suomen tytäryhtiömme Suomen Kaivotarvikkeet OY:n kanssa koko ELPLAST+-valikoiman myyntiedustus Pohjoismaissa."}, {"t": "p", "x": "Valikoimassa on paineputkia (PE-polyeteeniputket) ja putkenosia seuraaviin käyttökohteisiin:"}, {"t": "ul", "items": ["Vedenjakelu.", "Viemärijärjestelmät.", "Kaapelinsuojaputket.", "Putket kaivosteollisuuteen.", "Kellukkeilla varustetut putkijärjestelmät ruoppaajiin.", "Putkijärjestelmät jääkiekkokaukaloihin ja lumetukseen.", "Kanaaliputket."]}, {"t": "p", "x": "Tuotteiden laatu on varmistettu standardien PN-EN ISO 9001:2009 ja PN-EN ISO 14001:2005 mukaisesti."}, {"t": "p", "x": "Meillä on myös PE100 RC -materiaalista valmistettuja paineputkia, jotka on sertifioitu PAS 1075 -määrittelyn mukaisesti; niiden vaatimustaso hitaan särönkasvun (SCG) kestävyydessä on esimerkiksi 17 kertaa normia korkeampi."}, {"t": "p", "x": "Asiakkaitamme ovat jälleenmyyjät, tukkukaupat sekä suuremmat urakoitsijat ja teollisuusyritykset."}], "faq": []}}, "ent/forhojning": {"status": "kombinerad", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/betonglock/forhojningsringar-och-passdelar", "name": "Förhöjningsringar och passdelar", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/brunnslock/forhojningsringar-i-betong", "name": "Förhöjningsringar i betong", "use": "text+faq"}], "words": 67, "faqWords": 94, "check": "Kaksi lyhyttä tekstiä ja FAQ yhdistetty.", "sv": {"intro": "Passdelar eller förhöjningsringar i betong används i första hand för att få brunnens topp eller brunnslocket till önskad höjd.", "introDraft": false, "blocks": [{"t": "p", "x": "De används även som lastfördelare för brunnar och vertikala rör som inte själva kan ta upp de laster som brunnslock eller betäckningar utsätts för."}, {"t": "p", "x": "Om brunnen ligger för lågt och man vill höja brunnen då används förhöjningsringar i betong."}, {"t": "p", "x": "Finns även en modell av lätt brunnslock med förhöjningsring."}], "faq": [{"q": "Vad används förhöjningsringar i betong till?", "a": ["Förhöjningsringar används för att höja brunnen till en önskad höjd om den ligger för lågt."]}, {"q": "Vilka storlekar finns för förhöjningsringar i betong?", "a": ["Vi erbjuder förhöjningsringar i olika storlekar från 600 mm upp till 800 mm i diameter och höjder från 40 mm till 100 mm."]}, {"q": "Kan jag installera förhöjningsringen själv?", "a": ["Förhöjningsringar i betong kan installeras av de flesta med viss erfarenhet av byggarbete, men vid osäkerhet rekommenderas professionell hjälp."]}, {"q": "Är betongförhöjningsringar väderbeständiga?", "a": ["Ja, våra betongförhöjningsringar är tillverkade för att tåla olika väderförhållanden och är anpassade för lång hållbarhet."]}]}, "fi": {"intro": "Betonisia sovitusrenkaita tai korotusrenkaita käytetään ensisijaisesti, kun kaivon yläosa tai kaivonkansi halutaan saada halutulle korkeudelle.", "introDraft": false, "h": "Tietoa korotusrenkaista", "blocks": [{"t": "p", "x": "Niitä käytetään myös kuormanjakajina kaivoissa ja pystyputkissa, jotka eivät itse pysty ottamaan vastaan kaivonkansiin tai kansistoihin kohdistuvia kuormia."}, {"t": "p", "x": "Jos kaivo on liian matalalla ja sitä halutaan korottaa, käytetään betonisia korotusrenkaita."}, {"t": "p", "x": "Saatavilla on myös kevyt kaivonkansimalli korotusrenkaalla."}], "faq": [{"q": "Mihin betonisia korotusrenkaita käytetään?", "a": ["Korotusrenkailla kaivo korotetaan haluttuun korkeuteen, jos se on liian matalalla."]}, {"q": "Missä koissa betonisia korotusrenkaita on saatavilla?", "a": ["Tarjoamme korotusrenkaita eri kokoina halkaisijaltaan 600 mm:stä 800 mm:iin ja korkeudeltaan 40 mm:stä 100 mm:iin."]}, {"q": "Voinko asentaa korotusrenkaan itse?", "a": ["Useimmat, joilla on jonkin verran kokemusta rakennustöistä, voivat asentaa betoniset korotusrenkaat, mutta epävarmoissa tilanteissa suositellaan ammattilaisen apua."]}, {"q": "Kestävätkö betoniset korotusrenkaat säätä?", "a": ["Kyllä, betoniset korotusrenkaamme on valmistettu kestämään erilaisia sääolosuhteita, ja ne on suunniteltu pitkäikäisiksi."]}]}}, "ent/stodmurar": {"status": "kombinerad", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/stodmurar-l-stod/stenbekladd-stodmur", "name": "Stenbeklädd stödmur", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/stodmurar-l-stod/l-stod-i-betong-90-kn", "name": "L-stöd i betong 90 kN", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/stodmurar-l-stod", "name": "Stödmurar/L-stöd", "use": "ingen text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/stodmurar-l-stod/l-stod-i-betong-5-kn", "name": "L-stöd i betong 5 kN", "use": "ingen text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/stodmurar-l-stod/l-stod-i-betong-20-kn", "name": "L-stöd i betong 20 kN", "use": "ingen text"}], "words": 75, "faqWords": 0, "check": "Kaksi lyhyttä tekstiä yhdistetty.", "sv": {"intro": "Lättmonterade stödmurar som är utvecklade för att klara kuperade markområden och stå emot tidens påverkan. Produkterna tillverkas av högkvalitativa material för lång hållbarhet.", "introDraft": false, "blocks": [{"t": "h3", "x": "Stenbeklädd stödmur"}, {"t": "p", "x": "Varje lösning anpassas efter kundens behov, användningsområde och omgivande miljö."}, {"t": "h3", "x": "L-stöd i betong"}, {"t": "p", "x": "Lättmonterade L-stöd som är utvecklade för att klara kuperade markområden och stå emot långvarig belastning. Produkterna tillverkas av högkvalitativa material för god hållbarhet."}, {"t": "p", "x": "Belastning: Trafiklast 22 kN/m², vilket motsvarar en punktlast på 90 kN."}], "faq": []}, "fi": {"intro": "Helposti asennettavia tukimuureja, jotka on kehitetty kestämään mäkisiä maastoja ja ajan vaikutuksia. Tuotteet valmistetaan laadukkaista materiaaleista, joten ne kestävät pitkään.", "introDraft": false, "h": "Tietoa tukimuureista", "blocks": [{"t": "h3", "x": "Kiviverhoiltu tukimuuri"}, {"t": "p", "x": "Jokainen ratkaisu sovitetaan asiakkaan tarpeiden, käyttötarkoituksen ja ympäröivän ympäristön mukaan."}, {"t": "h3", "x": "Betoniset L-tukimuurit"}, {"t": "p", "x": "Helposti asennettavia L-tukimuureja, jotka on kehitetty kestämään mäkisiä maastoja ja pitkäaikaista kuormitusta. Tuotteet valmistetaan laadukkaista materiaaleista hyvän kestävyyden takaamiseksi."}, {"t": "p", "x": "Kuormitus: Liikennekuorma 22 kN/m², mikä vastaa 90 kN:n pistekuormaa."}], "faq": []}}, "ent/geo": {"status": "kombinerad", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/markgaller-traskydd-tradgardsfundament", "name": "Markgaller", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/markgaller-traskydd-tradgardsfundament/tradgardsfundament", "name": "Trädgropsfundament", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/markgaller-traskydd-tradgardsfundament/markgaller", "name": "Markgaller", "use": "sammanfogad"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/geotextiler-markforstarkning", "name": "Geotextiler Markförstärkning", "use": "ingen text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/markgaller-traskydd-tradgardsfundament/tradskydd", "name": "Trädskydd", "use": "ingen text"}], "words": 106, "faqWords": 0, "check": "Markgaller-teksti katkeaa nykyisessä kaupassa (\"läggs på\"); SB täydentää. Geotekstiileistä ei ole tekstiä.", "sv": {"intro": "Markgaller används för att skydda trädets rötter och hindra jorden för att bli alltför kompakt. Genom att jorden behålls ”luftigt” så får trädet lättare luft och vatten vilket underlättar för trädets välmående.", "introDraft": false, "blocks": [{"t": "h3", "x": "Markgaller"}, {"t": "p", "x": "Tillverkat i svart gjutjärn."}, {"t": "p", "x": "Gallret är kvadratiskt och finns i måtten 1500 x 1500mm och 1400 x 1400mm med ett mitthål på 700 mm, byggs samman av fyra delar och läggs på"}, {"t": "h3", "x": "Trädgropsfundament"}, {"t": "p", "x": "Trädgropsfundamentet skyddar trädets rotzon och ger kantstöd mot intilliggande beläggning. Kan med fördel användas ihop med skelettjord. Fundament och galler finns i två storlekar."}, {"t": "ul", "items": ["Längd: 1400 x bredd: 1400 höjd: 600 mm", "Längd: 1500 x bredd: 1500 höjd: 600 mm"]}], "faq": []}, "fi": {"intro": "Puunjuuriritilöitä käytetään suojaamaan puun juuria ja estämään maata tiivistymästä liikaa. Kun maa pysyy ”ilmavana”, puu saa helpommin ilmaa ja vettä, mikä edistää puun hyvinvointia.", "introDraft": false, "h": "Tietoa geotekstiileistä ja maaritilöistä", "blocks": [{"t": "h3", "x": "Puunjuuriritilä"}, {"t": "p", "x": "Valmistettu mustasta valuraudasta."}, {"t": "p", "x": "Ritilä on neliön muotoinen, ja sitä on saatavilla mitoissa 1500 x 1500 mm ja 1400 x 1400 mm, keskireikä 700 mm. Se kootaan neljästä osasta ja asetetaan paikalleen"}, {"t": "h3", "x": "Puukuopan reunatuki"}, {"t": "p", "x": "Puukuopan reunatuki suojaa puun juuristoaluetta ja antaa reunatuen viereiselle päällysteelle. Sitä voi hyvin käyttää yhdessä kivirunkoisen kasvualustan kanssa. Reunatukea ja ritilää on saatavilla kahta kokoa."}, {"t": "ul", "items": ["Pituus: 1400 x leveys: 1400 korkeus: 600 mm", "Pituus: 1500 x leveys: 1500 korkeus: 600 mm"]}], "faq": []}}, "ent/spont": {"status": "befintlig + utkast", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/plastspont", "name": "Plastspont", "use": "text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/sjoledningsvikter", "name": "Sjöledningsvikter", "use": "ingen text"}], "words": 96, "faqWords": 0, "check": "Lyhyt vanha teksti + luonnoslisäys sjöledningsvikter-tuotekuvauksista.", "sv": {"intro": "Plastspont kan användas för hållbara och vattentäta spontväggar i myrar, sjöar eller hamnar. En utmärkt produkt för att återskapa våtmarker.", "introDraft": false, "blocks": [{"t": "p", "x": "Livslängd på 50 år"}, {"t": "p", "x": "Plastspont är korrosions- och UV-beständig och kan vibreras, tryckas eller grävas ner. Den kan ersätta stålspont och används bland annat i hamnar, dammar, kanaler, diken och för att stabilisera slänter.", "d": true}, {"t": "h3", "x": "Sjöledningsvikter", "d": true}, {"t": "p", "x": "Sjöledningsvikter i betong håller rörledningar på plats på botten. Små vikter finns för rör Ø40, Ø50 och Ø63 mm och levereras med cellplaststoppning och buntband. För rördimensioner 315-800 mm finns vikter som låses med träkilar och levereras med skavskydd.", "d": true}], "faq": []}, "fi": {"intro": "Muoviponttilevyillä voidaan tehdä kestäviä ja vesitiiviitä ponttiseiniä soille, järviin tai satamiin. Erinomainen tuote kosteikkojen ennallistamiseen.", "introDraft": false, "h": "Tietoa muoviponttilevyistä ja vesijohtopainoista", "blocks": [{"t": "p", "x": "Käyttöikä 50 vuotta"}, {"t": "p", "x": "Muoviponttilevy kestää korroosiota ja UV-säteilyä, ja se voidaan asentaa täryttämällä, painamalla tai kaivamalla. Se voi korvata teräsponttilevyn, ja sitä käytetään muun muassa satamissa, padoissa, kanavissa, ojissa ja luiskien vakauttamiseen.", "d": true}, {"t": "h3", "x": "Vesistöputken painoelementit", "d": true}, {"t": "p", "x": "Betoniset vesistöputken painoelementit pitävät putkilinjat paikallaan pohjassa. Pieniä painoja on saatavilla putkille Ø40, Ø50 ja Ø63 mm, ja ne toimitetaan solumuovipehmusteella ja nippusiteillä. Putkikokoihin 315-800 mm on saatavilla painoja, jotka lukitaan puukiiloilla ja toimitetaan hankaussuojalla varustettuina.", "d": true}], "faq": []}}, "ent/redskap": {"status": "utkast", "sources": [{"url": "https://www.svenskabrunnslock.se/produkt-kategori/redskap-for-hjullastare-och-gravmaskin", "name": "Redskap för hjullastare och grävmaskin", "use": "ingen text"}, {"url": "https://www.svenskabrunnslock.se/produkt-kategori/redskap-och-tillbehor/balkdragare", "name": "Balkdragare", "use": "ingen text"}], "words": 75, "faqWords": 0, "check": "Luonnos kahden tuotteen kuvauksesta. Kategorian nimi (hjullastare och grävmaskin) ei vastaa tuotteita (palkinvetäjät).", "sv": {"intro": "Stedox balkdragare håller ihop träskarvar medan du fäster dem. Det extra långa spärrhandtaget gör att en person kan rikta in och montera tunga element utan extra hjälp.", "introDraft": true, "blocks": [{"t": "h3", "x": "Två modeller", "d": true}, {"t": "ul", "items": ["Hammer Down: smidda krokar som slås in i träet och ger ett stadigt grepp direkt. En extra krok medföljer.", "Screw Down: skruvfästen som minskar risken för sprickbildning i känsliga träslag."], "d": true}, {"t": "p", "x": "Balkdragaren sätts upp på några sekunder och ger täta skarvar utan spår efter slägga i träet.", "d": true}], "faq": []}, "fi": {"intro": "Stedox-palkinvetäjä pitää puuliitokset koossa, kun kiinnität ne. Erittäin pitkän räikkäkahvan ansiosta yksi henkilö pystyy suuntaamaan ja asentamaan raskaita elementtejä ilman lisäapua.", "introDraft": true, "h": "Tietoa työlaitteista pyöräkuormaajiin ja kaivinkoneisiin", "blocks": [{"t": "h3", "x": "Kaksi mallia", "d": true}, {"t": "ul", "items": ["Hammer Down: taotut koukut, jotka lyödään puuhun ja jotka antavat heti tukevan otteen. Mukana tulee ylimääräinen koukku.", "Screw Down: ruuvikiinnikkeet, jotka vähentävät halkeilun riskiä herkissä puulajeissa."], "d": true}, {"t": "p", "x": "Palkinvetäjä asennetaan muutamassa sekunnissa, ja se antaa tiiviit liitokset ilman lekan jälkiä puussa.", "d": true}], "faq": []}}};
